# V4.0 — MULTI-TICKER ML PANEL BUILDER, READ-ONLY
# ============================================================

def _normalize_ticker_list_v40(raw_text: str) -> list[str]:
    """
    Transforme une liste utilisateur en tickers propres.
    Accepte séparateurs virgule, espace, retour ligne.
    """
    if raw_text is None:
        return []

    cleaned = (
        str(raw_text)
        .replace("\n", ",")
        .replace(";", ",")
        .replace("\t", ",")
        .replace(" ", ",")
    )

    tickers = []

    for item in cleaned.split(","):
        t = item.strip().upper()

        if not t:
            continue

        if t not in tickers:
            tickers.append(t)

    return tickers[:30]


def fetch_price_history_v40(
    ticker: str,
    period: str = "1y",
    interval: str = "1d",
) -> pd.DataFrame:
    """
    Fetch minimal OHLCV via yfinance.
    Lecture seule.
    """
    if not YFINANCE_AVAILABLE:
        return pd.DataFrame()

    try:
        raw = yf.download(
            ticker,
            period=period,
            interval=interval,
            auto_adjust=False,
            progress=False,
            threads=False,
        )

        if raw is None or raw.empty:
            return pd.DataFrame()

        if isinstance(raw.columns, pd.MultiIndex):
            raw.columns = [c[0] if isinstance(c, tuple) else c for c in raw.columns]

        raw = raw.reset_index()

        rename_map = {
            "Date": "date",
            "Datetime": "date",
            "Open": "open",
            "High": "high",
            "Low": "low",
            "Close": "close",
            "Adj Close": "adj_close",
            "Volume": "volume",
        }

        raw = raw.rename(columns=rename_map)
        raw.columns = [str(c).lower() for c in raw.columns]

        required = ["date", "open", "high", "low", "close"]

        if not all(col in raw.columns for col in required):
            return pd.DataFrame()

        for col in ["open", "high", "low", "close", "volume"]:
            if col in raw.columns:
                raw[col] = pd.to_numeric(raw[col], errors="coerce")

        raw["date"] = pd.to_datetime(raw["date"], errors="coerce")
        raw = raw.dropna(subset=["date", "open", "high", "low", "close"])
        raw = raw.sort_values("date").reset_index(drop=True)

        return raw

    except Exception:
        return pd.DataFrame()


def build_single_ticker_panel_v40(
    ticker: str,
    period: str,
    interval: str,
    horizon: int,
    pt_mult: float,
    sl_mult: float,
) -> pd.DataFrame:
    """
    Construit feature + labels pour un ticker.
    Réutilise V1/V2.
    """
    price_df = fetch_price_history_v40(
        ticker=ticker,
        period=period,
        interval=interval,
    )

    if price_df.empty:
        return pd.DataFrame()

    feature_df = prepare_ml_feature_frame_v1(price_df)

    if feature_df.empty:
        return pd.DataFrame()

    labeled = make_triple_barrier_labels_v1(
        feature_df=feature_df,
        horizon=int(horizon),
        pt_mult=float(pt_mult),
        sl_mult=float(sl_mult),
        conservative_intraday=True,
    )

    if labeled.empty:
        return pd.DataFrame()

    labeled["ticker"] = ticker
    labeled["source_period"] = period
    labeled["source_interval"] = interval

    return labeled


def build_multi_ticker_panel_v40(
    tickers: list[str],
    period: str = "1y",
    interval: str = "1d",
    horizon: int = 20,
    pt_mult: float = 1.5,
    sl_mult: float = 1.5,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """
    Construit un panel multi-tickers read-only.

    Retourne :
    - panel complet ;
    - audit par ticker.
    """
    if not tickers:
        return pd.DataFrame(), pd.DataFrame()

    panels = []
    audit_rows = []

    for ticker in tickers:
        try:
            panel = build_single_ticker_panel_v40(
                ticker=ticker,
                period=period,
                interval=interval,
                horizon=horizon,
                pt_mult=pt_mult,
                sl_mult=sl_mult,
            )

            if panel.empty:
                audit_rows.append(
                    {
                        "Ticker": ticker,
                        "Status": "KO",
                        "Rows": 0,
                        "Labels": 0,
                        "TP %": np.nan,
                        "SL %": np.nan,
                        "Timeout %": np.nan,
                        "Start": "N/A",
                        "End": "N/A",
                        "Detail": "Aucune donnée exploitable.",
                    }
                )
                continue

            labels = panel.dropna(subset=["tb_label"]).copy()
            label_count = len(labels)

            if label_count > 0:
                tp_pct = (labels["tb_label"] == 1).mean()
                sl_pct = (labels["tb_label"] == -1).mean()
                timeout_pct = (labels["tb_label"] == 0).mean()
            else:
                tp_pct = np.nan
                sl_pct = np.nan
                timeout_pct = np.nan

            start = pd.to_datetime(panel["date"], errors="coerce").min()
            end = pd.to_datetime(panel["date"], errors="coerce").max()

            status = "OK" if label_count >= 80 else "Short history"

            audit_rows.append(
                {
                    "Ticker": ticker,
                    "Status": status,
                    "Rows": len(panel),
                    "Labels": label_count,
                    "TP %": tp_pct,
                    "SL %": sl_pct,
                    "Timeout %": timeout_pct,
                    "Start": start.strftime("%Y-%m-%d") if not pd.isna(start) else "N/A",
                    "End": end.strftime("%Y-%m-%d") if not pd.isna(end) else "N/A",
                    "Detail": "Panel construit." if status == "OK" else "Historique/labels limités.",
                }
            )

            panels.append(panel)

        except Exception as e:
            audit_rows.append(
                {
                    "Ticker": ticker,
                    "Status": "Error",
                    "Rows": 0,
                    "Labels": 0,
                    "TP %": np.nan,
                    "SL %": np.nan,
                    "Timeout %": np.nan,
                    "Start": "N/A",
                    "End": "N/A",
                    "Detail": str(e)[:120],
                }
            )

    if panels:
        full_panel = pd.concat(panels, ignore_index=True)
    else:
        full_panel = pd.DataFrame()

    audit = pd.DataFrame(audit_rows)

    return full_panel, audit


def build_multi_ticker_panel_summary_v40(panel: pd.DataFrame, audit: pd.DataFrame) -> pd.DataFrame:
    """
    Résumé institutionnel du panel.
    """
    rows = []

    if audit is None or audit.empty:
        return pd.DataFrame(
            [
                {
                    "Contrôle": "Panel",
                    "Statut": "KO",
                    "Détail": "Aucun audit disponible.",
                }
            ]
        )

    ok_tickers = int((audit["Status"] == "OK").sum())
    total_tickers = len(audit)

    rows.append(
        {
            "Contrôle": "Tickers exploitables",
            "Statut": "OK" if ok_tickers >= 5 else "À surveiller",
            "Détail": f"{ok_tickers}/{total_tickers} tickers OK.",
        }
    )

    if panel is None or panel.empty:
        rows.append(
            {
                "Contrôle": "Panel rows",
                "Statut": "KO",
                "Détail": "Panel vide.",
            }
        )
        return pd.DataFrame(rows)

    label_count = int(panel["tb_label"].notna().sum()) if "tb_label" in panel.columns else 0

    rows.append(
        {
            "Contrôle": "Observations",
            "Statut": "OK" if len(panel) >= 1000 else "À surveiller",
            "Détail": f"{len(panel):,} lignes panel.",
        }
    )

    rows.append(
        {
            "Contrôle": "Labels",
            "Statut": "OK" if label_count >= 500 else "À surveiller",
            "Détail": f"{label_count:,} labels exploitables.",
        }
    )

    if "tb_label" in panel.columns and label_count > 0:
        labels = panel.dropna(subset=["tb_label"])

        tp_pct = (labels["tb_label"] == 1).mean()
        sl_pct = (labels["tb_label"] == -1).mean()
        timeout_pct = (labels["tb_label"] == 0).mean()

        rows.append(
            {
                "Contrôle": "Distribution labels panel",
                "Statut": "OK" if 0.35 <= tp_pct <= 0.60 else "À surveiller",
                "Détail": (
                    f"TP {_fmt_pct(tp_pct)} · "
                    f"SL {_fmt_pct(sl_pct)} · "
                    f"Timeout {_fmt_pct(timeout_pct)}."
                ),
            }
        )

    if "ticker" in panel.columns:
        labels_by_ticker = panel.dropna(subset=["tb_label"]).groupby("ticker").size()

        if not labels_by_ticker.empty:
            min_labels = int(labels_by_ticker.min())
            max_labels = int(labels_by_ticker.max())

            rows.append(
                {
                    "Contrôle": "Balance par ticker",
                    "Statut": "OK" if min_labels >= 50 else "À surveiller",
                    "Détail": f"Min labels/ticker {min_labels}, max {max_labels}.",
                }
            )

    rows.append(
        {
            "Contrôle": "Decision Engine",
            "Statut": "Blocked",
            "Détail": "Aucune intégration. Panel research-only.",
        }
    )

    return pd.DataFrame(rows)


def build_multi_ticker_label_distribution_v40(panel: pd.DataFrame) -> pd.DataFrame:
    """
    Distribution de labels par ticker.
    """
    if panel is None or panel.empty or "ticker" not in panel.columns or "tb_label" not in panel.columns:
        return pd.DataFrame()

    labels = panel.dropna(subset=["tb_label"]).copy()

    if labels.empty:
        return pd.DataFrame()

    rows = []

    for ticker, group in labels.groupby("ticker"):
        total = len(group)

        rows.append(
            {
                "Ticker": ticker,
                "Labels": total,
                "TP count": int((group["tb_label"] == 1).sum()),
                "SL count": int((group["tb_label"] == -1).sum()),
                "Timeout count": int((group["tb_label"] == 0).sum()),
                "TP %": (group["tb_label"] == 1).sum() / total,
                "SL %": (group["tb_label"] == -1).sum() / total,
                "Timeout %": (group["tb_label"] == 0).sum() / total,
                "Avg return": group["tb_return"].mean(),
                "Avg MFE": group["tb_mfe"].mean(),
                "Avg MAE": group["tb_mae"].mean(),
            }
        )

    return pd.DataFrame(rows).sort_values("Labels", ascending=False)


def build_multi_ticker_feature_coverage_v40(panel: pd.DataFrame) -> pd.DataFrame:
    """
    Audit de couverture des features sur panel multi-tickers.
    """
    if panel is None or panel.empty:
        return pd.DataFrame()

    feature_cols = get_eligible_feature_columns_v30(panel)

    rows = []

    for col in feature_cols:
        if col not in panel.columns:
            continue

        series = panel[col]

        rows.append(
            {
                "Feature": col,
                "Missing %": float(series.isna().mean()),
                "Unique values": int(series.nunique(dropna=True)),
                "Mean": series.mean(),
                "Std": series.std(),
                "Min": series.min(),
                "Max": series.max(),
            }
        )

    return pd.DataFrame(rows).sort_values("Missing %")


# ============================================================
# V4.1 — CROSS-SECTIONAL PURGED VALIDATION SCAFFOLD
# ============================================================

def _ensure_panel_event_dates_v41(panel: pd.DataFrame) -> pd.DataFrame:
    """
    Sécurise tb_event_start / tb_event_end sur panel multi-tickers.
    """
    if panel is None or panel.empty:
        return pd.DataFrame()

    work = panel.copy().reset_index(drop=True)

    if "date" not in work.columns:
        return pd.DataFrame()

    work["date"] = pd.to_datetime(work["date"], errors="coerce")

    if "tb_event_start" not in work.columns:
        work["tb_event_start"] = work["date"]
    else:
        work["tb_event_start"] = pd.to_datetime(work["tb_event_start"], errors="coerce")
        work["tb_event_start"] = work["tb_event_start"].fillna(work["date"])

    if "tb_event_end" not in work.columns:
        work["tb_event_end"] = pd.NaT
    else:
        work["tb_event_end"] = pd.to_datetime(work["tb_event_end"], errors="coerce")

    if "ticker" not in work.columns:
        work["ticker"] = "UNKNOWN"

    # Fallback par ticker si tb_event_end manque.
    if "tb_holding_days" in work.columns:
        fixed_parts = []

        for ticker, group in work.groupby("ticker"):
            group = group.copy().sort_values("date").reset_index(drop=True)

            for idx, row in group.iterrows():
                if not pd.isna(row.get("tb_event_end")):
                    continue

                holding = _safe_float(row.get("tb_holding_days"))

                if holding is None:
                    continue

                exit_idx = int(idx + holding)

                if 0 <= exit_idx < len(group):
                    group.loc[idx, "tb_event_end"] = group.loc[exit_idx, "date"]

            fixed_parts.append(group)

        if fixed_parts:
            work = pd.concat(fixed_parts, ignore_index=True)

    return work


def build_cross_sectional_purged_validation_v41(
    panel: pd.DataFrame,
    n_splits: int = 5,
    embargo_days: int = 5,
    min_train_size: int = 300,
    min_test_size: int = 50,
) -> pd.DataFrame:
    """
    V4.1 — Folds cross-sectional purgés.

    Logique :
    - split par dates, pas par lignes individuelles ;
    - test = tous tickers sur une tranche temporelle ;
    - train = passé uniquement ;
    - purge des events train dont tb_event_end touche la fenêtre test ;
    - embargo avant test ;
    - aucun modèle entraîné.
    """
    if panel is None or panel.empty:
        return pd.DataFrame()

    work = _ensure_panel_event_dates_v41(panel)

    if work.empty:
        return pd.DataFrame()

    required = ["ticker", "date", "tb_label", "tb_event_start", "tb_event_end"]
    missing = [col for col in required if col not in work.columns]

    if missing:
        return pd.DataFrame()

    valid = work.dropna(subset=["tb_label", "tb_event_start", "tb_event_end", "ticker"]).copy()

    if valid.empty:
        return pd.DataFrame()

    valid["tb_event_start"] = pd.to_datetime(valid["tb_event_start"], errors="coerce")
    valid["tb_event_end"] = pd.to_datetime(valid["tb_event_end"], errors="coerce")
    valid = valid.dropna(subset=["tb_event_start", "tb_event_end"])
    valid = valid.sort_values(["tb_event_start", "ticker"]).reset_index(drop=True)

    unique_dates = np.array(sorted(valid["tb_event_start"].dropna().unique()))

    if len(unique_dates) < n_splits + 20:
        return pd.DataFrame()

    initial_train_dates = max(60, int(len(unique_dates) * 0.35))

    test_dates = unique_dates[initial_train_dates:]

    if len(test_dates) < n_splits:
        return pd.DataFrame()

    date_chunks = np.array_split(test_dates, n_splits)

    rows = []
    embargo_delta = pd.Timedelta(days=int(embargo_days))

    for fold_id, chunk in enumerate(date_chunks, start=1):
        if len(chunk) == 0:
            continue

        test_start = pd.to_datetime(chunk[0])
        test_end = pd.to_datetime(chunk[-1])

        test_mask = (
            (valid["tb_event_start"] >= test_start)
            & (valid["tb_event_start"] <= test_end)
        )

        train_candidate_mask = valid["tb_event_start"] < test_start
        embargo_cutoff = test_start - embargo_delta

        train_final_mask = train_candidate_mask & (valid["tb_event_end"] < embargo_cutoff)

        train_candidates = valid.loc[train_candidate_mask].copy()
        train_final = valid.loc[train_final_mask].copy()
        test = valid.loc[test_mask].copy()

        purged_removed = len(train_candidates) - len(train_final)

        overlap_after_purge = 0

        if not train_final.empty:
            overlap_after_purge = int((train_final["tb_event_end"] >= test_start).sum())

        train_tickers = int(train_final["ticker"].nunique()) if not train_final.empty else 0
        test_tickers = int(test["ticker"].nunique()) if not test.empty else 0

        train_stats = _fold_label_stats_v2(train_final, "Train")
        test_stats = _fold_label_stats_v2(test, "Test")

        status = "OK"

        if len(train_final) < min_train_size:
            status = "Train too small"

        if len(test) < min_test_size:
            status = "Test too small"

        if overlap_after_purge > 0:
            status = "Leakage risk"

        if test_tickers < 5:
            status = "Ticker coverage weak"

        row = {
            "Fold": fold_id,
            "Test start": test_start,
            "Test end": test_end,
            "Train candidates": len(train_candidates),
            "Purged / embargo removed": purged_removed,
            "Train final": len(train_final),
            "Test size": len(test),
            "Train tickers": train_tickers,
            "Test tickers": test_tickers,
            "Overlap after purge": overlap_after_purge,
            "Embargo days": embargo_days,
            "Status": status,
        }

        row.update(train_stats)
        row.update(test_stats)

        rows.append(row)

    if not rows:
        return pd.DataFrame()

    return pd.DataFrame(rows)


def build_cross_sectional_validation_summary_v41(validation_df: pd.DataFrame) -> pd.DataFrame:
    """
    Résumé du scaffold V4.1.
    """
    if validation_df is None or validation_df.empty:
        return pd.DataFrame()

    total = len(validation_df)
    ok = int((validation_df["Status"] == "OK").sum())
    leakage = int((validation_df["Overlap after purge"] > 0).sum())

    avg_train = validation_df["Train final"].mean()
    avg_test = validation_df["Test size"].mean()
    avg_test_tickers = validation_df["Test tickers"].mean()

    rows = [
        {
            "Contrôle": "Cross-sectional folds",
            "Statut": "OK" if total > 0 else "KO",
            "Détail": f"{total} folds générés.",
        },
        {
            "Contrôle": "Folds valides",
            "Statut": "OK" if ok == total else "À surveiller",
            "Détail": f"{ok}/{total} folds OK.",
        },
        {
            "Contrôle": "Leakage après purge",
            "Statut": "OK" if leakage == 0 else "KO",
            "Détail": f"{leakage} fold(s) avec overlap résiduel.",
        },
        {
            "Contrôle": "Train moyen",
            "Statut": "OK" if avg_train >= 300 else "À surveiller",
            "Détail": f"{avg_train:.1f} observations.",
        },
        {
            "Contrôle": "Test moyen",
            "Statut": "OK" if avg_test >= 50 else "À surveiller",
            "Détail": f"{avg_test:.1f} observations.",
        },
        {
            "Contrôle": "Ticker coverage test",
            "Statut": "OK" if avg_test_tickers >= 5 else "À surveiller",
            "Détail": f"{avg_test_tickers:.1f} tickers/test en moyenne.",
        },
        {
            "Contrôle": "Decision Engine",
            "Statut": "Blocked",
            "Détail": "Aucune intégration. Validation scaffold only.",
        },
    ]

    return pd.DataFrame(rows)


def build_cross_sectional_fold_stability_v41(validation_df: pd.DataFrame) -> pd.DataFrame:
    """
    Diagnostic de stabilité des distributions train/test sur panel.
    """
    if validation_df is None or validation_df.empty:
        return pd.DataFrame()

    required = [
        "Fold",
        "Train TP %",
        "Test TP %",
        "Train SL %",
        "Test SL %",
        "Train Avg return",
        "Test Avg return",
        "Train final",
        "Test size",
        "Status",
    ]

    missing = [col for col in required if col not in validation_df.columns]

    if missing:
        return pd.DataFrame()

    rows = []

    for _, row in validation_df.iterrows():
        train_tp = _safe_float(row.get("Train TP %"), 0) or 0
        test_tp = _safe_float(row.get("Test TP %"), 0) or 0
        train_sl = _safe_float(row.get("Train SL %"), 0) or 0
        test_sl = _safe_float(row.get("Test SL %"), 0) or 0
        train_ret = _safe_float(row.get("Train Avg return"), 0) or 0
        test_ret = _safe_float(row.get("Test Avg return"), 0) or 0

        tp_gap = test_tp - train_tp
        sl_gap = test_sl - train_sl
        ret_gap = test_ret - train_ret

        max_label_gap = max(abs(tp_gap), abs(sl_gap))

        if row.get("Status") != "OK":
            stability = "Invalid fold"
        elif max_label_gap <= 0.15:
            stability = "Stable"
        elif max_label_gap <= 0.30:
            stability = "Moderate drift"
        else:
            stability = "High drift"

        rows.append(
            {
                "Fold": int(row.get("Fold")),
                "Train size": int(row.get("Train final")),
                "Test size": int(row.get("Test size")),
                "Train TP %": train_tp,
                "Test TP %": test_tp,
                "TP gap": tp_gap,
                "Train SL %": train_sl,
                "Test SL %": test_sl,
                "SL gap": sl_gap,
                "Train Avg return": train_ret,
                "Test Avg return": test_ret,
                "Return gap": ret_gap,
                "Max label gap": max_label_gap,
                "Stability": stability,
            }
        )

    return pd.DataFrame(rows)


def build_cross_sectional_ticker_test_coverage_v41(panel: pd.DataFrame, validation_df: pd.DataFrame) -> pd.DataFrame:
    """
    Vérifie que chaque ticker apparaît dans les tests OOS.
    """
    if panel is None or panel.empty or validation_df is None or validation_df.empty:
        return pd.DataFrame()

    work = _ensure_panel_event_dates_v41(panel)

    if work.empty:
        return pd.DataFrame()

    work = work.dropna(subset=["tb_label", "tb_event_start", "ticker"]).copy()
    work["tb_event_start"] = pd.to_datetime(work["tb_event_start"], errors="coerce")

    rows = []

    for ticker, group in work.groupby("ticker"):
        tested_folds = 0
        test_obs = 0

        for _, fold in validation_df.iterrows():
            test_start = pd.to_datetime(fold.get("Test start"), errors="coerce")
            test_end = pd.to_datetime(fold.get("Test end"), errors="coerce")

            test = group[
                (group["tb_event_start"] >= test_start)
                & (group["tb_event_start"] <= test_end)
            ]

            if not test.empty:
                tested_folds += 1
                test_obs += len(test)

        rows.append(
            {
                "Ticker": ticker,
                "Tested folds": tested_folds,
                "Test observations": test_obs,
                "Coverage status": "OK" if tested_folds >= 3 and test_obs >= 20 else "À surveiller",
            }
        )

    return pd.DataFrame(rows).sort_values(["Coverage status", "Ticker"])


# ============================================================
# V4.2 — CROSS-SECTIONAL BASELINE RANKER, RESEARCH-ONLY
# ============================================================

def prepare_cross_sectional_dataset_v42(panel: pd.DataFrame) -> tuple[pd.DataFrame, pd.Series, pd.DataFrame]:
    """
    Prépare X, y, meta pour le modèle cross-sectional.

    y = 1 si TP_FIRST
    y = 0 sinon

    Important :
    - aucun tb_* dans X ;
    - aucun forward_return_* dans X ;
    - aucun prix brut ;
    - ticker seulement dans meta, pas dans X.
    """
    if panel is None or panel.empty:
        return pd.DataFrame(), pd.Series(dtype=int), pd.DataFrame()

    work = _ensure_panel_event_dates_v41(panel)

    if work.empty:
        return pd.DataFrame(), pd.Series(dtype=int), pd.DataFrame()

    work = work.dropna(subset=["ticker", "tb_label", "tb_event_start", "tb_event_end"]).copy()

    if work.empty:
        return pd.DataFrame(), pd.Series(dtype=int), pd.DataFrame()

    feature_cols = get_eligible_feature_columns_v30(work)

    if not feature_cols:
        return pd.DataFrame(), pd.Series(dtype=int), pd.DataFrame()

    X = work[feature_cols].copy().replace([np.inf, -np.inf], np.nan)
    y = (work["tb_label"].astype(float) == 1.0).astype(int)

    meta_cols = [
        "ticker",
        "date",
        "tb_label",
        "tb_event",
        "tb_event_start",
        "tb_event_end",
        "tb_return",
        "tb_mfe",
        "tb_mae",
        "tb_holding_days",
    ]

    meta_cols = [col for col in meta_cols if col in work.columns]
    meta = work[meta_cols].copy()

    return X, y, meta


def _make_cross_sectional_ranker_v42(model_name: str):
    """
    Modèles simples uniquement.
    Pas de LightGBM ici.
    """
    if model_name == "Logistic strong regularization":
        model = LogisticRegression(
            max_iter=1000,
            class_weight=None,
            solver="liblinear",
            C=0.10,
            random_state=42,
        )

    elif model_name == "Logistic unweighted":
        model = LogisticRegression(
            max_iter=1000,
            class_weight=None,
            solver="liblinear",
            C=1.0,
            random_state=42,
        )

    elif model_name == "Logistic balanced":
        model = LogisticRegression(
            max_iter=1000,
            class_weight="balanced",
            solver="liblinear",
            C=1.0,
            random_state=42,
        )

    else:
        model = LogisticRegression(
            max_iter=1000,
            class_weight=None,
            solver="liblinear",
            C=0.10,
            random_state=42,
        )

    return Pipeline(
        steps=[
            ("imputer", SimpleImputer(strategy="median")),
            ("scaler", StandardScaler()),
            ("model", model),
        ]
    )


def run_cross_sectional_baseline_ranker_v42(
    panel: pd.DataFrame,
    n_splits: int = 5,
    embargo_days: int = 5,
    min_train_size: int = 300,
    min_test_size: int = 50,
    model_name: str = "Logistic strong regularization",
) -> tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame]:
    """
    Premier modèle cross-sectional research-only.

    Validation :
    - split par date ;
    - train passé uniquement ;
    - purge + embargo ;
    - test tous tickers ;
    - output = ranking relatif OOS.

    Ne valide aucune probabilité.
    """
    if not SKLEARN_AVAILABLE:
        return pd.DataFrame(), pd.DataFrame(), pd.DataFrame()

    X, y, meta = prepare_cross_sectional_dataset_v42(panel)

    if X.empty or y.empty or meta.empty:
        return pd.DataFrame(), pd.DataFrame(), pd.DataFrame()

    valid = pd.concat(
        [meta.reset_index(drop=True), X.reset_index(drop=True)],
        axis=1,
    )

    valid["_y_success"] = y.values
    valid["tb_event_start"] = pd.to_datetime(valid["tb_event_start"], errors="coerce")
    valid["tb_event_end"] = pd.to_datetime(valid["tb_event_end"], errors="coerce")
    valid["date"] = pd.to_datetime(valid["date"], errors="coerce")

    valid = valid.dropna(subset=["ticker", "tb_event_start", "tb_event_end", "_y_success"])
    valid = valid.sort_values(["tb_event_start", "ticker"]).reset_index(drop=True)

    feature_cols = list(X.columns)

    if valid.empty or len(valid) < min_train_size + min_test_size:
        return pd.DataFrame(), pd.DataFrame(), pd.DataFrame()

    unique_dates = np.array(sorted(valid["tb_event_start"].dropna().unique()))

    if len(unique_dates) < n_splits + 20:
        return pd.DataFrame(), pd.DataFrame(), pd.DataFrame()

    initial_train_dates = max(60, int(len(unique_dates) * 0.35))
    test_dates = unique_dates[initial_train_dates:]

    if len(test_dates) < n_splits:
        return pd.DataFrame(), pd.DataFrame(), pd.DataFrame()

    date_chunks = np.array_split(test_dates, n_splits)
    embargo_delta = pd.Timedelta(days=int(embargo_days))

    fold_rows = []
    pred_rows = []

    for fold_id, chunk in enumerate(date_chunks, start=1):
        if len(chunk) == 0:
            continue

        test_start = pd.to_datetime(chunk[0])
        test_end = pd.to_datetime(chunk[-1])

        test_mask = (
            (valid["tb_event_start"] >= test_start)
            & (valid["tb_event_start"] <= test_end)
        )

        embargo_cutoff = test_start - embargo_delta

        train_mask = (
            (valid["tb_event_start"] < test_start)
            & (valid["tb_event_end"] < embargo_cutoff)
        )

        train = valid.loc[train_mask].copy()
        test = valid.loc[test_mask].copy()

        status = "OK"

        if len(train) < min_train_size:
            status = "Skipped - train too small"

        if len(test) < min_test_size:
            status = "Skipped - test too small"

        if train["ticker"].nunique() < 5 or test["ticker"].nunique() < 5:
            status = "Skipped - ticker coverage weak"

        if train["_y_success"].nunique() < 2:
            status = "Skipped - train single class"

        if status != "OK":
            fold_rows.append(
                {
                    "Fold": fold_id,
                    "Status": status,
                    "Train size": len(train),
                    "Test size": len(test),
                    "Train tickers": train["ticker"].nunique() if not train.empty else 0,
                    "Test tickers": test["ticker"].nunique() if not test.empty else 0,
                }
            )
            continue

        X_train = train[feature_cols].copy()
        y_train = train["_y_success"].astype(int)

        X_test = test[feature_cols].copy()
        y_test = test["_y_success"].astype(int)

        try:
            model = _make_cross_sectional_ranker_v42(model_name)
            dummy = Pipeline(
                steps=[
                    ("imputer", SimpleImputer(strategy="median")),
                    ("model", DummyClassifier(strategy="prior")),
                ]
            )

            model.fit(X_train, y_train)
            dummy.fit(X_train, y_train)

            proba = model.predict_proba(X_test)[:, 1]
            dummy_proba = dummy.predict_proba(X_test)[:, 1]

            metrics = _classification_metrics_v30(y_test, proba, threshold=0.50)
            dummy_metrics = _classification_metrics_v30(y_test, dummy_proba, threshold=0.50)

            # Rank intra-fold : on ne valide pas la proba brute.
            ranked_test = test[
                [
                    "ticker",
                    "date",
                    "tb_label",
                    "tb_event",
                    "tb_return",
                    "tb_mfe",
                    "tb_mae",
                    "tb_holding_days",
                ]
            ].copy()

            ranked_test["Fold"] = fold_id
            ranked_test["Model"] = model_name
            ranked_test["y_true_success"] = y_test.values
            ranked_test["p_raw"] = proba
            ranked_test["p_dummy"] = dummy_proba
            ranked_test["rank_pct_in_fold"] = pd.Series(proba).rank(method="average", pct=True).values

            ranked_test["rank_bucket"] = np.select(
                [
                    ranked_test["rank_pct_in_fold"] >= 0.90,
                    ranked_test["rank_pct_in_fold"] >= 0.80,
                    ranked_test["rank_pct_in_fold"] >= 0.70,
                    ranked_test["rank_pct_in_fold"] <= 0.20,
                ],
                [
                    "Top 10%",
                    "Top 20%",
                    "Top 30%",
                    "Bottom 20%",
                ],
                default="Middle 40%",
            )

            pred_rows.append(ranked_test)

            top20 = ranked_test[ranked_test["rank_pct_in_fold"] >= 0.80]
            bottom20 = ranked_test[ranked_test["rank_pct_in_fold"] <= 0.20]

            all_tp = ranked_test["y_true_success"].mean()
            all_return = ranked_test["tb_return"].mean()

            top20_tp = top20["y_true_success"].mean() if not top20.empty else np.nan
            top20_return = top20["tb_return"].mean() if not top20.empty else np.nan
            bottom20_return = bottom20["tb_return"].mean() if not bottom20.empty else np.nan

            fold_rows.append(
                {
                    "Fold": fold_id,
                    "Status": "OK",
                    "Train size": len(train),
                    "Test size": len(test),
                    "Train tickers": train["ticker"].nunique(),
                    "Test tickers": test["ticker"].nunique(),
                    "Train TP %": y_train.mean(),
                    "Test TP %": y_test.mean(),
                    "AUC": metrics["ROC AUC"],
                    "Balanced accuracy": metrics["Balanced accuracy"],
                    "Brier": metrics["Brier score"],
                    "Dummy Brier": dummy_metrics["Brier score"],
                    "Brier improvement": dummy_metrics["Brier score"] - metrics["Brier score"],
                    "Avg raw p": metrics["Avg predicted TP %"],
                    "Realized TP %": metrics["Realized TP %"],
                    "Top20 count": len(top20),
                    "Top20 TP %": top20_tp,
                    "Top20 TP lift": top20_tp - all_tp if not pd.isna(top20_tp) else np.nan,
                    "Top20 return": top20_return,
                    "Top20 return lift": top20_return - all_return if not pd.isna(top20_return) else np.nan,
                    "Bottom20 return": bottom20_return,
                    "All return": all_return,
                }
            )

        except Exception as e:
            fold_rows.append(
                {
                    "Fold": fold_id,
                    "Status": f"Error: {str(e)[:100]}",
                    "Train size": len(train),
                    "Test size": len(test),
                    "Train tickers": train["ticker"].nunique() if not train.empty else 0,
                    "Test tickers": test["ticker"].nunique() if not test.empty else 0,
                }
            )

    fold_results = pd.DataFrame(fold_rows)

    if pred_rows:
        predictions = pd.concat(pred_rows, ignore_index=True)
    else:
        predictions = pd.DataFrame()

    if predictions.empty:
        bucket_summary = pd.DataFrame()
    else:
        bucket_rows = []

        for bucket, group in predictions.groupby("rank_bucket"):
            if group.empty:
                continue

            bucket_rows.append(
                {
                    "Rank bucket": bucket,
                    "Count": len(group),
                    "TP %": group["y_true_success"].mean(),
                    "Avg return": group["tb_return"].mean(),
                    "Avg MFE": group["tb_mfe"].mean(),
                    "Avg MAE": group["tb_mae"].mean(),
                    "Avg raw p": group["p_raw"].mean(),
                    "Tickers": group["ticker"].nunique(),
                }
            )

        bucket_summary = pd.DataFrame(bucket_rows)

    return fold_results, predictions, bucket_summary


def build_cross_sectional_ranker_summary_v42(
    fold_results: pd.DataFrame,
    bucket_summary: pd.DataFrame,
) -> pd.DataFrame:
    """
    Résumé institutionnel du ranker cross-sectional.
    """
    if fold_results is None or fold_results.empty:
        return pd.DataFrame()

    ok = fold_results[fold_results["Status"] == "OK"].copy()

    if ok.empty:
        return pd.DataFrame(
            [
                {
                    "Contrôle": "Cross-sectional ranker",
                    "Statut": "KO",
                    "Détail": "Aucun fold modèle exploitable.",
                }
            ]
        )

    avg_auc = ok["AUC"].mean()
    avg_brier_improvement = ok["Brier improvement"].mean()
    positive_top20_return_folds = int((ok["Top20 return"] > 0).sum())
    positive_top20_lift_folds = int((ok["Top20 return lift"] > 0).sum())
    avg_top20_lift = ok["Top20 return lift"].mean()
    avg_top20_tp_lift = ok["Top20 TP lift"].mean()

    if positive_top20_return_folds >= max(1, len(ok) - 1) and avg_top20_lift > 0:
        rank_status = "Research positive"
        detail = "Top20 cross-sectional positif sur la majorité des folds."
    elif positive_top20_lift_folds >= max(1, len(ok) - 1):
        rank_status = "Ranking lift only"
        detail = "Top20 améliore le ranking mais le return absolu reste fragile."
    else:
        rank_status = "Weak"
        detail = "Top20 ne montre pas assez de robustesse OOS."

    rows = [
        {
            "Contrôle": "Cross-sectional ranker status",
            "Statut": rank_status,
            "Détail": detail,
        },
        {
            "Contrôle": "Folds modèle OK",
            "Statut": "OK",
            "Détail": f"{len(ok)}/{len(fold_results)} folds.",
        },
        {
            "Contrôle": "AUC moyen",
            "Statut": "OK" if avg_auc >= 0.55 else "Weak",
            "Détail": "N/A" if pd.isna(avg_auc) else f"{avg_auc:.3f}",
        },
        {
            "Contrôle": "Brier improvement moyen",
            "Statut": "Info",
            "Détail": f"{avg_brier_improvement:.4f}",
        },
        {
            "Contrôle": "Top20 return folds positifs",
            "Statut": "OK" if positive_top20_return_folds >= max(1, len(ok) - 1) else "À surveiller",
            "Détail": f"{positive_top20_return_folds}/{len(ok)} folds.",
        },
        {
            "Contrôle": "Top20 lift folds positifs",
            "Statut": "OK" if positive_top20_lift_folds >= max(1, len(ok) - 1) else "À surveiller",
            "Détail": f"{positive_top20_lift_folds}/{len(ok)} folds.",
        },
        {
            "Contrôle": "Avg Top20 return lift",
            "Statut": "OK" if avg_top20_lift > 0 else "Weak",
            "Détail": _fmt_pct(avg_top20_lift),
        },
        {
            "Contrôle": "Avg Top20 TP lift",
            "Statut": "OK" if avg_top20_tp_lift > 0 else "Weak",
            "Détail": _fmt_pct(avg_top20_tp_lift),
        },
        {
            "Contrôle": "Probability usage",
            "Statut": "Blocked",
            "Détail": "Probabilités non validées. Usage rank-only.",
        },
        {
            "Contrôle": "Decision Engine",
            "Statut": "Blocked",
            "Détail": "Aucune intégration.",
        },
    ]

    return pd.DataFrame(rows)


def build_cross_sectional_ranker_ticker_breakdown_v42(predictions: pd.DataFrame) -> pd.DataFrame:
    """
    Analyse Top20 par ticker.
    """
    if predictions is None or predictions.empty:
        return pd.DataFrame()

    required = ["ticker", "rank_pct_in_fold", "y_true_success", "tb_return", "tb_mfe", "tb_mae"]

    if any(col not in predictions.columns for col in required):
        return pd.DataFrame()

    rows = []

    for ticker, group in predictions.groupby("ticker"):
        all_tp = group["y_true_success"].mean()
        all_return = group["tb_return"].mean()

        top20 = group[group["rank_pct_in_fold"] >= 0.80]
        bottom20 = group[group["rank_pct_in_fold"] <= 0.20]

        if top20.empty:
            continue

        rows.append(
            {
                "Ticker": ticker,
                "OOS obs": len(group),
                "Top20 obs": len(top20),
                "All TP %": all_tp,
                "Top20 TP %": top20["y_true_success"].mean(),
                "Top20 TP lift": top20["y_true_success"].mean() - all_tp,
                "All avg return": all_return,
                "Top20 avg return": top20["tb_return"].mean(),
                "Top20 return lift": top20["tb_return"].mean() - all_return,
                "Top20 avg MFE": top20["tb_mfe"].mean(),
                "Top20 avg MAE": top20["tb_mae"].mean(),
                "Bottom20 avg return": bottom20["tb_return"].mean() if not bottom20.empty else np.nan,
            }
        )

    return pd.DataFrame(rows).sort_values("Top20 return lift", ascending=False)


def build_cross_sectional_ranker_manifest_v42(summary_df: pd.DataFrame) -> pd.DataFrame:
    """
    Manifest sécurité V4.2.
    """
    if summary_df is None or summary_df.empty:
        return pd.DataFrame()

    status_row = summary_df[summary_df["Contrôle"] == "Cross-sectional ranker status"]

    if not status_row.empty:
        rank_status = str(status_row.iloc[0]["Statut"])
        rank_detail = str(status_row.iloc[0]["Détail"])
    else:
        rank_status = "Unknown"
        rank_detail = "Résumé indisponible."

    rows = [
        {
            "Item": "Model scope",
            "Status": "Research-only",
            "Detail": "Cross-sectional baseline ranker uniquement.",
        },
        {
            "Item": "Ranker status",
            "Status": rank_status,
            "Detail": rank_detail,
        },
        {
            "Item": "Probability usage",
            "Status": "Blocked",
            "Detail": "Les probabilités brutes ne sont pas calibrées.",
        },
        {
            "Item": "Allowed usage",
            "Status": "Shadow only",
            "Detail": "Analyse Top20/Bottom20, ranking relatif, diagnostic ticker.",
        },
        {
            "Item": "Decision Engine integration",
            "Status": "Blocked",
            "Detail": "Aucune intégration avant validation plus large et calibration.",
        },
    ]

    return pd.DataFrame(rows)


def build_cross_sectional_cumulative_rank_summary_v421(predictions: pd.DataFrame) -> pd.DataFrame:
    """
    Résumé cumulatif du ranking cross-sectional.

    Contrairement à rank_bucket :
    - Top 10% = rank >= 90%
    - Top 20% = rank >= 80%
    - Top 30% = rank >= 70%

    Cela évite de confondre bandes de rang et sélections cumulatives.
    """
    if predictions is None or predictions.empty:
        return pd.DataFrame()

    required = [
        "rank_pct_in_fold",
        "y_true_success",
        "tb_return",
        "tb_mfe",
        "tb_mae",
        "ticker",
    ]

    if any(col not in predictions.columns for col in required):
        return pd.DataFrame()

    work = predictions.copy()

    for col in ["rank_pct_in_fold", "y_true_success", "tb_return", "tb_mfe", "tb_mae"]:
        work[col] = pd.to_numeric(work[col], errors="coerce")

    work = work.dropna(subset=["rank_pct_in_fold", "y_true_success"])

    if work.empty:
        return pd.DataFrame()

    all_tp = work["y_true_success"].mean()
    all_return = work["tb_return"].mean()

    selections = [
        ("Top 10% cumulative", work["rank_pct_in_fold"] >= 0.90),
        ("Top 20% cumulative", work["rank_pct_in_fold"] >= 0.80),
        ("Top 30% cumulative", work["rank_pct_in_fold"] >= 0.70),
        ("Middle 40%", (work["rank_pct_in_fold"] > 0.30) & (work["rank_pct_in_fold"] < 0.70)),
        ("Bottom 20%", work["rank_pct_in_fold"] <= 0.20),
        ("All OOS", work["rank_pct_in_fold"] >= 0.00),
    ]

    rows = []

    for selection_name, mask in selections:
        group = work.loc[mask].copy()

        if group.empty:
            continue

        rows.append(
            {
                "Selection": selection_name,
                "Count": len(group),
                "Tickers": group["ticker"].nunique(),
                "TP %": group["y_true_success"].mean(),
                "Avg return": group["tb_return"].mean(),
                "Avg MFE": group["tb_mfe"].mean(),
                "Avg MAE": group["tb_mae"].mean(),
                "TP lift vs all": group["y_true_success"].mean() - all_tp,
                "Return lift vs all": group["tb_return"].mean() - all_return,
                "All TP %": all_tp,
                "All avg return": all_return,
            }
        )

    return pd.DataFrame(rows)


 # ============================================================
# V4.3 — CROSS-SECTIONAL RANK FAILURE DIAGNOSTICS + TICKER GATE
# ============================================================

def build_cross_sectional_fold_selection_diagnostics_v43(predictions: pd.DataFrame) -> pd.DataFrame:
    """
    Vérifie les sélections cumulatives Top10/Top20/Top30 fold par fold.

    Objectif :
    - voir si l'échec global vient d'un seul fold ;
    - contrôler la stabilité temporelle du ranking ;
    - aucun nouveau modèle.
    """
    if predictions is None or predictions.empty:
        return pd.DataFrame()

    required = [
        "Fold",
        "rank_pct_in_fold",
        "y_true_success",
        "tb_return",
        "tb_mfe",
        "tb_mae",
        "ticker",
    ]

    if any(col not in predictions.columns for col in required):
        return pd.DataFrame()

    work = predictions.copy()

    for col in ["rank_pct_in_fold", "y_true_success", "tb_return", "tb_mfe", "tb_mae"]:
        work[col] = pd.to_numeric(work[col], errors="coerce")

    work = work.dropna(subset=["Fold", "rank_pct_in_fold", "y_true_success"])

    if work.empty:
        return pd.DataFrame()

    rows = []

    for fold, group in work.groupby("Fold"):
        fold_all_tp = group["y_true_success"].mean()
        fold_all_return = group["tb_return"].mean()

        selections = [
            ("Top 10%", group["rank_pct_in_fold"] >= 0.90),
            ("Top 20%", group["rank_pct_in_fold"] >= 0.80),
            ("Top 30%", group["rank_pct_in_fold"] >= 0.70),
            ("Bottom 20%", group["rank_pct_in_fold"] <= 0.20),
        ]

        for selection, mask in selections:
            selected = group.loc[mask].copy()

            if selected.empty:
                continue

            tp_rate = selected["y_true_success"].mean()
            avg_return = selected["tb_return"].mean()

            tp_lift = tp_rate - fold_all_tp
            return_lift = avg_return - fold_all_return

            if selection.startswith("Top") and tp_lift > 0.05 and return_lift > 0:
                verdict = "Supportive"
            elif selection.startswith("Top") and return_lift > 0:
                verdict = "Return supportive"
            elif selection.startswith("Top") and return_lift < -0.005:
                verdict = "Weak"
            elif selection.startswith("Bottom") and avg_return < fold_all_return:
                verdict = "Bottom useful"
            else:
                verdict = "Neutral"

            rows.append(
                {
                    "Fold": int(fold),
                    "Selection": selection,
                    "Count": len(selected),
                    "Tickers": selected["ticker"].nunique(),
                    "Fold all TP %": fold_all_tp,
                    "Selection TP %": tp_rate,
                    "TP lift vs fold": tp_lift,
                    "Fold all return": fold_all_return,
                    "Selection return": avg_return,
                    "Return lift vs fold": return_lift,
                    "Avg MFE": selected["tb_mfe"].mean(),
                    "Avg MAE": selected["tb_mae"].mean(),
                    "Verdict": verdict,
                }
            )

    return pd.DataFrame(rows)


def build_cross_sectional_ticker_gate_v43(ticker_breakdown: pd.DataFrame) -> pd.DataFrame:
    """
    Classe les tickers selon leur contribution au Top20.

    Important :
    - ce n'est pas une autorisation de trading ;
    - c'est un diagnostic de recherche pour savoir si le global ranker doit être filtré par ticker.
    """
    if ticker_breakdown is None or ticker_breakdown.empty:
        return pd.DataFrame()

    required = [
        "Ticker",
        "OOS obs",
        "Top20 obs",
        "Top20 TP lift",
        "Top20 return lift",
        "Top20 avg return",
        "Bottom20 avg return",
    ]

    if any(col not in ticker_breakdown.columns for col in required):
        return pd.DataFrame()

    rows = []

    for _, row in ticker_breakdown.iterrows():
        ticker = str(row.get("Ticker"))

        top20_obs = int(_safe_float(row.get("Top20 obs"), 0) or 0)
        top20_tp_lift = _safe_float(row.get("Top20 TP lift"), 0) or 0
        top20_return_lift = _safe_float(row.get("Top20 return lift"), 0) or 0
        top20_avg_return = _safe_float(row.get("Top20 avg return"), 0) or 0
        bottom20_return = _safe_float(row.get("Bottom20 avg return"), 0) or 0

        if top20_obs < 15:
            gate = "Small sample"
            detail = "Top20 trop peu représenté."
        elif top20_return_lift > 0.005 and top20_tp_lift > 0.05 and top20_avg_return > 0:
            gate = "Supportive ticker"
            detail = "Top20 améliore hit rate et return."
        elif top20_return_lift > 0 and top20_avg_return > 0:
            gate = "Watchlist ticker"
            detail = "Top20 améliore le return mais signal modéré."
        elif top20_return_lift < -0.005 or top20_tp_lift < -0.05:
            gate = "Damaging ticker"
            detail = "Top20 dégrade le ranking global."
        else:
            gate = "Neutral ticker"
            detail = "Pas d'effet exploitable clair."

        rows.append(
            {
                "Ticker": ticker,
                "Top20 obs": top20_obs,
                "Top20 TP lift": top20_tp_lift,
                "Top20 return lift": top20_return_lift,
                "Top20 avg return": top20_avg_return,
                "Bottom20 avg return": bottom20_return,
                "Ticker gate": gate,
                "Detail": detail,
            }
        )

    out = pd.DataFrame(rows)

    if out.empty:
        return out

    gate_order = {
        "Supportive ticker": 0,
        "Watchlist ticker": 1,
        "Neutral ticker": 2,
        "Small sample": 3,
        "Damaging ticker": 4,
    }

    out["_order"] = out["Ticker gate"].map(gate_order).fillna(99)
    out = out.sort_values(["_order", "Top20 return lift"], ascending=[True, False]).drop(columns=["_order"])

    return out


def build_cross_sectional_failure_manifest_v43(
    summary_v42: pd.DataFrame,
    cumulative_v421: pd.DataFrame,
    ticker_gate_v43: pd.DataFrame,
    fold_diag_v43: pd.DataFrame,
) -> pd.DataFrame:
    """
    Manifest de décision après l'échec du ranker global.
    """
    rows = []

    global_status = "Unknown"

    if summary_v42 is not None and not summary_v42.empty:
        status_row = summary_v42[summary_v42["Contrôle"] == "Cross-sectional ranker status"]

        if not status_row.empty:
            global_status = str(status_row.iloc[0]["Statut"])

    supportive = 0
    watchlist = 0
    damaging = 0

    if ticker_gate_v43 is not None and not ticker_gate_v43.empty:
        supportive = int((ticker_gate_v43["Ticker gate"] == "Supportive ticker").sum())
        watchlist = int((ticker_gate_v43["Ticker gate"] == "Watchlist ticker").sum())
        damaging = int((ticker_gate_v43["Ticker gate"] == "Damaging ticker").sum())

    top20_return_lift = np.nan
    top30_return_lift = np.nan

    if cumulative_v421 is not None and not cumulative_v421.empty:
        top20 = cumulative_v421[cumulative_v421["Selection"] == "Top 20% cumulative"]
        top30 = cumulative_v421[cumulative_v421["Selection"] == "Top 30% cumulative"]

        if not top20.empty:
            top20_return_lift = _safe_float(top20.iloc[0].get("Return lift vs all"), np.nan)

        if not top30.empty:
            top30_return_lift = _safe_float(top30.iloc[0].get("Return lift vs all"), np.nan)

    weak_top20_folds = 0

    if fold_diag_v43 is not None and not fold_diag_v43.empty:
        top20_folds = fold_diag_v43[fold_diag_v43["Selection"] == "Top 20%"]

        if not top20_folds.empty:
            weak_top20_folds = int((top20_folds["Verdict"] == "Weak").sum())

    if global_status == "Weak":
        rows.append(
            {
                "Decision item": "Global cross-sectional ranker",
                "Status": "Rejected",
                "Detail": "Le ranker global V4.2 ne passe pas les critères OOS.",
            }
        )
    else:
        rows.append(
            {
                "Decision item": "Global cross-sectional ranker",
                "Status": global_status,
                "Detail": "Statut hérité du résumé V4.2.",
            }
        )

    rows.append(
        {
            "Decision item": "Top20 cumulative",
            "Status": "Weak" if pd.isna(top20_return_lift) or top20_return_lift <= 0 else "Info",
            "Detail": "N/A" if pd.isna(top20_return_lift) else f"Return lift {top20_return_lift:.2%}.",
        }
    )

    rows.append(
        {
            "Decision item": "Top30 cumulative",
            "Status": "Info" if not pd.isna(top30_return_lift) else "N/A",
            "Detail": "N/A" if pd.isna(top30_return_lift) else f"Return lift {top30_return_lift:.2%}.",
        }
    )

    rows.append(
        {
            "Decision item": "Ticker gate",
            "Status": "Research path" if supportive + watchlist > 0 else "Weak",
            "Detail": f"{supportive} supportive, {watchlist} watchlist, {damaging} damaging tickers.",
        }
    )

    rows.append(
        {
            "Decision item": "Fold Top20 weakness",
            "Status": "À surveiller" if weak_top20_folds > 0 else "OK",
            "Detail": f"{weak_top20_folds} weak Top20 fold(s).",
        }
    )

    rows.append(
        {
            "Decision item": "Next step",
            "Status": "Research only",
            "Detail": "Ne pas calibrer. Ajouter un ticker gate ou enrichir features/régime avant modèle avancé.",
        }
    )

    rows.append(
        {
            "Decision item": "Decision Engine",
            "Status": "Blocked",
            "Detail": "Aucune intégration.",
        }
    )

    return pd.DataFrame(rows)


# ============================================================
# V4.3.1 — STRICT TICKER GATE
# ============================================================

def build_cross_sectional_strict_ticker_gate_v431(ticker_breakdown: pd.DataFrame) -> pd.DataFrame:
    """
    Gate strict par ticker.

    Correction importante vs V4.3 :
    un ticker ne peut pas être considéré supportive si le Top20 ne bat pas le Bottom20.
    Pour un vrai ranker, il faut une séparation haut/bas.
    """
    if ticker_breakdown is None or ticker_breakdown.empty:
        return pd.DataFrame()

    required = [
        "Ticker",
        "OOS obs",
        "Top20 obs",
        "All TP %",
        "Top20 TP %",
        "Top20 TP lift",
        "All avg return",
        "Top20 avg return",
        "Top20 return lift",
        "Bottom20 avg return",
    ]

    if any(col not in ticker_breakdown.columns for col in required):
        return pd.DataFrame()

    rows = []

    for _, row in ticker_breakdown.iterrows():
        ticker = str(row.get("Ticker"))

        oos_obs = int(_safe_float(row.get("OOS obs"), 0) or 0)
        top20_obs = int(_safe_float(row.get("Top20 obs"), 0) or 0)

        all_tp = _safe_float(row.get("All TP %"), 0) or 0
        top20_tp = _safe_float(row.get("Top20 TP %"), 0) or 0
        top20_tp_lift = _safe_float(row.get("Top20 TP lift"), 0) or 0

        all_return = _safe_float(row.get("All avg return"), 0) or 0
        top20_return = _safe_float(row.get("Top20 avg return"), 0) or 0
        top20_return_lift = _safe_float(row.get("Top20 return lift"), 0) or 0
        bottom20_return = _safe_float(row.get("Bottom20 avg return"), np.nan)

        top_vs_bottom_spread = (
            top20_return - bottom20_return
            if not pd.isna(bottom20_return)
            else np.nan
        )

        strict_score = 0

        if top20_obs >= 15:
            strict_score += 20
        else:
            strict_score -= 25

        if top20_tp_lift > 0.05:
            strict_score += 20
        elif top20_tp_lift < -0.05:
            strict_score -= 20

        if top20_return_lift > 0.005:
            strict_score += 25
        elif top20_return_lift < -0.005:
            strict_score -= 25

        if top20_return > 0:
            strict_score += 15
        else:
            strict_score -= 15

        if not pd.isna(top_vs_bottom_spread):
            if top_vs_bottom_spread > 0.005:
                strict_score += 25
            elif top_vs_bottom_spread > 0:
                strict_score += 10
            else:
                strict_score -= 30

        strict_score = clamp(strict_score, 0, 100)

        if top20_obs < 15:
            strict_gate = "Small sample"
            detail = "Top20 trop peu représenté pour valider le ticker."

        elif (
            top20_tp_lift > 0.05
            and top20_return_lift > 0.005
            and top20_return > 0
            and not pd.isna(top_vs_bottom_spread)
            and top_vs_bottom_spread > 0.005
        ):
            strict_gate = "Strict supportive"
            detail = "Top20 bat la moyenne et le Bottom20 : séparation de rang propre."

        elif (
            top20_return_lift > 0
            and top20_return > 0
            and not pd.isna(top_vs_bottom_spread)
            and top_vs_bottom_spread > 0
        ):
            strict_gate = "Watchlist"
            detail = "Top20 positif et supérieur au Bottom20, mais edge encore modéré."

        elif not pd.isna(top_vs_bottom_spread) and top_vs_bottom_spread <= 0:
            strict_gate = "Spread failure"
            detail = "Top20 ne bat pas Bottom20 : ranking haut/bas incohérent."

        elif top20_return_lift < -0.005 or top20_tp_lift < -0.05:
            strict_gate = "Damaging"
            detail = "Top20 dégrade le ticker."

        else:
            strict_gate = "Neutral"
            detail = "Pas de preuve suffisante."

        rows.append(
            {
                "Ticker": ticker,
                "OOS obs": oos_obs,
                "Top20 obs": top20_obs,
                "All TP %": all_tp,
                "Top20 TP %": top20_tp,
                "Top20 TP lift": top20_tp_lift,
                "All avg return": all_return,
                "Top20 avg return": top20_return,
                "Top20 return lift": top20_return_lift,
                "Bottom20 avg return": bottom20_return,
                "Top20 minus Bottom20": top_vs_bottom_spread,
                "Strict gate score": strict_score,
                "Strict ticker gate": strict_gate,
                "Detail": detail,
            }
        )

    out = pd.DataFrame(rows)

    if out.empty:
        return out

    gate_order = {
        "Strict supportive": 0,
        "Watchlist": 1,
        "Neutral": 2,
        "Small sample": 3,
        "Spread failure": 4,
        "Damaging": 5,
    }

    out["_order"] = out["Strict ticker gate"].map(gate_order).fillna(99)
    out = out.sort_values(
        ["_order", "Strict gate score", "Top20 minus Bottom20"],
        ascending=[True, False, False],
    ).drop(columns=["_order"])

    return out


def build_strict_ticker_gate_manifest_v431(strict_gate: pd.DataFrame) -> pd.DataFrame:
    """
    Manifest strict après correction du ticker gate.
    """
    if strict_gate is None or strict_gate.empty:
        return pd.DataFrame()

    strict_supportive = int((strict_gate["Strict ticker gate"] == "Strict supportive").sum())
    watchlist = int((strict_gate["Strict ticker gate"] == "Watchlist").sum())
    spread_failures = int((strict_gate["Strict ticker gate"] == "Spread failure").sum())
    damaging = int((strict_gate["Strict ticker gate"] == "Damaging").sum())
    small = int((strict_gate["Strict ticker gate"] == "Small sample").sum())

    supportive_tickers = strict_gate.loc[
        strict_gate["Strict ticker gate"] == "Strict supportive",
        "Ticker",
    ].astype(str).tolist()

    watchlist_tickers = strict_gate.loc[
        strict_gate["Strict ticker gate"] == "Watchlist",
        "Ticker",
    ].astype(str).tolist()

    if strict_supportive >= 2:
        research_path = "Ticker-gated research possible"
        detail = f"Tickers strictement supportifs : {', '.join(supportive_tickers)}."
    elif strict_supportive == 1:
        research_path = "Single-ticker research only"
        detail = f"Un seul ticker strictement supportif : {', '.join(supportive_tickers)}."
    elif watchlist > 0:
        research_path = "Watchlist only"
        detail = f"Tickers watchlist : {', '.join(watchlist_tickers)}."
    else:
        research_path = "Rejected"
        detail = "Aucun ticker ne passe le gate strict."

    rows = [
        {
            "Decision item": "Strict ticker gate",
            "Status": research_path,
            "Detail": detail,
        },
        {
            "Decision item": "Strict supportive tickers",
            "Status": "Info",
            "Detail": f"{strict_supportive} ticker(s).",
        },
        {
            "Decision item": "Watchlist tickers",
            "Status": "Info",
            "Detail": f"{watchlist} ticker(s).",
        },
        {
            "Decision item": "Spread failures",
            "Status": "À surveiller" if spread_failures > 0 else "OK",
            "Detail": f"{spread_failures} ticker(s) où Top20 ne bat pas Bottom20.",
        },
        {
            "Decision item": "Damaging tickers",
            "Status": "À surveiller" if damaging > 0 else "OK",
            "Detail": f"{damaging} ticker(s).",
        },
        {
            "Decision item": "Small sample tickers",
            "Status": "Info",
            "Detail": f"{small} ticker(s).",
        },
        {
            "Decision item": "Global ranker",
            "Status": "Rejected",
            "Detail": "Le ranker cross-sectional global reste rejeté.",
        },
        {
            "Decision item": "Decision Engine",
            "Status": "Blocked",
            "Detail": "Aucune intégration.",
        },
    ]

    return pd.DataFrame(rows)


