def get_strict_supportive_tickers_v44(strict_gate_df: pd.DataFrame) -> list[str]:
    """
    Récupère les tickers qui passent le gate strict.
    """
    if strict_gate_df is None or strict_gate_df.empty:
        return []

    if "Strict ticker gate" not in strict_gate_df.columns or "Ticker" not in strict_gate_df.columns:
        return []

    tickers = strict_gate_df.loc[
        strict_gate_df["Strict ticker gate"] == "Strict supportive",
        "Ticker",
    ].astype(str).tolist()

    return tickers


def build_ticker_gated_policy_summary_v44(
    predictions: pd.DataFrame,
    strict_tickers: list[str],
) -> pd.DataFrame:
    """
    Résumé global de la policy ticker-gated.

    On ne réentraîne rien.
    On filtre seulement les prédictions OOS existantes sur les tickers strictement supportifs.
    """
    if predictions is None or predictions.empty or not strict_tickers:
        return pd.DataFrame()

    required = [
        "ticker",
        "Fold",
        "rank_pct_in_fold",
        "y_true_success",
        "tb_return",
        "tb_mfe",
        "tb_mae",
    ]

    if any(col not in predictions.columns for col in required):
        return pd.DataFrame()

    work = predictions[predictions["ticker"].astype(str).isin(strict_tickers)].copy()

    if work.empty:
        return pd.DataFrame()

    for col in ["rank_pct_in_fold", "y_true_success", "tb_return", "tb_mfe", "tb_mae"]:
        work[col] = pd.to_numeric(work[col], errors="coerce")

    work = work.dropna(subset=["rank_pct_in_fold", "y_true_success"])

    if work.empty:
        return pd.DataFrame()

    all_tp = work["y_true_success"].mean()
    all_return = work["tb_return"].mean()

    selections = [
        ("Top 10% gated", work["rank_pct_in_fold"] >= 0.90),
        ("Top 20% gated", work["rank_pct_in_fold"] >= 0.80),
        ("Top 30% gated", work["rank_pct_in_fold"] >= 0.70),
        ("Middle 40% gated", (work["rank_pct_in_fold"] > 0.30) & (work["rank_pct_in_fold"] < 0.70)),
        ("Bottom 20% gated", work["rank_pct_in_fold"] <= 0.20),
        ("All gated OOS", work["rank_pct_in_fold"] >= 0.00),
    ]

    rows = []

    for selection_name, mask in selections:
        group = work.loc[mask].copy()

        if group.empty:
            continue

        rows.append(
            {
                "Selection": selection_name,
                "Tickers": ", ".join(sorted(group["ticker"].astype(str).unique())),
                "Count": len(group),
                "Folds": group["Fold"].nunique(),
                "TP %": group["y_true_success"].mean(),
                "Avg return": group["tb_return"].mean(),
                "Avg MFE": group["tb_mfe"].mean(),
                "Avg MAE": group["tb_mae"].mean(),
                "TP lift vs gated all": group["y_true_success"].mean() - all_tp,
                "Return lift vs gated all": group["tb_return"].mean() - all_return,
                "Gated all TP %": all_tp,
                "Gated all return": all_return,
            }
        )

    return pd.DataFrame(rows)


def build_ticker_gated_fold_diagnostics_v44(
    predictions: pd.DataFrame,
    strict_tickers: list[str],
) -> pd.DataFrame:
    """
    Vérifie la stabilité fold par fold sur les tickers strictement supportifs.
    """
    if predictions is None or predictions.empty or not strict_tickers:
        return pd.DataFrame()

    required = [
        "ticker",
        "Fold",
        "rank_pct_in_fold",
        "y_true_success",
        "tb_return",
        "tb_mfe",
        "tb_mae",
    ]

    if any(col not in predictions.columns for col in required):
        return pd.DataFrame()

    work = predictions[predictions["ticker"].astype(str).isin(strict_tickers)].copy()

    if work.empty:
        return pd.DataFrame()

    for col in ["rank_pct_in_fold", "y_true_success", "tb_return", "tb_mfe", "tb_mae"]:
        work[col] = pd.to_numeric(work[col], errors="coerce")

    work = work.dropna(subset=["Fold", "rank_pct_in_fold", "y_true_success"])

    rows = []

    for fold, group in work.groupby("Fold"):
        fold_all_tp = group["y_true_success"].mean()
        fold_all_return = group["tb_return"].mean()

        selections = [
            ("Top 20% gated", group["rank_pct_in_fold"] >= 0.80),
            ("Top 30% gated", group["rank_pct_in_fold"] >= 0.70),
            ("Bottom 20% gated", group["rank_pct_in_fold"] <= 0.20),
            ("All gated OOS", group["rank_pct_in_fold"] >= 0.00),
        ]

        for selection, mask in selections:
            selected = group.loc[mask].copy()

            if selected.empty:
                continue

            tp_rate = selected["y_true_success"].mean()
            avg_return = selected["tb_return"].mean()

            tp_lift = tp_rate - fold_all_tp
            return_lift = avg_return - fold_all_return

            if selection.startswith("Top") and len(selected) < 3:
                verdict = "Small fold sample"
            elif selection.startswith("Top") and tp_lift > 0.05 and return_lift > 0:
                verdict = "Supportive"
            elif selection.startswith("Top") and return_lift > 0:
                verdict = "Return supportive"
            elif selection.startswith("Top") and return_lift < -0.005:
                verdict = "Weak"
            elif selection.startswith("Bottom") and avg_return < fold_all_return:
                verdict = "Bottom useful"
            else:
                verdict = "Neutral"

            rows.append(
                {
                    "Fold": int(fold),
                    "Selection": selection,
                    "Tickers": ", ".join(sorted(selected["ticker"].astype(str).unique())),
                    "Count": len(selected),
                    "Fold all TP %": fold_all_tp,
                    "Selection TP %": tp_rate,
                    "TP lift vs fold": tp_lift,
                    "Fold all return": fold_all_return,
                    "Selection return": avg_return,
                    "Return lift vs fold": return_lift,
                    "Avg MFE": selected["tb_mfe"].mean(),
                    "Avg MAE": selected["tb_mae"].mean(),
                    "Verdict": verdict,
                }
            )

    return pd.DataFrame(rows)


def build_ticker_gated_manifest_v44(
    gated_summary: pd.DataFrame,
    gated_fold_diag: pd.DataFrame,
    strict_tickers: list[str],
) -> pd.DataFrame:
    """
    Manifest final pour la policy ticker-gated.
    """
    if not strict_tickers:
        return pd.DataFrame(
            [
                {
                    "Decision item": "Ticker-gated policy",
                    "Status": "Rejected",
                    "Detail": "Aucun ticker strictement supportif.",
                }
            ]
        )

    rows = []

    top20 = pd.DataFrame()

    if gated_summary is not None and not gated_summary.empty:
        top20 = gated_summary[gated_summary["Selection"] == "Top 20% gated"]

    if top20.empty:
        rows.append(
            {
                "Decision item": "Top20 gated policy",
                "Status": "Unavailable",
                "Detail": "Aucune sélection Top20 disponible.",
            }
        )
    else:
        row = top20.iloc[0]

        count = int(_safe_float(row.get("Count"), 0) or 0)
        folds = int(_safe_float(row.get("Folds"), 0) or 0)
        tp_lift = _safe_float(row.get("TP lift vs gated all"), 0) or 0
        ret_lift = _safe_float(row.get("Return lift vs gated all"), 0) or 0
        avg_return = _safe_float(row.get("Avg return"), 0) or 0

        if count < 20:
            status = "Small sample"
            detail = f"Top20 gated contient seulement {count} observations."
        elif folds < 4:
            status = "Fold coverage weak"
            detail = f"Top20 gated présent sur {folds} folds seulement."
        elif tp_lift > 0.05 and ret_lift > 0 and avg_return > 0:
            status = "Research positive"
            detail = f"Top20 gated positif : TP lift {tp_lift:.2%}, return lift {ret_lift:.2%}."
        elif ret_lift > 0 and avg_return > 0:
            status = "Watchlist"
            detail = f"Top20 gated return positif mais edge incomplet : return lift {ret_lift:.2%}."
        else:
            status = "Rejected"
            detail = f"Top20 gated insuffisant : TP lift {tp_lift:.2%}, return lift {ret_lift:.2%}."

        rows.append(
            {
                "Decision item": "Top20 gated policy",
                "Status": status,
                "Detail": detail,
            }
        )

    weak_folds = 0
    supportive_folds = 0

    if gated_fold_diag is not None and not gated_fold_diag.empty:
        top20_folds = gated_fold_diag[gated_fold_diag["Selection"] == "Top 20% gated"]

        if not top20_folds.empty:
            weak_folds = int((top20_folds["Verdict"] == "Weak").sum())
            supportive_folds = int(
                top20_folds["Verdict"].isin(["Supportive", "Return supportive"]).sum()
            )

    rows.extend(
        [
            {
                "Decision item": "Strict tickers",
                "Status": "Info",
                "Detail": ", ".join(strict_tickers),
            },
            {
                "Decision item": "Supportive Top20 folds",
                "Status": "OK" if supportive_folds >= 3 else "À surveiller",
                "Detail": f"{supportive_folds} supportive fold(s).",
            },
            {
                "Decision item": "Weak Top20 folds",
                "Status": "À surveiller" if weak_folds > 0 else "OK",
                "Detail": f"{weak_folds} weak fold(s).",
            },
            {
                "Decision item": "Global ranker",
                "Status": "Rejected",
                "Detail": "Le modèle global reste rejeté.",
            },
            {
                "Decision item": "Decision Engine",
                "Status": "Blocked",
                "Detail": "Aucune intégration.",
            },
        ]
    )

    return pd.DataFrame(rows)


    # ============================================================
# V4.5 — STRICT TICKER REGIME + STABILITY DIAGNOSTICS
# ============================================================

def build_strict_ticker_regime_frame_v45(
    panel: pd.DataFrame,
    predictions: pd.DataFrame,
    strict_tickers: list[str],
) -> pd.DataFrame:
    """
    Fusionne les prédictions OOS ticker-gated avec les features de régime.

    Aucun nouveau modèle.
    Aucune probabilité validée.
    Analyse uniquement les tickers strictement supportifs.
    """
    if panel is None or panel.empty:
        return pd.DataFrame()

    if predictions is None or predictions.empty or not strict_tickers:
        return pd.DataFrame()

    required_pred = ["ticker", "date", "Fold", "rank_pct_in_fold", "y_true_success", "tb_return", "tb_mfe", "tb_mae"]

    if any(col not in predictions.columns for col in required_pred):
        return pd.DataFrame()

    pred = predictions[predictions["ticker"].astype(str).isin(strict_tickers)].copy()

    if pred.empty:
        return pd.DataFrame()

    pred["date"] = pd.to_datetime(pred["date"], errors="coerce")

    features = panel.copy()
    features["date"] = pd.to_datetime(features["date"], errors="coerce")

    regime_cols = [
        "ticker",
        "date",
        "vol_20d",
        "vol_60d",
        "atr_pct",
        "drawdown",
        "return_20d",
        "return_60d",
        "price_vs_ema20",
        "price_vs_ema50",
        "rsi_14",
        "volume_zscore",
        "breakout_20d",
        "breakdown_20d",
    ]

    regime_cols = [col for col in regime_cols if col in features.columns]

    merged = pd.merge(
        pred,
        features[regime_cols],
        on=["ticker", "date"],
        how="left",
    )

    if merged.empty:
        return pd.DataFrame()

    numeric_cols = [
        "rank_pct_in_fold",
        "y_true_success",
        "tb_return",
        "tb_mfe",
        "tb_mae",
        "vol_20d",
        "vol_60d",
        "atr_pct",
        "drawdown",
        "return_20d",
        "return_60d",
        "price_vs_ema20",
        "price_vs_ema50",
        "rsi_14",
        "volume_zscore",
        "breakout_20d",
        "breakdown_20d",
    ]

    for col in numeric_cols:
        if col in merged.columns:
            merged[col] = pd.to_numeric(merged[col], errors="coerce")

    merged["rank_selection"] = np.select(
        [
            merged["rank_pct_in_fold"] >= 0.90,
            merged["rank_pct_in_fold"] >= 0.80,
            merged["rank_pct_in_fold"] >= 0.70,
            merged["rank_pct_in_fold"] <= 0.20,
        ],
        [
            "Top 10%",
            "Top 20%",
            "Top 30%",
            "Bottom 20%",
        ],
        default="Middle 40%",
    )

    if "vol_20d" in merged.columns:
        merged["vol_regime"] = _rank_bucket_v35(
            merged["vol_20d"],
            ["Low vol", "Mid vol", "High vol"],
        )

    if "atr_pct" in merged.columns:
        merged["atr_regime"] = _rank_bucket_v35(
            merged["atr_pct"],
            ["Low ATR", "Mid ATR", "High ATR"],
        )

    if "drawdown" in merged.columns:
        merged["drawdown_regime"] = pd.cut(
            merged["drawdown"],
            bins=[-np.inf, -0.15, -0.05, np.inf],
            labels=["Deep drawdown", "Moderate drawdown", "Near highs"],
            include_lowest=True,
        ).astype("object")

    if "rsi_14" in merged.columns:
        merged["rsi_regime"] = pd.cut(
            merged["rsi_14"],
            bins=[-np.inf, 35, 55, 70, np.inf],
            labels=["RSI weak", "RSI neutral", "RSI strong", "RSI extended"],
            include_lowest=True,
        ).astype("object")

    if "return_20d" in merged.columns and "price_vs_ema50" in merged.columns:
        merged["trend_regime"] = np.select(
            [
                (merged["return_20d"] > 0) & (merged["price_vs_ema50"] > 0),
                (merged["return_20d"] < 0) & (merged["price_vs_ema50"] < 0),
            ],
            [
                "Positive trend",
                "Negative trend",
            ],
            default="Mixed trend",
        )

    if "volume_zscore" in merged.columns:
        merged["volume_regime"] = pd.cut(
            merged["volume_zscore"],
            bins=[-np.inf, -0.5, 1.0, np.inf],
            labels=["Low volume", "Normal volume", "High volume"],
            include_lowest=True,
        ).astype("object")

    return merged


def build_strict_ticker_regime_table_v45(regime_frame: pd.DataFrame) -> pd.DataFrame:
    """
    Analyse Top20 gated par régime.
    """
    if regime_frame is None or regime_frame.empty:
        return pd.DataFrame()

    regime_cols = [
        "vol_regime",
        "atr_regime",
        "drawdown_regime",
        "rsi_regime",
        "trend_regime",
        "volume_regime",
    ]

    regime_cols = [col for col in regime_cols if col in regime_frame.columns]

    rows = []

    for regime_col in regime_cols:
        for regime_bucket, group in regime_frame.groupby(regime_col, dropna=True):
            if group.empty:
                continue

            top20 = group[group["rank_pct_in_fold"] >= 0.80]
            bottom20 = group[group["rank_pct_in_fold"] <= 0.20]

            all_tp = group["y_true_success"].mean()
            all_return = group["tb_return"].mean()

            top20_count = len(top20)

            top20_tp = top20["y_true_success"].mean() if not top20.empty else np.nan
            top20_return = top20["tb_return"].mean() if not top20.empty else np.nan
            top20_mfe = top20["tb_mfe"].mean() if not top20.empty else np.nan
            top20_mae = top20["tb_mae"].mean() if not top20.empty else np.nan
            bottom20_return = bottom20["tb_return"].mean() if not bottom20.empty else np.nan

            top20_lift = top20_return - all_return if not pd.isna(top20_return) else np.nan
            tp_lift = top20_tp - all_tp if not pd.isna(top20_tp) else np.nan

            top_vs_bottom = (
                top20_return - bottom20_return
                if not pd.isna(top20_return) and not pd.isna(bottom20_return)
                else np.nan
            )

            if len(group) < 10 or top20_count < 3:
                verdict = "Small sample"
            elif tp_lift > 0.05 and top20_lift > 0 and top_vs_bottom > 0:
                verdict = "Supportive regime"
            elif top20_lift > 0 and top_vs_bottom > 0:
                verdict = "Return supportive"
            elif top20_lift < -0.005 or top_vs_bottom <= 0:
                verdict = "Weak / avoid regime"
            else:
                verdict = "Neutral"

            rows.append(
                {
                    "Regime dimension": regime_col,
                    "Regime bucket": str(regime_bucket),
                    "OOS count": len(group),
                    "Top20 count": top20_count,
                    "All TP %": all_tp,
                    "Top20 TP %": top20_tp,
                    "Top20 TP lift": tp_lift,
                    "All avg return": all_return,
                    "Top20 avg return": top20_return,
                    "Top20 return lift": top20_lift,
                    "Bottom20 avg return": bottom20_return,
                    "Top20 minus Bottom20": top_vs_bottom,
                    "Top20 avg MFE": top20_mfe,
                    "Top20 avg MAE": top20_mae,
                    "Regime verdict": verdict,
                }
            )

    if not rows:
        return pd.DataFrame()

    return pd.DataFrame(rows).sort_values(
        ["Regime dimension", "Regime verdict", "Top20 return lift"],
        ascending=[True, True, False],
    )


def build_strict_ticker_fold_quality_v45(gated_fold_diag: pd.DataFrame) -> pd.DataFrame:
    """
    Résume la qualité fold par fold de la sélection Top20 gated.
    """
    if gated_fold_diag is None or gated_fold_diag.empty:
        return pd.DataFrame()

    top20 = gated_fold_diag[gated_fold_diag["Selection"] == "Top 20% gated"].copy()

    if top20.empty:
        return pd.DataFrame()

    rows = []

    for _, row in top20.iterrows():
        count = int(_safe_float(row.get("Count"), 0) or 0)
        tp_lift = _safe_float(row.get("TP lift vs fold"), 0) or 0
        ret_lift = _safe_float(row.get("Return lift vs fold"), 0) or 0
        selection_return = _safe_float(row.get("Selection return"), 0) or 0
        verdict = str(row.get("Verdict"))

        if count < 5:
            quality = "Small sample"
            detail = "Top20 fold trop petit."
        elif verdict in ["Supportive", "Return supportive"] and ret_lift > 0:
            quality = "OK"
            detail = "Fold favorable en return."
        elif ret_lift < 0:
            quality = "Weak"
            detail = "Top20 sous-performe le fold."
        else:
            quality = "Neutral"
            detail = "Signal incomplet."

        rows.append(
            {
                "Fold": int(row.get("Fold")),
                "Top20 count": count,
                "Top20 TP lift": tp_lift,
                "Top20 return": selection_return,
                "Top20 return lift": ret_lift,
                "Original verdict": verdict,
                "Fold quality": quality,
                "Detail": detail,
            }
        )

    return pd.DataFrame(rows)


def build_strict_ticker_regime_manifest_v45(
    regime_table: pd.DataFrame,
    fold_quality: pd.DataFrame,
    strict_tickers: list[str],
) -> pd.DataFrame:
    """
    Manifest V4.5 : est-ce que le ticker-gated research est stable par régime ?
    """
    supportive = 0
    weak = 0
    small = 0

    if regime_table is not None and not regime_table.empty:
        supportive = int((regime_table["Regime verdict"] == "Supportive regime").sum())
        weak = int((regime_table["Regime verdict"] == "Weak / avoid regime").sum())
        small = int((regime_table["Regime verdict"] == "Small sample").sum())

    ok_folds = 0
    weak_folds = 0
    small_folds = 0

    if fold_quality is not None and not fold_quality.empty:
        ok_folds = int((fold_quality["Fold quality"] == "OK").sum())
        weak_folds = int((fold_quality["Fold quality"] == "Weak").sum())
        small_folds = int((fold_quality["Fold quality"] == "Small sample").sum())

    if ok_folds >= 3 and weak_folds == 0 and weak == 0:
        status = "Research constructive"
        detail = "Ticker-gated policy stable en return, sans régime faible détecté."
    elif ok_folds >= 3 and weak_folds == 0:
        status = "Research watchlist"
        detail = "Policy positive mais certains régimes restent à surveiller."
    elif small_folds > 0:
        status = "Sample constrained"
        detail = "Policy intéressante mais limitée par le nombre d'observations."
    else:
        status = "Rejected"
        detail = "Stabilité insuffisante."

    rows = [
        {
            "Decision item": "Strict ticker regime status",
            "Status": status,
            "Detail": detail,
        },
        {
            "Decision item": "Strict tickers",
            "Status": "Info",
            "Detail": ", ".join(strict_tickers) if strict_tickers else "None",
        },
        {
            "Decision item": "Supportive regimes",
            "Status": "OK" if supportive > 0 else "Info",
            "Detail": f"{supportive} regime bucket(s).",
        },
        {
            "Decision item": "Weak regimes",
            "Status": "À surveiller" if weak > 0 else "OK",
            "Detail": f"{weak} regime bucket(s).",
        },
        {
            "Decision item": "Small sample regimes",
            "Status": "Info",
            "Detail": f"{small} regime bucket(s).",
        },
        {
            "Decision item": "OK Top20 folds",
            "Status": "OK" if ok_folds >= 3 else "À surveiller",
            "Detail": f"{ok_folds} fold(s).",
        },
        {
            "Decision item": "Weak Top20 folds",
            "Status": "À surveiller" if weak_folds > 0 else "OK",
            "Detail": f"{weak_folds} fold(s).",
        },
        {
            "Decision item": "Small Top20 folds",
            "Status": "Info",
            "Detail": f"{small_folds} fold(s).",
        },
        {
            "Decision item": "Decision Engine",
            "Status": "Blocked",
            "Detail": "Aucune intégration.",
        },
    ]

    return pd.DataFrame(rows)


# ============================================================
# V4.6 — STRICT TICKER SHADOW SCORE, AMD-ONLY / RESEARCH-ONLY
# ============================================================

def _gated_selection_from_rank_pct_v46(rank_pct: float) -> str:
    """
    Convertit un percentile de rang en bucket gated.
    Ce n'est pas une probabilité.
    """
    rank_pct = _safe_float(rank_pct, 0) or 0

    if rank_pct >= 0.90:
        return "Top 10% gated"
    if rank_pct >= 0.80:
        return "Top 20% gated"
    if rank_pct >= 0.70:
        return "Top 30% gated"
    if rank_pct <= 0.20:
        return "Bottom 20% gated"

    return "Middle 40% gated"


def build_strict_ticker_current_shadow_score_v46(
    panel: pd.DataFrame,
    predictions: pd.DataFrame,
    strict_tickers: list[str],
    model_name: str = "Logistic strong regularization",
) -> pd.DataFrame:
    """
    Score shadow courant sur les tickers strictement supportifs.

    Important :
    - entraîne un modèle uniquement pour produire un score de recherche courant ;
    - compare ce score à la distribution OOS déjà observée ;
    - ne valide aucune probabilité ;
    - ne branche rien au Decision Engine.
    """
    if not SKLEARN_AVAILABLE:
        return pd.DataFrame()

    if panel is None or panel.empty or not strict_tickers:
        return pd.DataFrame()

    work = _ensure_panel_event_dates_v41(panel)

    if work.empty:
        return pd.DataFrame()

    feature_cols = get_eligible_feature_columns_v30(work)

    if not feature_cols:
        return pd.DataFrame()

    rows = []

    for strict_ticker in strict_tickers:
        ticker_df = work[work["ticker"].astype(str) == str(strict_ticker)].copy()

        if ticker_df.empty:
            continue

        ticker_df["date"] = pd.to_datetime(ticker_df["date"], errors="coerce")
        ticker_df = ticker_df.dropna(subset=["date"]).sort_values("date")

        if ticker_df.empty:
            continue

        latest_row = ticker_df.iloc[[-1]].copy()
        latest_date = latest_row["date"].iloc[0]

        train = work.dropna(subset=["tb_label", "date"]).copy()
        train["date"] = pd.to_datetime(train["date"], errors="coerce")

        # Ne pas utiliser la date courante dans le train si elle existe.
        train = train[train["date"] < latest_date].copy()

        if len(train) < 300:
            rows.append(
                {
                    "Ticker": strict_ticker,
                    "Item": "Shadow score",
                    "Status": "Unavailable",
                    "Value": "N/A",
                    "Interpretation": "Train panel trop court pour scorer.",
                }
            )
            continue

        y_train = (train["tb_label"].astype(float) == 1.0).astype(int)

        if y_train.nunique() < 2:
            rows.append(
                {
                    "Ticker": strict_ticker,
                    "Item": "Shadow score",
                    "Status": "Unavailable",
                    "Value": "N/A",
                    "Interpretation": "Train single-class.",
                }
            )
            continue

        X_train = train[feature_cols].copy().replace([np.inf, -np.inf], np.nan)
        X_latest = latest_row[feature_cols].copy().replace([np.inf, -np.inf], np.nan)

        try:
            model = _make_cross_sectional_ranker_v42(model_name)
            model.fit(X_train, y_train)

            raw_probability = float(model.predict_proba(X_latest)[:, 1][0])

            ref_probs = pd.Series(dtype=float)
            reference_source = "Unavailable"

            if predictions is not None and not predictions.empty:
                ref = predictions[
                    predictions["ticker"].astype(str) == str(strict_ticker)
                ].copy()

                if "p_raw" in ref.columns:
                    ref_probs = pd.to_numeric(ref["p_raw"], errors="coerce").dropna()
                    reference_source = f"OOS {strict_ticker} predictions"

            if ref_probs.empty:
                ref_probs = pd.Series(model.predict_proba(X_train)[:, 1])
                reference_source = "In-sample fallback"

            rank_pct = float((ref_probs <= raw_probability).mean())
            rank_bucket = _gated_selection_from_rank_pct_v46(rank_pct)

            rows.extend(
                [
                    {
                        "Ticker": strict_ticker,
                        "Item": "Latest date",
                        "Status": "Info",
                        "Value": latest_date.strftime("%Y-%m-%d"),
                        "Interpretation": "Dernière observation scorée.",
                    },
                    {
                        "Ticker": strict_ticker,
                        "Item": "Model",
                        "Status": "Research",
                        "Value": model_name,
                        "Interpretation": "Modèle utilisé en shadow uniquement.",
                    },
                    {
                        "Ticker": strict_ticker,
                        "Item": "Raw model probability",
                        "Status": "Blocked",
                        "Value": _fmt_pct(raw_probability),
                        "Interpretation": "Probabilité brute non calibrée : ne pas utiliser comme vraie probabilité.",
                    },
                    {
                        "Ticker": strict_ticker,
                        "Item": "Shadow rank percentile",
                        "Status": "Research",
                        "Value": _fmt_pct(rank_pct),
                        "Interpretation": f"Position relative vs {reference_source}.",
                    },
                    {
                        "Ticker": strict_ticker,
                        "Item": "Current gated bucket",
                        "Status": "Research",
                        "Value": rank_bucket,
                        "Interpretation": "Bucket de rang expérimental, pas un signal de trading.",
                    },
                    {
                        "Ticker": strict_ticker,
                        "Item": "Reference count",
                        "Status": "Info",
                        "Value": str(len(ref_probs)),
                        "Interpretation": "Nombre d'observations utilisées pour le percentile.",
                    },
                    {
                        "Ticker": strict_ticker,
                        "Item": "Training labels",
                        "Status": "Info",
                        "Value": str(len(train)),
                        "Interpretation": f"TP train rate {_fmt_pct(y_train.mean())}.",
                    },
                    {
                        "Ticker": strict_ticker,
                        "Item": "Decision Engine integration",
                        "Status": "Blocked",
                        "Value": "No",
                        "Interpretation": "Aucune intégration autorisée.",
                    },
                ]
            )

        except Exception as e:
            rows.append(
                {
                    "Ticker": strict_ticker,
                    "Item": "Shadow score",
                    "Status": "Error",
                    "Value": str(e)[:120],
                    "Interpretation": "Erreur pendant le scoring shadow.",
                }
            )

    return pd.DataFrame(rows)


def build_strict_ticker_policy_reference_v46(
    shadow_score_df: pd.DataFrame,
    gated_summary_v44: pd.DataFrame,
) -> pd.DataFrame:
    """
    Relie le bucket courant à la performance OOS V4.4.
    """
    if shadow_score_df is None or shadow_score_df.empty:
        return pd.DataFrame()

    if gated_summary_v44 is None or gated_summary_v44.empty:
        return pd.DataFrame()

    bucket_rows = shadow_score_df[shadow_score_df["Item"] == "Current gated bucket"]

    if bucket_rows.empty:
        return pd.DataFrame()

    rows = []

    for _, bucket_row in bucket_rows.iterrows():
        ticker = str(bucket_row.get("Ticker"))
        current_bucket = str(bucket_row.get("Value"))

        ref = gated_summary_v44[gated_summary_v44["Selection"] == current_bucket].copy()

        if ref.empty:
            rows.append(
                {
                    "Ticker": ticker,
                    "Metric": "Policy reference",
                    "Value": "Unavailable",
                    "Interpretation": f"Aucune référence OOS pour {current_bucket}.",
                }
            )
            continue

        r = ref.iloc[0]

        rows.extend(
            [
                {
                    "Ticker": ticker,
                    "Metric": "Current gated bucket",
                    "Value": current_bucket,
                    "Interpretation": "Bucket shadow courant.",
                },
                {
                    "Ticker": ticker,
                    "Metric": "OOS count",
                    "Value": str(int(r.get("Count", 0))),
                    "Interpretation": "Nombre d'observations OOS dans ce bucket.",
                },
                {
                    "Ticker": ticker,
                    "Metric": "OOS folds",
                    "Value": str(int(r.get("Folds", 0))),
                    "Interpretation": "Nombre de folds couverts par ce bucket.",
                },
                {
                    "Ticker": ticker,
                    "Metric": "OOS TP %",
                    "Value": _fmt_pct(r.get("TP %")),
                    "Interpretation": "Hit rate historique du bucket.",
                },
                {
                    "Ticker": ticker,
                    "Metric": "OOS avg return",
                    "Value": _fmt_pct(r.get("Avg return")),
                    "Interpretation": "Return moyen historique du bucket.",
                },
                {
                    "Ticker": ticker,
                    "Metric": "OOS TP lift",
                    "Value": _fmt_pct(r.get("TP lift vs gated all")),
                    "Interpretation": "Lift hit rate vs AMD all OOS.",
                },
                {
                    "Ticker": ticker,
                    "Metric": "OOS return lift",
                    "Value": _fmt_pct(r.get("Return lift vs gated all")),
                    "Interpretation": "Lift return vs AMD all OOS.",
                },
                {
                    "Ticker": ticker,
                    "Metric": "Gated all return",
                    "Value": _fmt_pct(r.get("Gated all return")),
                    "Interpretation": "Return moyen AMD OOS complet.",
                },
            ]
        )

    return pd.DataFrame(rows)


def build_strict_ticker_current_regime_snapshot_v46(
    panel: pd.DataFrame,
    strict_tickers: list[str],
) -> pd.DataFrame:
    """
    Snapshot régime courant pour les tickers strictement supportifs.
    """
    if panel is None or panel.empty or not strict_tickers:
        return pd.DataFrame()

    work = panel.copy()
    work["date"] = pd.to_datetime(work["date"], errors="coerce")

    rows = []

    for strict_ticker in strict_tickers:
        ticker_df = work[work["ticker"].astype(str) == str(strict_ticker)].copy()
        ticker_df = ticker_df.dropna(subset=["date"]).sort_values("date")

        if ticker_df.empty:
            continue

        latest = ticker_df.iloc[-1]

        def pct_bucket(col, low_label, mid_label, high_label):
            if col not in ticker_df.columns:
                return None, "Unavailable"

            series = pd.to_numeric(ticker_df[col], errors="coerce").dropna()
            value = _safe_float(latest.get(col))

            if value is None or series.empty:
                return value, "Unavailable"

            pct = float((series <= value).mean())

            if pct <= 1 / 3:
                bucket = low_label
            elif pct <= 2 / 3:
                bucket = mid_label
            else:
                bucket = high_label

            return value, f"{bucket} ({_fmt_pct(pct)})"

        latest_date = latest.get("date")

        rows.append(
            {
                "Ticker": strict_ticker,
                "Regime feature": "date",
                "Current value": latest_date.strftime("%Y-%m-%d") if not pd.isna(latest_date) else "N/A",
                "Regime bucket": "Latest",
                "Interpretation": "Dernière observation disponible.",
            }
        )

        value, bucket = pct_bucket("vol_20d", "Low vol", "Mid vol", "High vol")
        rows.append(
            {
                "Ticker": strict_ticker,
                "Regime feature": "vol_20d",
                "Current value": _fmt_pct(value),
                "Regime bucket": bucket,
                "Interpretation": "Volatilité 20 jours relative à l'historique du ticker.",
            }
        )

        value, bucket = pct_bucket("atr_pct", "Low ATR", "Mid ATR", "High ATR")
        rows.append(
            {
                "Ticker": strict_ticker,
                "Regime feature": "atr_pct",
                "Current value": _fmt_pct(value),
                "Regime bucket": bucket,
                "Interpretation": "Amplitude ATR relative au prix.",
            }
        )

        if "drawdown" in ticker_df.columns:
            dd = _safe_float(latest.get("drawdown"))

            if dd is not None:
                if dd <= -0.15:
                    dd_bucket = "Deep drawdown"
                elif dd <= -0.05:
                    dd_bucket = "Moderate drawdown"
                else:
                    dd_bucket = "Near highs"

                rows.append(
                    {
                        "Ticker": strict_ticker,
                        "Regime feature": "drawdown",
                        "Current value": _fmt_pct(dd),
                        "Regime bucket": dd_bucket,
                        "Interpretation": "Position relative aux plus hauts de la fenêtre.",
                    }
                )

        if "rsi_14" in ticker_df.columns:
            rsi = _safe_float(latest.get("rsi_14"))

            if rsi is not None:
                if rsi <= 35:
                    rsi_bucket = "RSI weak"
                elif rsi <= 55:
                    rsi_bucket = "RSI neutral"
                elif rsi <= 70:
                    rsi_bucket = "RSI strong"
                else:
                    rsi_bucket = "RSI extended"

                rows.append(
                    {
                        "Ticker": strict_ticker,
                        "Regime feature": "rsi_14",
                        "Current value": _fmt_num(rsi),
                        "Regime bucket": rsi_bucket,
                        "Interpretation": "Momentum RSI courant.",
                    }
                )

        if "return_20d" in ticker_df.columns and "price_vs_ema50" in ticker_df.columns:
            r20 = _safe_float(latest.get("return_20d"))
            ema50_gap = _safe_float(latest.get("price_vs_ema50"))

            if r20 is not None and ema50_gap is not None:
                if r20 > 0 and ema50_gap > 0:
                    trend_bucket = "Positive trend"
                elif r20 < 0 and ema50_gap < 0:
                    trend_bucket = "Negative trend"
                else:
                    trend_bucket = "Mixed trend"

                rows.append(
                    {
                        "Ticker": strict_ticker,
                        "Regime feature": "trend_proxy",
                        "Current value": f"20D {_fmt_pct(r20)} / vs EMA50 {_fmt_pct(ema50_gap)}",
                        "Regime bucket": trend_bucket,
                        "Interpretation": "Proxy simple de régime de tendance.",
                    }
                )

        value, bucket = pct_bucket("volume_zscore", "Low volume", "Normal volume", "High volume")
        rows.append(
            {
                "Ticker": strict_ticker,
                "Regime feature": "volume_zscore",
                "Current value": _fmt_num(value),
                "Regime bucket": bucket,
                "Interpretation": "Volume relatif au régime historique.",
            }
        )

    return pd.DataFrame(rows)


