# ============================================================
# V4.6.1 — SHADOW DECISION CARD / INTERPRETATION LAYER
# ============================================================

def _extract_shadow_value_v461(shadow_score_df: pd.DataFrame, item: str):
    if shadow_score_df is None or shadow_score_df.empty:
        return None

    rows = shadow_score_df[shadow_score_df["Item"] == item]

    if rows.empty:
        return None

    return rows.iloc[0].get("Value")


def _extract_policy_value_v461(policy_reference_df: pd.DataFrame, metric: str):
    if policy_reference_df is None or policy_reference_df.empty:
        return None

    rows = policy_reference_df[policy_reference_df["Metric"] == metric]

    if rows.empty:
        return None

    return rows.iloc[0].get("Value")


def _extract_regime_bucket_v461(regime_snapshot_df: pd.DataFrame, feature: str):
    if regime_snapshot_df is None or regime_snapshot_df.empty:
        return None

    rows = regime_snapshot_df[regime_snapshot_df["Regime feature"] == feature]

    if rows.empty:
        return None

    return rows.iloc[0].get("Regime bucket")


def build_shadow_decision_card_v461(
    shadow_score_df: pd.DataFrame,
    policy_reference_df: pd.DataFrame,
    regime_snapshot_df: pd.DataFrame,
) -> pd.DataFrame:
    """
    Carte d'interprétation V4.6.1.

    Elle ne crée aucun signal.
    Elle transforme le shadow score en verdict research-only lisible.
    """
    if shadow_score_df is None or shadow_score_df.empty:
        return pd.DataFrame()

    ticker_rows = shadow_score_df["Ticker"].dropna().astype(str).unique().tolist()
    ticker = ticker_rows[0] if ticker_rows else "N/A"

    bucket = _extract_shadow_value_v461(shadow_score_df, "Current gated bucket")
    rank_pct = _extract_shadow_value_v461(shadow_score_df, "Shadow rank percentile")
    raw_prob = _extract_shadow_value_v461(shadow_score_df, "Raw model probability")

    oos_tp = _extract_policy_value_v461(policy_reference_df, "OOS TP %")
    oos_return = _extract_policy_value_v461(policy_reference_df, "OOS avg return")
    oos_return_lift = _extract_policy_value_v461(policy_reference_df, "OOS return lift")

    vol_bucket = _extract_regime_bucket_v461(regime_snapshot_df, "vol_20d")
    atr_bucket = _extract_regime_bucket_v461(regime_snapshot_df, "atr_pct")
    dd_bucket = _extract_regime_bucket_v461(regime_snapshot_df, "drawdown")
    trend_bucket = _extract_regime_bucket_v461(regime_snapshot_df, "trend_proxy")
    volume_bucket = _extract_regime_bucket_v461(regime_snapshot_df, "volume_zscore")

    bucket_str = str(bucket)

    if bucket_str in ["Top 10% gated", "Top 20% gated"]:
        shadow_status = "High-rank research setup"
        shadow_detail = "Le ticker est dans le haut du ranking shadow."
    elif bucket_str == "Top 30% gated":
        shadow_status = "Moderate-rank research setup"
        shadow_detail = "Le ticker est dans une zone supérieure mais pas top-conviction."
    elif bucket_str == "Middle 40% gated":
        shadow_status = "Watchlist only"
        shadow_detail = "Le ticker est au milieu de la distribution : pas d'edge ML fort courant."
    elif bucket_str == "Bottom 20% gated":
        shadow_status = "Avoid / no edge"
        shadow_detail = "Le ticker est en bas de ranking shadow."
    else:
        shadow_status = "Unknown"
        shadow_detail = "Bucket courant non reconnu."

    regime_flags = []

    if vol_bucket is not None and "High vol" in str(vol_bucket):
        regime_flags.append("high volatility")

    if atr_bucket is not None and "High ATR" in str(atr_bucket):
        regime_flags.append("high ATR")

    if dd_bucket is not None and "Deep drawdown" in str(dd_bucket):
        regime_flags.append("deep drawdown")

    if volume_bucket is not None and "Low volume" in str(volume_bucket):
        regime_flags.append("low volume")

    if trend_bucket is not None and "Positive trend" in str(trend_bucket):
        trend_status = "Constructive trend"
    elif trend_bucket is not None and "Negative trend" in str(trend_bucket):
        trend_status = "Negative trend"
    else:
        trend_status = "Mixed/neutral trend"

    if regime_flags:
        regime_status = "Risk regime elevated"
        regime_detail = "Régime courant : " + ", ".join(regime_flags) + "."
    else:
        regime_status = "Regime acceptable"
        regime_detail = "Aucun flag régime majeur détecté."

    if shadow_status in ["High-rank research setup", "Moderate-rank research setup"] and regime_status != "Risk regime elevated":
        final_status = "Research positive"
        final_detail = "Setup shadow favorable, mais toujours non promouvable."
    elif shadow_status in ["High-rank research setup", "Moderate-rank research setup"] and regime_status == "Risk regime elevated":
        final_status = "Research positive but regime-risky"
        final_detail = "Ranking favorable mais régime risqué : prudence maximale."
    elif shadow_status == "Watchlist only":
        final_status = "Watchlist only"
        final_detail = "Pas de signal ML fort courant malgré une référence OOS constructive."
    else:
        final_status = "No active ML edge"
        final_detail = "Aucun avantage ML exploitable à ce stade."

    rows = [
        {
            "Decision item": "Ticker",
            "Status": "Strict research ticker",
            "Detail": ticker,
        },
        {
            "Decision item": "Current shadow bucket",
            "Status": shadow_status,
            "Detail": f"{bucket_str} · percentile {rank_pct}. {shadow_detail}",
        },
        {
            "Decision item": "Raw probability",
            "Status": "Blocked",
            "Detail": f"{raw_prob}. Non calibrée, interdite comme probabilité.",
        },
        {
            "Decision item": "OOS bucket reference",
            "Status": "Info",
            "Detail": f"TP {oos_tp}, return {oos_return}, return lift {oos_return_lift}.",
        },
        {
            "Decision item": "Trend regime",
            "Status": trend_status,
            "Detail": str(trend_bucket),
        },
        {
            "Decision item": "Risk regime",
            "Status": regime_status,
            "Detail": regime_detail,
        },
        {
            "Decision item": "Final research verdict",
            "Status": final_status,
            "Detail": final_detail,
        },
        {
            "Decision item": "Decision Engine",
            "Status": "Blocked",
            "Detail": "Aucune intégration. Aucun signal BUY/SELL.",
        },
    ]

    return pd.DataFrame(rows)


# ============================================================
# V4.7 — ML RESEARCH PROMOTION GATE
# ============================================================

def _manifest_lookup_v47(
    df: pd.DataFrame,
    item_col: str,
    item_value: str,
    status_col: str = "Status",
    detail_col: str = "Detail",
) -> tuple[str, str]:
    """
    Lookup robuste dans un manifest.
    """
    if df is None or df.empty:
        return "Unavailable", "Manifest indisponible."

    if item_col not in df.columns:
        return "Unavailable", f"Colonne {item_col} absente."

    rows = df[df[item_col].astype(str) == str(item_value)]

    if rows.empty:
        return "Unavailable", f"{item_value} absent du manifest."

    row = rows.iloc[0]

    status = str(row.get(status_col, "N/A"))
    detail = str(row.get(detail_col, "N/A"))

    return status, detail


def build_ml_research_promotion_gate_v47(
    strict_manifest_v431: pd.DataFrame,
    gated_manifest_v44: pd.DataFrame,
    regime_manifest_v45: pd.DataFrame,
    decision_card_v461: pd.DataFrame,
) -> pd.DataFrame:
    """
    Gate final de promotion ML.

    Important :
    - ne crée aucun modèle ;
    - ne crée aucun signal ;
    - sert à empêcher la promotion d'une couche research fragile ;
    - Decision Engine reste bloqué.
    """
    rows = []

    global_status, global_detail = _manifest_lookup_v47(
        strict_manifest_v431,
        item_col="Decision item",
        item_value="Global ranker",
    )

    strict_gate_status, strict_gate_detail = _manifest_lookup_v47(
        strict_manifest_v431,
        item_col="Decision item",
        item_value="Strict ticker gate",
    )

    top20_policy_status, top20_policy_detail = _manifest_lookup_v47(
        gated_manifest_v44,
        item_col="Decision item",
        item_value="Top20 gated policy",
    )

    regime_status, regime_detail = _manifest_lookup_v47(
        regime_manifest_v45,
        item_col="Decision item",
        item_value="Strict ticker regime status",
    )

    current_bucket_status, current_bucket_detail = _manifest_lookup_v47(
        decision_card_v461,
        item_col="Decision item",
        item_value="Current shadow bucket",
    )

    final_research_status, final_research_detail = _manifest_lookup_v47(
        decision_card_v461,
        item_col="Decision item",
        item_value="Final research verdict",
    )

    risk_status, risk_detail = _manifest_lookup_v47(
        decision_card_v461,
        item_col="Decision item",
        item_value="Risk regime",
    )

    # Règles de blocage.
    hard_blocks = []

    if global_status == "Rejected":
        hard_blocks.append("global ranker rejected")

    if current_bucket_status not in [
        "High-rank research setup",
        "Moderate-rank research setup",
    ]:
        hard_blocks.append("current bucket not top-ranked")

    if final_research_status not in [
        "Research positive",
        "Research positive but regime-risky",
    ]:
        hard_blocks.append("no active shadow edge")

    hard_blocks.append("raw probabilities uncalibrated")
    hard_blocks.append("single-ticker research scope")
    hard_blocks.append("Decision Engine blocked by policy")

    if final_research_status == "Research positive":
        active_edge_status = "Shadow positive"
        active_edge_detail = "Score courant favorable en recherche uniquement."
    elif final_research_status == "Research positive but regime-risky":
        active_edge_status = "Shadow positive / regime risky"
        active_edge_detail = "Score courant favorable mais régime risqué."
    elif final_research_status == "Watchlist only":
        active_edge_status = "Watchlist only"
        active_edge_detail = "Score courant non top-ranked."
    else:
        active_edge_status = "No active edge"
        active_edge_detail = "Aucun avantage ML actif détecté."

    if current_bucket_status in [
        "High-rank research setup",
        "Moderate-rank research setup",
    ]:
        shadow_bucket_gate = "Pass research"
    else:
        shadow_bucket_gate = "Fail current edge"

    promotion_status = "Blocked"

    if final_research_status in [
        "Research positive",
        "Research positive but regime-risky",
    ]:
        research_state = "Research active / non-promotable"
    elif final_research_status == "Watchlist only":
        research_state = "Watchlist / inactive"
    else:
        research_state = "Rejected / inactive"

    rows.extend(
        [
            {
                "Gate item": "Global model",
                "Status": global_status,
                "Detail": global_detail,
            },
            {
                "Gate item": "Strict ticker scope",
                "Status": strict_gate_status,
                "Detail": strict_gate_detail,
            },
            {
                "Gate item": "Ticker-gated Top20 policy",
                "Status": top20_policy_status,
                "Detail": top20_policy_detail,
            },
            {
                "Gate item": "Regime stability",
                "Status": regime_status,
                "Detail": regime_detail,
            },
            {
                "Gate item": "Current bucket gate",
                "Status": shadow_bucket_gate,
                "Detail": current_bucket_detail,
            },
            {
                "Gate item": "Current active edge",
                "Status": active_edge_status,
                "Detail": active_edge_detail,
            },
            {
                "Gate item": "Risk regime",
                "Status": risk_status,
                "Detail": risk_detail,
            },
            {
                "Gate item": "Research state",
                "Status": research_state,
                "Detail": final_research_detail,
            },
            {
                "Gate item": "Promotion eligibility",
                "Status": promotion_status,
                "Detail": "Blocked reasons: " + ", ".join(hard_blocks) + ".",
            },
            {
                "Gate item": "Decision Engine",
                "Status": "Blocked",
                "Detail": "Aucune intégration autorisée.",
            },
        ]
    )

    return pd.DataFrame(rows)


def build_ml_research_next_actions_v47(promotion_gate_v47: pd.DataFrame) -> pd.DataFrame:
    """
    Actions recommandées selon le gate final.
    """
    if promotion_gate_v47 is None or promotion_gate_v47.empty:
        return pd.DataFrame()

    active_edge_status, _ = _manifest_lookup_v47(
        promotion_gate_v47,
        item_col="Gate item",
        item_value="Current active edge",
    )

    current_bucket_status, _ = _manifest_lookup_v47(
        promotion_gate_v47,
        item_col="Gate item",
        item_value="Current bucket gate",
    )

    rows = [
        {
            "Action": "Decision Engine",
            "Priority": "Hard block",
            "Instruction": "Ne rien connecter au Decision Engine.",
        },
        {
            "Action": "Probability usage",
            "Priority": "Hard block",
            "Instruction": "Ne jamais afficher la raw probability comme probabilité exploitable.",
        },
    ]

    if current_bucket_status == "Fail current edge":
        rows.append(
            {
                "Action": "Current ticker monitoring",
                "Priority": "High",
                "Instruction": "Garder AMD en watchlist ML. Attendre un passage Top30/Top20 avant interprétation positive.",
            }
        )

    if active_edge_status == "Watchlist only":
        rows.append(
            {
                "Action": "Research interpretation",
                "Priority": "High",
                "Instruction": "Pas d'edge ML actif aujourd'hui. Le modèle est informatif, pas actionnable.",
            }
        )

    rows.extend(
        [
            {
                "Action": "Historical robustness",
                "Priority": "Medium",
                "Instruction": "Relancer avec 2y/5y d'historique pour vérifier si AMD reste strict supportive.",
            },
            {
                "Action": "Universe robustness",
                "Priority": "Medium",
                "Instruction": "Tester un univers semi-conducteurs plus large avant tout modèle avancé.",
            },
            {
                "Action": "Feature enrichment",
                "Priority": "Medium",
                "Instruction": "Ajouter features régime/liquidité/relative strength avant LightGBM ou modèle non linéaire.",
            },
            {
                "Action": "Model promotion",
                "Priority": "Blocked",
                "Instruction": "Promotion interdite tant que le modèle global est rejeté et que le score courant n'est pas top-ranked.",
            },
        ]
    )

    return pd.DataFrame(rows)


