# Paste this block just before def render_ml_research_lab_v1(...),
# then add the single render call provided after this block.
# Scope: research/shadow only. No Decision Engine integration.

import io
import zipfile
from datetime import datetime


def _mlqa_safe_df(obj):
    if isinstance(obj, pd.DataFrame):
        return obj.copy()
    return pd.DataFrame()


def _mlqa_safe_dict(obj):
    if isinstance(obj, dict):
        return obj
    return {}


def _mlqa_get_dict(container, key):
    if isinstance(container, dict) and isinstance(container.get(key), dict):
        return container.get(key)
    return {}


def _mlqa_get_df(container, key, default=None):
    if default is None:
        default = pd.DataFrame()
    if isinstance(container, dict):
        return _mlqa_safe_df(container.get(key, default))
    return pd.DataFrame()


def _mlqa_safe_float(value, default=np.nan):
    try:
        if value is None:
            return default
        if pd.isna(value):
            return default
        return float(value)
    except Exception:
        return default


def _mlqa_fmt_pct(value):
    value = _mlqa_safe_float(value, None)
    if value is None or pd.isna(value):
        return "N/A"
    return f"{value:.2%}"


def _mlqa_fmt_num(value):
    value = _mlqa_safe_float(value, None)
    if value is None or pd.isna(value):
        return "N/A"
    return f"{value:,.2f}"


def _mlqa_fmt_pct_cols(df, cols):
    if df is None or df.empty:
        return pd.DataFrame()
    out = df.copy()
    for col in cols:
        if col in out.columns:
            out[col] = out[col].apply(_mlqa_fmt_pct)
    return out


def _mlqa_contains_blocked_status(df, item_keywords=None):
    if df is None or df.empty:
        return False
    item_keywords = item_keywords or []
    text = df.astype(str).agg(" ".join, axis=1)
    if item_keywords:
        mask = pd.Series(False, index=df.index)
        for keyword in item_keywords:
            mask = mask | text.str.contains(str(keyword), case=False, na=False)
        text = text[mask]
    if text.empty:
        return False
    return bool(text.str.contains("Blocked|OFF|No|Aucune intégration|aucune integration", case=False, na=False).any())


def _mlqa_find_status(df, key_col_candidates, key_value, status_col_candidates):
    if df is None or df.empty:
        return "Unavailable"
    key_col = None
    status_col = None
    for col in key_col_candidates:
        if col in df.columns:
            key_col = col
            break
    for col in status_col_candidates:
        if col in df.columns:
            status_col = col
            break
    if key_col is None or status_col is None:
        return "Unavailable"
    mask = df[key_col].astype(str).str.contains(str(key_value), case=False, na=False)
    if not mask.any():
        return "Unavailable"
    return str(df.loc[mask, status_col].iloc[0])


