def build_ml_research_evidence_report_v76(
    ticker,
    v50_results,
    v511_results,
    v52_results,
    suite_v53_v63,
    completion_v64_v72,
    test_manifest_v73,
    shadow_manifest_v75,
    current_run_v74,
):
    v50_results = _mlqa_safe_dict(v50_results)
    v511_results = _mlqa_safe_dict(v511_results)
    v52_results = _mlqa_safe_dict(v52_results)
    completion_v64_v72 = _mlqa_safe_dict(completion_v64_v72)

    enriched_panel = _mlqa_get_df(v50_results, "enriched_panel")
    shortlist = _mlqa_get_df(v511_results, "shortlist")
    predictions = _mlqa_get_df(v52_results, "predictions")
    folds = _mlqa_get_df(v52_results, "folds")
    cumulative = _mlqa_get_df(v52_results, "cumulative_summary")
    final_manifest = _mlqa_get_df(completion_v64_v72, "final_manifest")

    labels = int(enriched_panel["tb_label"].notna().sum()) if (not enriched_panel.empty and "tb_label" in enriched_panel.columns) else 0
    tickers = int(enriched_panel["ticker"].nunique()) if (not enriched_panel.empty and "ticker" in enriched_panel.columns) else 0
    features = len(shortlist) if not shortlist.empty else 0
    oos_predictions = len(predictions) if not predictions.empty else 0

    run_identity = pd.DataFrame(
        [
            {"Field": "Report UTC", "Value": datetime.utcnow().strftime("%Y-%m-%d %H:%M:%S")},
            {"Field": "Ticker context", "Value": str(ticker)},
            {"Field": "Scope", "Value": "Research-only ML stack audit"},
            {"Field": "Decision Engine", "Value": "Blocked"},
            {"Field": "Probability usage", "Value": "Blocked"},
        ]
    )

    data_scope = pd.DataFrame(
        [
            {"Metric": "Panel rows", "Value": len(enriched_panel)},
            {"Metric": "Tickers", "Value": tickers},
            {"Metric": "Labels", "Value": labels},
            {"Metric": "Shortlist features", "Value": features},
            {"Metric": "OOS predictions", "Value": oos_predictions},
            {"Metric": "OOS folds", "Value": len(folds)},
        ]
    )

    usage_policy = pd.DataFrame(
        [
            {"Policy item": "Allowed", "Status": "Research", "Detail": "Diagnostics, rank analysis, run comparison, evidence report."},
            {"Policy item": "Blocked", "Status": "Hard block", "Detail": "Decision Engine connection."},
            {"Policy item": "Blocked", "Status": "Hard block", "Detail": "Raw probability as tradable probability."},
            {"Policy item": "Blocked", "Status": "Hard block", "Detail": "BUY/SELL signal creation."},
            {"Policy item": "Next validation", "Status": "Required", "Detail": "Multi-run robustness, longer history, ticker universe expansion, calibration after evidence only."},
        ]
    )

    return {
        "run_identity": run_identity,
        "data_scope": data_scope,
        "feature_shortlist": shortlist,
        "fold_results": folds,
        "cumulative_summary": cumulative,
        "test_manifest_v73": _mlqa_safe_df(test_manifest_v73),
        "shadow_manifest_v75": _mlqa_safe_df(shadow_manifest_v75),
        "current_run_v74": _mlqa_safe_df(current_run_v74),
        "final_guardrail": final_manifest,
        "usage_policy": usage_policy,
    }


def make_ml_research_report_zip_v76(report_dict):
    report_dict = _mlqa_safe_dict(report_dict)
    buffer = io.BytesIO()
    with zipfile.ZipFile(buffer, mode="w", compression=zipfile.ZIP_DEFLATED) as zf:
        for name, df in report_dict.items():
            safe_df = _mlqa_safe_df(df)
            if safe_df.empty:
                continue
            zf.writestr(f"{name}.csv", safe_df.to_csv(index=False))
    buffer.seek(0)
    return buffer.getvalue()


