def build_ml_feature_store_signature_v77(
    ticker,
    v50_results,
    v511_results,
    v52_results,
    completion_v64_v72,
    panel_period="",
    panel_interval="",
    panel_horizon=None,
    panel_pt=None,
    panel_sl=None,
):
    v50_results = _mlqa_safe_dict(v50_results)
    v511_results = _mlqa_safe_dict(v511_results)
    v52_results = _mlqa_safe_dict(v52_results)
    completion_v64_v72 = _mlqa_safe_dict(completion_v64_v72)

    enriched_panel = _mlqa_get_df(v50_results, "enriched_panel")
    shortlist = _mlqa_get_df(v511_results, "shortlist")
    predictions = _mlqa_get_df(v52_results, "predictions")
    final_manifest = _mlqa_get_df(completion_v64_v72, "final_manifest")

    if not enriched_panel.empty and "date" in enriched_panel.columns:
        dates = pd.to_datetime(enriched_panel["date"], errors="coerce")
        start = dates.min()
        end = dates.max()
    else:
        start = pd.NaT
        end = pd.NaT

    return pd.DataFrame(
        [
            {
                "Cache signature UTC": datetime.utcnow().strftime("%Y-%m-%d %H:%M:%S"),
                "Ticker context": str(ticker),
                "Panel period": str(panel_period),
                "Panel interval": str(panel_interval),
                "Horizon": panel_horizon,
                "TP ATR": panel_pt,
                "SL ATR": panel_sl,
                "Start": start.strftime("%Y-%m-%d") if not pd.isna(start) else "N/A",
                "End": end.strftime("%Y-%m-%d") if not pd.isna(end) else "N/A",
                "Rows": len(enriched_panel),
                "Tickers": enriched_panel["ticker"].nunique() if (not enriched_panel.empty and "ticker" in enriched_panel.columns) else 0,
                "Labels": int(enriched_panel["tb_label"].notna().sum()) if (not enriched_panel.empty and "tb_label" in enriched_panel.columns) else 0,
                "Shortlist features": len(shortlist),
                "Predictions": len(predictions),
                "Final manifest rows": len(final_manifest),
                "Decision Engine": "Blocked",
                "Probability usage": "Blocked",
            }
        ]
    )


def build_ml_feature_store_manifest_v77(signature_df):
    signature_df = _mlqa_safe_df(signature_df)
    if signature_df.empty:
        return pd.DataFrame(
            [
                {"Item": "Feature store light", "Status": "Unavailable", "Detail": "No signature."},
            ]
        )

    row = signature_df.iloc[0]
    labels = int(_mlqa_safe_float(row.get("Labels"), 0) or 0)
    features = int(_mlqa_safe_float(row.get("Shortlist features"), 0) or 0)
    predictions = int(_mlqa_safe_float(row.get("Predictions"), 0) or 0)

    if labels >= 500 and features >= 5 and predictions >= 100:
        status = "Cacheable"
        detail = "Run has enough labels, features and predictions to be stored as a light research snapshot."
    else:
        status = "Partial"
        detail = "Snapshot can be stored, but it is incomplete for institutional comparison."

    return pd.DataFrame(
        [
            {"Item": "Feature store light", "Status": status, "Detail": detail},
            {"Item": "Stored object scope", "Status": "Research", "Detail": "V5.0/V5.1.1/V5.2/V6.4-V7.2 references only; no production signal."},
            {"Item": "Cache invalidation keys", "Status": "Info", "Detail": "ticker universe, period, interval, horizon, TP/SL, feature version."},
            {"Item": "Decision Engine", "Status": "Blocked", "Detail": "Cached objects cannot be used as Decision Engine input."},
        ]
    )


