            pct_cols = ["Hit rate", "Avg gross return", "Avg net return proxy", "Vol proxy", "Max drawdown proxy", "Exposure proxy", "Turnover proxy", "Avg MFE", "Avg MAE"]
            display_metrics = _mlqa_fmt_pct_cols(metrics, pct_cols)
