# V4.8 — ROBUSTNESS EXPANSION RUNNER, READ-ONLY
# ============================================================

def _scenario_status_from_summary_v48(summary_df: pd.DataFrame) -> tuple[str, str]:
    """
    Extrait le statut global du ranker depuis le résumé V4.2.
    """
    if summary_df is None or summary_df.empty:
        return "Unavailable", "Résumé V4.2 indisponible."

    row = summary_df[summary_df["Contrôle"] == "Cross-sectional ranker status"]

    if row.empty:
        return "Unknown", "Statut ranker introuvable."

    return str(row.iloc[0].get("Statut", "Unknown")), str(row.iloc[0].get("Détail", ""))


def _top_selection_metrics_v48(cumulative_df: pd.DataFrame, selection: str) -> dict:
    """
    Récupère les métriques d'une sélection cumulative.
    """
    if cumulative_df is None or cumulative_df.empty:
        return {
            "count": 0,
            "tp_lift": np.nan,
            "return_lift": np.nan,
            "avg_return": np.nan,
        }

    row = cumulative_df[cumulative_df["Selection"] == selection]

    if row.empty:
        return {
            "count": 0,
            "tp_lift": np.nan,
            "return_lift": np.nan,
            "avg_return": np.nan,
        }

    r = row.iloc[0]

    return {
        "count": int(_safe_float(r.get("Count"), 0) or 0),
        "tp_lift": _safe_float(r.get("TP lift vs all"), np.nan),
        "return_lift": _safe_float(r.get("Return lift vs all"), np.nan),
        "avg_return": _safe_float(r.get("Avg return"), np.nan),
    }


def run_robustness_expansion_v48(
    core_tickers: list[str],
    expanded_tickers: list[str],
    periods: list[str],
    universes: list[str],
    interval: str = "1d",
    horizon: int = 20,
    pt_mult: float = 1.5,
    sl_mult: float = 1.5,
    n_splits: int = 5,
    embargo_days: int = 5,
    min_train_size: int = 300,
    model_name: str = "Logistic strong regularization",
) -> dict:
    """
    V4.8 — Relance des scénarios historiques / univers.

    Read-only :
    - construit des panels alternatifs ;
    - relance le ranker V4.2 ;
    - applique le gate strict V4.3.1 ;
    - compare la persistance ticker/scénario.

    Aucun signal, aucune probabilité exploitable, aucune intégration Decision Engine.
    """
    scenario_rows = []
    strict_gate_parts = []

    universe_map = {
        "Core": core_tickers,
        "Semi expanded": expanded_tickers,
    }

    selected_universes = [u for u in universes if u in universe_map]
    selected_periods = [str(p) for p in periods if str(p)]

    if not selected_universes or not selected_periods:
        return {
            "manifest": pd.DataFrame(),
            "scenario_comparison": pd.DataFrame(),
            "ticker_persistence": pd.DataFrame(),
            "strict_gate_by_scenario": pd.DataFrame(),
        }

    for universe_name in selected_universes:
        scenario_tickers = _normalize_ticker_list_v40(",".join(universe_map.get(universe_name, [])))

        if not scenario_tickers:
            continue

        for period in selected_periods:
            scenario_name = f"{universe_name} · {period}"

            try:
                panel_s, audit_s = build_multi_ticker_panel_v40(
                    tickers=scenario_tickers,
                    period=period,
                    interval=interval,
                    horizon=int(horizon),
                    pt_mult=float(pt_mult),
                    sl_mult=float(sl_mult),
                )

                if panel_s is None or panel_s.empty:
                    scenario_rows.append(
                        {
                            "Scenario": scenario_name,
                            "Universe": universe_name,
                            "Period": period,
                            "Tickers requested": len(scenario_tickers),
                            "Tickers OK": 0,
                            "Panel rows": 0,
                            "Labels": 0,
                            "Folds OK": 0,
                            "Global ranker status": "Unavailable",
                            "Top20 count": 0,
                            "Top20 TP lift": np.nan,
                            "Top20 return lift": np.nan,
                            "Top20 avg return": np.nan,
                            "Strict supportive count": 0,
                            "Strict supportive tickers": "",
                            "Watchlist count": 0,
                            "Spread failure count": 0,
                            "Damaging count": 0,
                            "Scenario verdict": "Panel unavailable",
                            "Detail": "Panel vide ou données indisponibles.",
                        }
                    )
                    continue

                labels_s = panel_s.dropna(subset=["tb_label"]).copy()
                label_count = len(labels_s)
                tickers_ok = int((audit_s["Status"] == "OK").sum()) if audit_s is not None and not audit_s.empty else 0

                folds_s, preds_s, buckets_s = run_cross_sectional_baseline_ranker_v42(
                    panel=panel_s,
                    n_splits=int(n_splits),
                    embargo_days=int(embargo_days),
                    min_train_size=int(min_train_size),
                    min_test_size=50,
                    model_name=model_name,
                )

                summary_s = build_cross_sectional_ranker_summary_v42(
                    fold_results=folds_s,
                    bucket_summary=buckets_s,
                )

                cumulative_s = build_cross_sectional_cumulative_rank_summary_v421(preds_s)
                ticker_breakdown_s = build_cross_sectional_ranker_ticker_breakdown_v42(preds_s)
                strict_gate_s = build_cross_sectional_strict_ticker_gate_v431(ticker_breakdown_s)

                ranker_status, ranker_detail = _scenario_status_from_summary_v48(summary_s)
                top20_metrics = _top_selection_metrics_v48(cumulative_s, "Top 20% cumulative")

                folds_ok = int((folds_s["Status"] == "OK").sum()) if folds_s is not None and not folds_s.empty else 0

                strict_supportive_tickers = []
                watchlist_count = 0
                spread_failure_count = 0
                damaging_count = 0

                if strict_gate_s is not None and not strict_gate_s.empty:
                    strict_gate_s = strict_gate_s.copy()
                    strict_gate_s.insert(0, "Scenario", scenario_name)
                    strict_gate_s.insert(1, "Universe", universe_name)
                    strict_gate_s.insert(2, "Period", period)
                    strict_gate_parts.append(strict_gate_s)

                    strict_supportive_tickers = strict_gate_s.loc[
                        strict_gate_s["Strict ticker gate"] == "Strict supportive",
                        "Ticker",
                    ].astype(str).tolist()

                    watchlist_count = int((strict_gate_s["Strict ticker gate"] == "Watchlist").sum())
                    spread_failure_count = int((strict_gate_s["Strict ticker gate"] == "Spread failure").sum())
                    damaging_count = int((strict_gate_s["Strict ticker gate"] == "Damaging").sum())

                if len(strict_supportive_tickers) >= 2 and top20_metrics["return_lift"] is not None and top20_metrics["return_lift"] > 0:
                    scenario_verdict = "Constructive"
                    detail = "Plusieurs tickers strictement supportifs et Top20 cumulatif positif."
                elif len(strict_supportive_tickers) >= 1:
                    scenario_verdict = "Ticker-specific"
                    detail = "Au moins un ticker strictement supportif, mais robustesse globale limitée."
                elif ranker_status in ["Research positive", "Ranking lift only"]:
                    scenario_verdict = "Global watchlist"
                    detail = "Le ranker montre un lift mais sans ticker strict assez robuste."
                else:
                    scenario_verdict = "Weak"
                    detail = ranker_detail or "Scénario faible."

                scenario_rows.append(
                    {
                        "Scenario": scenario_name,
                        "Universe": universe_name,
                        "Period": period,
                        "Tickers requested": len(scenario_tickers),
                        "Tickers OK": tickers_ok,
                        "Panel rows": len(panel_s),
                        "Labels": label_count,
                        "Folds OK": folds_ok,
                        "Global ranker status": ranker_status,
                        "Top20 count": top20_metrics["count"],
                        "Top20 TP lift": top20_metrics["tp_lift"],
                        "Top20 return lift": top20_metrics["return_lift"],
                        "Top20 avg return": top20_metrics["avg_return"],
                        "Strict supportive count": len(strict_supportive_tickers),
                        "Strict supportive tickers": ", ".join(strict_supportive_tickers),
                        "Watchlist count": watchlist_count,
                        "Spread failure count": spread_failure_count,
                        "Damaging count": damaging_count,
                        "Scenario verdict": scenario_verdict,
                        "Detail": detail,
                    }
                )

            except Exception as e:
                scenario_rows.append(
                    {
                        "Scenario": scenario_name,
                        "Universe": universe_name,
                        "Period": period,
                        "Tickers requested": len(scenario_tickers),
                        "Tickers OK": 0,
                        "Panel rows": 0,
                        "Labels": 0,
                        "Folds OK": 0,
                        "Global ranker status": "Error",
                        "Top20 count": 0,
                        "Top20 TP lift": np.nan,
                        "Top20 return lift": np.nan,
                        "Top20 avg return": np.nan,
                        "Strict supportive count": 0,
                        "Strict supportive tickers": "",
                        "Watchlist count": 0,
                        "Spread failure count": 0,
                        "Damaging count": 0,
                        "Scenario verdict": "Error",
                        "Detail": str(e)[:140],
                    }
                )

    scenario_comparison = pd.DataFrame(scenario_rows)

    if strict_gate_parts:
        strict_gate_by_scenario = pd.concat(strict_gate_parts, ignore_index=True)
    else:
        strict_gate_by_scenario = pd.DataFrame()

    ticker_persistence = build_robustness_ticker_persistence_v48(strict_gate_by_scenario)
    manifest = build_robustness_manifest_v48(scenario_comparison, ticker_persistence)

    return {
        "manifest": manifest,
        "scenario_comparison": scenario_comparison,
        "ticker_persistence": ticker_persistence,
        "strict_gate_by_scenario": strict_gate_by_scenario,
    }


def build_robustness_ticker_persistence_v48(strict_gate_by_scenario: pd.DataFrame) -> pd.DataFrame:
    """
    Mesure la persistance des tickers dans les scénarios V4.8.
    """
    if strict_gate_by_scenario is None or strict_gate_by_scenario.empty:
        return pd.DataFrame()

    required = [
        "Ticker",
        "Scenario",
        "Strict ticker gate",
        "Strict gate score",
        "Top20 return lift",
        "Top20 minus Bottom20",
    ]

    if any(col not in strict_gate_by_scenario.columns for col in required):
        return pd.DataFrame()

    rows = []

    for ticker, group in strict_gate_by_scenario.groupby("Ticker"):
        scenarios_tested = int(group["Scenario"].nunique())
        strict_supportive = int((group["Strict ticker gate"] == "Strict supportive").sum())
        watchlist = int((group["Strict ticker gate"] == "Watchlist").sum())
        spread_failures = int((group["Strict ticker gate"] == "Spread failure").sum())
        damaging = int((group["Strict ticker gate"] == "Damaging").sum())
        small_sample = int((group["Strict ticker gate"] == "Small sample").sum())

        avg_score = pd.to_numeric(group["Strict gate score"], errors="coerce").mean()
        avg_return_lift = pd.to_numeric(group["Top20 return lift"], errors="coerce").mean()
        avg_spread = pd.to_numeric(group["Top20 minus Bottom20"], errors="coerce").mean()

        supportive_rate = strict_supportive / scenarios_tested if scenarios_tested else 0

        if strict_supportive >= 2 and damaging == 0 and avg_return_lift > 0 and avg_spread > 0:
            status = "Persistent strict supportive"
            detail = "Ticker supportif sur plusieurs scénarios, sans scénario damaging."
        elif strict_supportive >= 1 and damaging == 0:
            status = "Scenario-specific supportive"
            detail = "Supportif dans certains scénarios seulement."
        elif damaging > 0 or spread_failures >= max(1, scenarios_tested // 2):
            status = "Unstable / avoid"
            detail = "Trop de spread failures ou scénario damaging."
        elif watchlist > 0:
            status = "Watchlist"
            detail = "Signal partiel, non persistant."
        else:
            status = "Neutral"
            detail = "Pas de persistance exploitable."

        rows.append(
            {
                "Ticker": str(ticker),
                "Scenarios tested": scenarios_tested,
                "Strict supportive scenarios": strict_supportive,
                "Supportive rate": supportive_rate,
                "Watchlist scenarios": watchlist,
                "Spread failures": spread_failures,
                "Damaging scenarios": damaging,
                "Small sample scenarios": small_sample,
                "Avg strict score": avg_score,
                "Avg Top20 return lift": avg_return_lift,
                "Avg Top20 minus Bottom20": avg_spread,
                "Persistence status": status,
                "Detail": detail,
            }
        )

    out = pd.DataFrame(rows)

    if out.empty:
        return out

    order = {
        "Persistent strict supportive": 0,
        "Scenario-specific supportive": 1,
        "Watchlist": 2,
        "Neutral": 3,
        "Unstable / avoid": 4,
    }

    out["_order"] = out["Persistence status"].map(order).fillna(99)

    return out.sort_values(
        ["_order", "Strict supportive scenarios", "Avg Top20 return lift", "Avg strict score"],
        ascending=[True, False, False, False],
    ).drop(columns=["_order"])


def build_robustness_manifest_v48(
    scenario_comparison: pd.DataFrame,
    ticker_persistence: pd.DataFrame,
) -> pd.DataFrame:
    """
    Manifest V4.8 : décision read-only après scénarios.
    """
    if scenario_comparison is None or scenario_comparison.empty:
        return pd.DataFrame(
            [
                {
                    "Decision item": "Robustness expansion",
                    "Status": "Unavailable",
                    "Detail": "Aucun scénario V4.8 exploitable.",
                }
            ]
        )

    total_scenarios = len(scenario_comparison)
    constructive = int((scenario_comparison["Scenario verdict"] == "Constructive").sum())
    ticker_specific = int((scenario_comparison["Scenario verdict"] == "Ticker-specific").sum())
    weak = int((scenario_comparison["Scenario verdict"] == "Weak").sum())
    errors = int((scenario_comparison["Scenario verdict"] == "Error").sum())

    persistent = 0
    scenario_specific = 0
    persistent_tickers = []

    if ticker_persistence is not None and not ticker_persistence.empty:
        persistent_rows = ticker_persistence[
            ticker_persistence["Persistence status"] == "Persistent strict supportive"
        ]
        scenario_specific_rows = ticker_persistence[
            ticker_persistence["Persistence status"] == "Scenario-specific supportive"
        ]

        persistent = len(persistent_rows)
        scenario_specific = len(scenario_specific_rows)
        persistent_tickers = persistent_rows["Ticker"].astype(str).tolist()

    if persistent > 0 and constructive + ticker_specific >= max(1, total_scenarios // 2):
        status = "Research constructive"
        detail = f"Ticker(s) persistant(s) détecté(s) : {', '.join(persistent_tickers)}."
    elif persistent > 0 or scenario_specific > 0:
        status = "Research watchlist"
        detail = "Au moins un ticker est supportif, mais la persistance scénario reste insuffisante."
    else:
        status = "Rejected / enrich features"
        detail = "Aucun ticker ne persiste suffisamment. Priorité à l'enrichissement features/régime."

    rows = [
        {
            "Decision item": "Robustness expansion status",
            "Status": status,
            "Detail": detail,
        },
        {
            "Decision item": "Scenarios tested",
            "Status": "OK" if total_scenarios >= 2 else "À surveiller",
            "Detail": f"{total_scenarios} scénario(s).",
        },
        {
            "Decision item": "Constructive scenarios",
            "Status": "Info",
            "Detail": f"{constructive}/{total_scenarios} scénario(s).",
        },
        {
            "Decision item": "Ticker-specific scenarios",
            "Status": "Info",
            "Detail": f"{ticker_specific}/{total_scenarios} scénario(s).",
        },
        {
            "Decision item": "Weak scenarios",
            "Status": "À surveiller" if weak > 0 else "OK",
            "Detail": f"{weak}/{total_scenarios} scénario(s).",
        },
        {
            "Decision item": "Error scenarios",
            "Status": "À surveiller" if errors > 0 else "OK",
            "Detail": f"{errors}/{total_scenarios} scénario(s).",
        },
        {
            "Decision item": "Persistent strict tickers",
            "Status": "Research" if persistent > 0 else "None",
            "Detail": ", ".join(persistent_tickers) if persistent_tickers else "Aucun.",
        },
        {
            "Decision item": "Decision Engine",
            "Status": "Blocked",
            "Detail": "Aucune intégration. V4.8 reste read-only.",
        },
    ]

    return pd.DataFrame(rows)


# ============================================================
# V4.9 — ROBUSTNESS DECISION GATE + FEATURE ENRICHMENT ROADMAP
# ============================================================

def build_robustness_decision_gate_v49(
    robustness_manifest_v48: pd.DataFrame,
    scenario_comparison_v48: pd.DataFrame,
    ticker_persistence_v48: pd.DataFrame,
    promotion_gate_v47: pd.DataFrame,
) -> pd.DataFrame:
    """
    V4.9 — Gate de décision après V4.8.

    Objectif : transformer V4.8 en décision de recherche claire.
    Ce gate ne promeut jamais le modèle et ne branche jamais le Decision Engine.
    """
    rows = []

    promo_status = "Unknown"
    promo_detail = "Promotion gate V4.7 indisponible."

    if promotion_gate_v47 is not None and not promotion_gate_v47.empty:
        promo_row = promotion_gate_v47[
            promotion_gate_v47["Gate item"] == "Promotion eligibility"
        ]

        if not promo_row.empty:
            promo_status = str(promo_row.iloc[0].get("Status", "Unknown"))
            promo_detail = str(promo_row.iloc[0].get("Detail", ""))

    robust_status = "Unavailable"
    robust_detail = "Manifest V4.8 indisponible."

    if robustness_manifest_v48 is not None and not robustness_manifest_v48.empty:
        robust_row = robustness_manifest_v48[
            robustness_manifest_v48["Decision item"] == "Robustness expansion status"
        ]

        if not robust_row.empty:
            robust_status = str(robust_row.iloc[0].get("Status", "Unavailable"))
            robust_detail = str(robust_row.iloc[0].get("Detail", ""))

    total_scenarios = len(scenario_comparison_v48) if scenario_comparison_v48 is not None else 0
    constructive_scenarios = 0
    weak_scenarios = 0

    if scenario_comparison_v48 is not None and not scenario_comparison_v48.empty:
        constructive_scenarios = int(
            scenario_comparison_v48["Scenario verdict"].isin(["Constructive", "Ticker-specific"]).sum()
        )
        weak_scenarios = int((scenario_comparison_v48["Scenario verdict"] == "Weak").sum())

    persistent_tickers = []
    scenario_specific_tickers = []
    unstable_tickers = []

    if ticker_persistence_v48 is not None and not ticker_persistence_v48.empty:
        persistent_tickers = ticker_persistence_v48.loc[
            ticker_persistence_v48["Persistence status"] == "Persistent strict supportive",
            "Ticker",
        ].astype(str).tolist()

        scenario_specific_tickers = ticker_persistence_v48.loc[
            ticker_persistence_v48["Persistence status"] == "Scenario-specific supportive",
            "Ticker",
        ].astype(str).tolist()

        unstable_tickers = ticker_persistence_v48.loc[
            ticker_persistence_v48["Persistence status"] == "Unstable / avoid",
            "Ticker",
        ].astype(str).tolist()

    if promo_status == "Blocked":
        final_status = "Blocked"
        final_detail = "Promotion ML déjà bloquée par V4.7. V4.9 ne peut pas débloquer le modèle."
    elif robust_status in ["Rejected / enrich features", "Unavailable"]:
        final_status = "Blocked"
        final_detail = "Robustesse insuffisante. Revenir aux features/régimes."
    elif len(persistent_tickers) == 0:
        final_status = "Research watchlist only"
        final_detail = "Pas de ticker persistant. Analyse uniquement watchlist."
    else:
        final_status = "Research constructive but blocked"
        final_detail = "Ticker persistant détecté, mais pas de promotion avant nouveau modèle enrichi et calibration."

    rows.extend(
        [
            {
                "Gate item": "V4.7 promotion state",
                "Status": promo_status,
                "Detail": promo_detail,
            },
            {
                "Gate item": "V4.8 robustness state",
                "Status": robust_status,
                "Detail": robust_detail,
            },
            {
                "Gate item": "Scenario coverage",
                "Status": "OK" if total_scenarios >= 2 else "Weak",
                "Detail": f"{total_scenarios} scénario(s), {constructive_scenarios} constructif(s), {weak_scenarios} faible(s).",
            },
            {
                "Gate item": "Persistent tickers",
                "Status": "Research" if persistent_tickers else "None",
                "Detail": ", ".join(persistent_tickers) if persistent_tickers else "Aucun ticker persistant.",
            },
            {
                "Gate item": "Scenario-specific tickers",
                "Status": "Watchlist" if scenario_specific_tickers else "None",
                "Detail": ", ".join(scenario_specific_tickers) if scenario_specific_tickers else "Aucun.",
            },
            {
                "Gate item": "Unstable tickers",
                "Status": "À surveiller" if unstable_tickers else "OK",
                "Detail": ", ".join(unstable_tickers) if unstable_tickers else "Aucun ticker instable majeur.",
            },
            {
                "Gate item": "Probability usage",
                "Status": "Blocked",
                "Detail": "Aucune probabilité brute n'est utilisable. Le ranking reste shadow/research-only.",
            },
            {
                "Gate item": "Decision Engine",
                "Status": "Blocked",
                "Detail": "Aucune intégration autorisée.",
            },
            {
                "Gate item": "Final V4.9 decision",
                "Status": final_status,
                "Detail": final_detail,
            },
        ]
    )

    return pd.DataFrame(rows)


