# ============================================================
# V5.0 — FEATURE ENRICHMENT LAYER, READ-ONLY
# ============================================================

def _v50_rank_pct_by_date(work: pd.DataFrame, col: str, ascending: bool = True) -> pd.Series:
    """
    Cross-sectional percentile rank by date.
    Returns NaN if the source column is unavailable.
    """
    if work is None or work.empty or col not in work.columns or "date" not in work.columns:
        return pd.Series(np.nan, index=work.index if work is not None else None)

    values = pd.to_numeric(work[col], errors="coerce")

    return values.groupby(work["date"]).rank(method="average", pct=True, ascending=ascending)


def _v50_minus_universe_median(work: pd.DataFrame, col: str) -> pd.Series:
    """
    Écart d'une feature au median cross-sectionnel du jour.
    """
    if work is None or work.empty or col not in work.columns or "date" not in work.columns:
        return pd.Series(np.nan, index=work.index if work is not None else None)

    values = pd.to_numeric(work[col], errors="coerce")
    med = values.groupby(work["date"]).transform("median")

    return values - med


def _v50_ticker_zscore(work: pd.DataFrame, col: str, window: int = 60) -> pd.Series:
    """
    Z-score rolling par ticker, décalé pour éviter d'utiliser la ligne courante comme référence complète.
    """
    if work is None or work.empty or col not in work.columns or "ticker" not in work.columns:
        return pd.Series(np.nan, index=work.index if work is not None else None)

    pieces = []

    for _, group in work.groupby("ticker", sort=False):
        values = pd.to_numeric(group[col], errors="coerce")
        rolling_mean = values.rolling(window, min_periods=max(10, int(window / 4))).mean().shift(1)
        rolling_std = values.rolling(window, min_periods=max(10, int(window / 4))).std().shift(1)
        z = (values - rolling_mean) / rolling_std.replace(0, np.nan)
        pieces.append(z)

    if not pieces:
        return pd.Series(np.nan, index=work.index)

    return pd.concat(pieces).sort_index()


def build_feature_enriched_panel_v50(
    panel: pd.DataFrame,
    ticker_persistence_v48: pd.DataFrame | None = None,
) -> pd.DataFrame:
    """
    V5.0 — Enrichit le panel sans entraîner de modèle.

    Ajouts :
    - relative strength cross-sectional ;
    - liquidité / volume ;
    - path risk / gap risk ;
    - interactions régime x momentum ;
    - flags de recherche issus de V4.8, mais bloqués pour futur X.

    Aucune probabilité.
    Aucun signal.
    Aucune intégration Decision Engine.
    """
    if panel is None or panel.empty:
        return pd.DataFrame()

    work = panel.copy()

    if "date" not in work.columns or "ticker" not in work.columns:
        return pd.DataFrame()

    work["date"] = pd.to_datetime(work["date"], errors="coerce")
    work["ticker"] = work["ticker"].astype(str).str.upper()
    work = work.dropna(subset=["date", "ticker"]).sort_values(["ticker", "date"]).reset_index(drop=True)

    numeric_candidates = [
        "open",
        "high",
        "low",
        "close",
        "volume",
        "return_1d",
        "return_5d",
        "return_20d",
        "return_60d",
        "vol_20d",
        "vol_60d",
        "atr_pct",
        "rsi_14",
        "drawdown",
        "price_vs_ema20",
        "price_vs_ema50",
        "price_vs_sma200",
        "breakout_20d",
        "breakdown_20d",
        "volume_zscore",
        "dollar_volume",
        "tb_return",
        "tb_mfe",
        "tb_mae",
    ]

    for col in numeric_candidates:
        if col in work.columns:
            work[col] = pd.to_numeric(work[col], errors="coerce")

    # ------------------------------
    # Relative strength cross-sectional
    # ------------------------------
    rank_specs = [
        ("return_5d", "rs_return_5d_xs_rank", True),
        ("return_20d", "rs_return_20d_xs_rank", True),
        ("return_60d", "rs_return_60d_xs_rank", True),
        ("price_vs_ema20", "rs_price_vs_ema20_xs_rank", True),
        ("price_vs_ema50", "rs_price_vs_ema50_xs_rank", True),
        ("price_vs_sma200", "rs_price_vs_sma200_xs_rank", True),
        ("rsi_14", "rs_rsi_14_xs_rank", True),
        ("drawdown", "rs_drawdown_xs_rank", True),
        ("breakout_20d", "rs_breakout_20d_xs_rank", True),
        ("breakdown_20d", "rs_breakdown_20d_xs_rank", True),
    ]

    for source_col, out_col, ascending in rank_specs:
        if source_col in work.columns:
            work[out_col] = _v50_rank_pct_by_date(work, source_col, ascending=ascending)
            work[f"{out_col}_spread"] = _v50_minus_universe_median(work, source_col)

    rs_rank_cols = [
        col
        for col in [
            "rs_return_20d_xs_rank",
            "rs_return_60d_xs_rank",
            "rs_price_vs_ema50_xs_rank",
            "rs_rsi_14_xs_rank",
        ]
        if col in work.columns
    ]

    if rs_rank_cols:
        work["rs_composite_momentum_rank_v50"] = work[rs_rank_cols].mean(axis=1)

    # ------------------------------
    # Liquidity / volume regime
    # ------------------------------
    if "dollar_volume" not in work.columns and "volume" in work.columns and "close" in work.columns:
        work["dollar_volume"] = work["volume"] * work["close"]

    if "dollar_volume" in work.columns:
        work["liq_log_dollar_volume_v50"] = np.log1p(work["dollar_volume"].clip(lower=0))
        work["liq_dollar_volume_xs_rank_v50"] = _v50_rank_pct_by_date(work, "dollar_volume", ascending=True)
        work["liq_dollar_volume_ticker_z_v50"] = _v50_ticker_zscore(work, "dollar_volume", window=60)

    if "volume_zscore" in work.columns:
        work["liq_volume_zscore_xs_rank_v50"] = _v50_rank_pct_by_date(work, "volume_zscore", ascending=True)

    if "volume" in work.columns:
        work["liq_volume_ticker_z_v50"] = _v50_ticker_zscore(work, "volume", window=60)

    # ------------------------------
    # Path risk / gap risk, using only OHLC observed at date t
    # ------------------------------
    if {"open", "close", "high", "low"}.issubset(work.columns):
        prev_close = work.groupby("ticker")["close"].shift(1)
        work["risk_overnight_gap_v50"] = work["open"] / prev_close.replace(0, np.nan) - 1
        work["risk_intraday_range_pct_v50"] = (work["high"] - work["low"]) / work["close"].replace(0, np.nan)
        work["risk_open_to_close_v50"] = work["close"] / work["open"].replace(0, np.nan) - 1
        work["risk_close_location_v50"] = (
            (work["close"] - work["low"]) / (work["high"] - work["low"]).replace(0, np.nan)
        )
        work["risk_downside_gap_flag_v50"] = (work["risk_overnight_gap_v50"] <= -0.03).astype(int)
        work["risk_upside_gap_flag_v50"] = (work["risk_overnight_gap_v50"] >= 0.03).astype(int)

        downside_parts = []
        upside_parts = []
        range_z_parts = []

        for _, group in work.groupby("ticker", sort=False):
            downside = group["risk_downside_gap_flag_v50"].rolling(20, min_periods=5).sum().shift(1)
            upside = group["risk_upside_gap_flag_v50"].rolling(20, min_periods=5).sum().shift(1)
            range_z = _v50_ticker_zscore(group, "risk_intraday_range_pct_v50", window=60)
            downside_parts.append(downside)
            upside_parts.append(upside)
            range_z_parts.append(range_z)

        if downside_parts:
            work["risk_downside_gap_20d_count_v50"] = pd.concat(downside_parts).sort_index()
        if upside_parts:
            work["risk_upside_gap_20d_count_v50"] = pd.concat(upside_parts).sort_index()
        if range_z_parts:
            work["risk_intraday_range_ticker_z_v50"] = pd.concat(range_z_parts).sort_index()

        work["risk_intraday_range_xs_rank_v50"] = _v50_rank_pct_by_date(
            work,
            "risk_intraday_range_pct_v50",
            ascending=True,
        )

    # ------------------------------
    # Regime interactions
    # ------------------------------
    if "return_20d" in work.columns and "vol_20d" in work.columns:
        work["int_momentum_vol20_v50"] = work["return_20d"] * work["vol_20d"]

    if "return_20d" in work.columns and "atr_pct" in work.columns:
        work["int_momentum_atr_v50"] = work["return_20d"] * work["atr_pct"]

    if "drawdown" in work.columns and "atr_pct" in work.columns:
        work["int_drawdown_atr_v50"] = work["drawdown"] * work["atr_pct"]

    if "rsi_14" in work.columns and "price_vs_ema50" in work.columns:
        work["int_rsi_trend_v50"] = ((work["rsi_14"] - 50.0) / 50.0) * work["price_vs_ema50"]

    if "rs_composite_momentum_rank_v50" in work.columns and "liq_dollar_volume_xs_rank_v50" in work.columns:
        work["int_rs_liquidity_v50"] = work["rs_composite_momentum_rank_v50"] * work["liq_dollar_volume_xs_rank_v50"]

    if "rs_composite_momentum_rank_v50" in work.columns and "risk_intraday_range_xs_rank_v50" in work.columns:
        work["int_rs_range_risk_v50"] = work["rs_composite_momentum_rank_v50"] * work["risk_intraday_range_xs_rank_v50"]

    # ------------------------------
    # Flags V4.8 research-only, never eligible as model X
    # ------------------------------
    work["research_v48_persistent_ticker_flag"] = 0
    work["research_v48_scenario_specific_flag"] = 0
    work["research_v48_unstable_flag"] = 0

    if ticker_persistence_v48 is not None and not ticker_persistence_v48.empty:
        if "Ticker" in ticker_persistence_v48.columns and "Persistence status" in ticker_persistence_v48.columns:
            persistence = ticker_persistence_v48.copy()
            persistence["Ticker"] = persistence["Ticker"].astype(str).str.upper()

            persistent = persistence.loc[
                persistence["Persistence status"] == "Persistent strict supportive",
                "Ticker",
            ].tolist()

            scenario_specific = persistence.loc[
                persistence["Persistence status"] == "Scenario-specific supportive",
                "Ticker",
            ].tolist()

            unstable = persistence.loc[
                persistence["Persistence status"] == "Unstable / avoid",
                "Ticker",
            ].tolist()

            work["research_v48_persistent_ticker_flag"] = work["ticker"].isin(persistent).astype(int)
            work["research_v48_scenario_specific_flag"] = work["ticker"].isin(scenario_specific).astype(int)
            work["research_v48_unstable_flag"] = work["ticker"].isin(unstable).astype(int)

    return work


def get_v50_candidate_feature_columns(panel_v50: pd.DataFrame) -> list[str]:
    """
    Colonnes V5.0 candidates pour une future expérience, hors flags research et hors labels.
    """
    if panel_v50 is None or panel_v50.empty:
        return []

    prefixes = [
        "rs_",
        "liq_",
        "risk_",
        "int_",
    ]

    blocked_prefixes = [
        "research_",
        "tb_",
        "forward_return_",
        "target_",
        "label_",
    ]

    candidates = []

    for col in panel_v50.columns:
        name = str(col)

        if any(name.startswith(prefix) for prefix in blocked_prefixes):
            continue

        if not any(name.startswith(prefix) for prefix in prefixes):
            continue

        if pd.api.types.is_numeric_dtype(panel_v50[col]):
            candidates.append(name)

    return candidates


def build_v50_feature_inventory(panel_v50: pd.DataFrame) -> pd.DataFrame:
    """
    Inventaire des features V5.0.
    """
    if panel_v50 is None or panel_v50.empty:
        return pd.DataFrame()

    rows = []
    candidate_cols = set(get_v50_candidate_feature_columns(panel_v50))

    def group_name(col: str) -> str:
        if col.startswith("rs_"):
            return "Relative strength"
        if col.startswith("liq_"):
            return "Liquidity / volume"
        if col.startswith("risk_"):
            return "Path risk / gap risk"
        if col.startswith("int_"):
            return "Regime interaction"
        if col.startswith("research_"):
            return "Research flags — blocked from X"
        return "Other"

    for col in panel_v50.columns:
        name = str(col)

        if not (
            name.startswith("rs_")
            or name.startswith("liq_")
            or name.startswith("risk_")
            or name.startswith("int_")
            or name.startswith("research_")
        ):
            continue

        series = panel_v50[col]
        missing = float(series.isna().mean()) if len(series) else np.nan
        unique_values = int(series.nunique(dropna=True)) if len(series) else 0
        numeric = pd.api.types.is_numeric_dtype(series)

        eligible = name in candidate_cols and missing <= 0.35 and unique_values >= 5

        if name.startswith("research_"):
            status = "Blocked"
            detail = "Flag issu des diagnostics V4.8 : utilisable pour audit, pas comme feature modèle."
        elif eligible:
            status = "Candidate"
            detail = "Feature candidate V5.0 pour future expérience OOS."
        elif not numeric:
            status = "Blocked"
            detail = "Non numérique."
        elif missing > 0.35:
            status = "Watch"
            detail = "Taux de valeurs manquantes élevé."
        elif unique_values < 5:
            status = "Blocked"
            detail = "Trop peu de valeurs distinctes."
        else:
            status = "Watch"
            detail = "À contrôler avant modèle enrichi."

        rows.append(
            {
                "Feature": name,
                "Block": group_name(name),
                "Status": status,
                "Missing %": missing,
                "Unique values": unique_values,
                "Dtype": str(series.dtype),
                "Detail": detail,
            }
        )

    out = pd.DataFrame(rows)

    if out.empty:
        return out

    return out.sort_values(["Block", "Status", "Missing %", "Feature"])


def build_v50_feature_block_summary(inventory_v50: pd.DataFrame) -> pd.DataFrame:
    """
    Résumé par bloc de features.
    """
    if inventory_v50 is None or inventory_v50.empty:
        return pd.DataFrame()

    rows = []

    for block, group in inventory_v50.groupby("Block"):
        total = len(group)
        candidates = int((group["Status"] == "Candidate").sum())
        watch = int((group["Status"] == "Watch").sum())
        blocked = int((group["Status"] == "Blocked").sum())
        avg_missing = group["Missing %"].mean()

        if block == "Research flags — blocked from X":
            status = "Blocked from model"
            detail = "Colonnes conservées pour audit uniquement."
        elif candidates >= 3 and avg_missing <= 0.20:
            status = "OK"
            detail = "Bloc exploitable pour future expérience enrichie."
        elif candidates > 0:
            status = "À surveiller"
            detail = "Bloc partiellement exploitable, couverture à contrôler."
        else:
            status = "Weak"
            detail = "Bloc insuffisant actuellement."

        rows.append(
            {
                "Feature block": block,
                "Status": status,
                "Features": total,
                "Candidates": candidates,
                "Watch": watch,
                "Blocked": blocked,
                "Avg missing %": avg_missing,
                "Detail": detail,
            }
        )

    return pd.DataFrame(rows)


def build_v50_ticker_enrichment_snapshot(panel_v50: pd.DataFrame) -> pd.DataFrame:
    """
    Snapshot par ticker après enrichissement.
    """
    if panel_v50 is None or panel_v50.empty or "ticker" not in panel_v50.columns:
        return pd.DataFrame()

    rows = []

    for ticker, group in panel_v50.groupby("ticker"):
        labeled = group.dropna(subset=["tb_label"]) if "tb_label" in group.columns else group.copy()

        rows.append(
            {
                "Ticker": ticker,
                "Rows": len(group),
                "Labels": len(labeled),
                "Avg RS composite": group["rs_composite_momentum_rank_v50"].mean()
                if "rs_composite_momentum_rank_v50" in group.columns
                else np.nan,
                "Avg liquidity rank": group["liq_dollar_volume_xs_rank_v50"].mean()
                if "liq_dollar_volume_xs_rank_v50" in group.columns
                else np.nan,
                "Avg range risk rank": group["risk_intraday_range_xs_rank_v50"].mean()
                if "risk_intraday_range_xs_rank_v50" in group.columns
                else np.nan,
                "Downside gap 20d avg": group["risk_downside_gap_20d_count_v50"].mean()
                if "risk_downside_gap_20d_count_v50" in group.columns
                else np.nan,
                "V4.8 persistent flag": int(group["research_v48_persistent_ticker_flag"].max())
                if "research_v48_persistent_ticker_flag" in group.columns
                else 0,
                "V4.8 scenario-specific flag": int(group["research_v48_scenario_specific_flag"].max())
                if "research_v48_scenario_specific_flag" in group.columns
                else 0,
                "V4.8 unstable flag": int(group["research_v48_unstable_flag"].max())
                if "research_v48_unstable_flag" in group.columns
                else 0,
            }
        )

    return pd.DataFrame(rows).sort_values(
        ["V4.8 persistent flag", "Avg RS composite", "Avg liquidity rank"],
        ascending=[False, False, False],
    )


def build_v50_leakage_guard(inventory_v50: pd.DataFrame) -> pd.DataFrame:
    """
    Garde-fous anti-leakage V5.0.
    """
    if inventory_v50 is None:
        inventory_v50 = pd.DataFrame()

    feature_names = inventory_v50["Feature"].astype(str).tolist() if not inventory_v50.empty else []

    forbidden_hits = [
        name
        for name in feature_names
        if name.startswith("tb_")
        or name.startswith("forward_return_")
        or name.startswith("target_")
        or name.startswith("label_")
    ]

    research_flags = [name for name in feature_names if name.startswith("research_")]

    rows = [
        {
            "Guardrail": "Model training",
            "Status": "Blocked",
            "Rule": "V5.0 n'entraîne aucun modèle. Il enrichit seulement le panel.",
        },
        {
            "Guardrail": "Probability usage",
            "Status": "Blocked",
            "Rule": "Aucune probabilité brute n'est créée ou validée par V5.0.",
        },
        {
            "Guardrail": "Decision Engine",
            "Status": "Blocked",
            "Rule": "Aucune connexion au Decision Engine.",
        },
        {
            "Guardrail": "Forward / label leakage",
            "Status": "OK" if not forbidden_hits else "KO",
            "Rule": "Aucune feature candidate ne doit venir de tb_*, forward_return_*, target_* ou label_*.",
        },
        {
            "Guardrail": "Research flags",
            "Status": "Blocked from X" if research_flags else "OK",
            "Rule": f"{len(research_flags)} flag(s) V4.8 conservés pour audit uniquement, interdits comme features modèle.",
        },
    ]

    if forbidden_hits:
        rows.append(
            {
                "Guardrail": "Forbidden columns detected",
                "Status": "KO",
                "Rule": ", ".join(forbidden_hits[:12]),
            }
        )

    return pd.DataFrame(rows)


def build_v50_manifest(
    enriched_panel_v50: pd.DataFrame,
    inventory_v50: pd.DataFrame,
    ticker_persistence_v48: pd.DataFrame | None = None,
) -> pd.DataFrame:
    """
    Manifest institutionnel V5.0.
    """
    if enriched_panel_v50 is None or enriched_panel_v50.empty:
        return pd.DataFrame(
            [
                {
                    "Decision item": "V5.0 enrichment",
                    "Status": "Unavailable",
                    "Detail": "Panel enrichi indisponible.",
                }
            ]
        )

    candidate_count = 0

    if inventory_v50 is not None and not inventory_v50.empty:
        candidate_count = int((inventory_v50["Status"] == "Candidate").sum())

    persistent_tickers = []

    if ticker_persistence_v48 is not None and not ticker_persistence_v48.empty:
        if "Ticker" in ticker_persistence_v48.columns and "Persistence status" in ticker_persistence_v48.columns:
            persistent_tickers = ticker_persistence_v48.loc[
                ticker_persistence_v48["Persistence status"] == "Persistent strict supportive",
                "Ticker",
            ].astype(str).tolist()

    labels = int(enriched_panel_v50["tb_label"].notna().sum()) if "tb_label" in enriched_panel_v50.columns else 0
    tickers = int(enriched_panel_v50["ticker"].nunique()) if "ticker" in enriched_panel_v50.columns else 0

    rows = [
        {
            "Decision item": "V5.0 feature enrichment",
            "Status": "Read-only OK" if candidate_count >= 10 else "Partial",
            "Detail": f"{candidate_count} feature(s) candidates, {labels:,} labels, {tickers} ticker(s).",
        },
        {
            "Decision item": "Persistent ticker focus",
            "Status": "Research" if persistent_tickers else "None",
            "Detail": ", ".join(persistent_tickers) if persistent_tickers else "Aucun ticker persistant hérité de V4.8.",
        },
        {
            "Decision item": "Model training",
            "Status": "Blocked",
            "Detail": "Aucun modèle entraîné en V5.0.",
        },
        {
            "Decision item": "Probability usage",
            "Status": "Blocked",
            "Detail": "Aucune probabilité exploitable n'est créée.",
        },
        {
            "Decision item": "Decision Engine",
            "Status": "Blocked",
            "Detail": "Aucune intégration autorisée.",
        },
        {
            "Decision item": "Next step",
            "Status": "Research only",
            "Detail": "V5.1 doit auditer corrélations, missingness, stabilité par scénario avant tout ranker enrichi.",
        },
    ]

    return pd.DataFrame(rows)


def run_feature_enrichment_layer_v50(
    panel: pd.DataFrame,
    ticker_persistence_v48: pd.DataFrame | None = None,
) -> dict:
    """
    Runner V5.0 unique pour garder le render propre.
    """
    enriched_panel = build_feature_enriched_panel_v50(
        panel=panel,
        ticker_persistence_v48=ticker_persistence_v48,
    )

    inventory = build_v50_feature_inventory(enriched_panel)
    block_summary = build_v50_feature_block_summary(inventory)
    ticker_snapshot = build_v50_ticker_enrichment_snapshot(enriched_panel)
    leakage_guard = build_v50_leakage_guard(inventory)
    manifest = build_v50_manifest(
        enriched_panel_v50=enriched_panel,
        inventory_v50=inventory,
        ticker_persistence_v48=ticker_persistence_v48,
    )

    return {
        "enriched_panel": enriched_panel,
        "inventory": inventory,
        "block_summary": block_summary,
        "ticker_snapshot": ticker_snapshot,
        "leakage_guard": leakage_guard,
        "manifest": manifest,
    }



# ============================================================
# V5.1 — ENRICHED FEATURE QUALITY AUDIT, READ-ONLY
# ============================================================

def _v51_forbidden_reason(feature_name: str) -> str:
    """
    Raison de blocage d'une colonne pour un futur modèle.
    V5.1 ne supprime rien du panel : il audite seulement.
    """
    name = str(feature_name).lower()

    forbidden_prefixes = (
        "tb_",
        "forward_return_",
        "future_",
        "target_",
        "label_",
    )

    audit_only_prefixes = (
        "v48_",
        "research_",
        "gate_",
        "strict_",
    )

    blocked_exact = {
        "date",
        "ticker",
        "open",
        "high",
        "low",
        "close",
        "adj_close",
        "volume",
        "source_period",
        "source_interval",
        "tb_label",
        "tb_event",
        "tb_event_start",
        "tb_event_end",
    }

    if name in blocked_exact:
        return "Blocked exact/meta/raw column"

    if any(name.startswith(prefix) for prefix in forbidden_prefixes):
        return "Forbidden leakage/label/forward column"

    if any(name.startswith(prefix) for prefix in audit_only_prefixes):
        return "Audit-only research flag, not model feature"

    if "future" in name or "target" in name or "forward" in name:
        return "Forbidden future-looking name"

    return ""


def _v51_candidate_feature_columns(
    enriched_panel: pd.DataFrame,
    inventory: pd.DataFrame | None = None,
) -> list[str]:
    """
    Sélectionne les features candidates V5.1.

    Priorité :
    1) utiliser l'inventory V5.0 si disponible ;
    2) fallback défensif sur colonnes numériques non interdites.
    """
    if enriched_panel is None or enriched_panel.empty:
        return []

    candidate_cols = []

    if inventory is not None and not inventory.empty:
        feature_col = "Feature" if "Feature" in inventory.columns else None
        status_col = "Status" if "Status" in inventory.columns else None

        if feature_col and status_col:
            inv = inventory.copy()
            inv[feature_col] = inv[feature_col].astype(str)
            inv[status_col] = inv[status_col].astype(str)

            candidate_cols = inv.loc[
                inv[status_col].str.lower().str.contains("candidate", na=False),
                feature_col,
            ].tolist()

    if not candidate_cols:
        for col in enriched_panel.columns:
            if _v51_forbidden_reason(col):
                continue

            if pd.api.types.is_numeric_dtype(enriched_panel[col]):
                candidate_cols.append(str(col))

    out = []

    for col in candidate_cols:
        if col not in enriched_panel.columns:
            continue

        if _v51_forbidden_reason(col):
            continue

        if not pd.api.types.is_numeric_dtype(enriched_panel[col]):
            continue

        if col not in out:
            out.append(col)

    return out


def build_v51_leakage_audit(
    enriched_panel: pd.DataFrame,
    candidate_features: list[str],
) -> pd.DataFrame:
    """
    Vérifie qu'aucune feature candidate ne dépend du futur ou du label.
    Le panel peut contenir tb_* pour audit/export, mais ces colonnes doivent rester hors X.
    """
    if enriched_panel is None or enriched_panel.empty:
        return pd.DataFrame(
            [
                {
                    "Audit item": "Panel",
                    "Status": "KO",
                    "Detail": "Panel enrichi vide.",
                }
            ]
        )

    candidate_set = set(str(c) for c in candidate_features)
    rows = []

    forbidden_in_candidates = []

    for col in enriched_panel.columns:
        reason = _v51_forbidden_reason(col)
        is_candidate = str(col) in candidate_set

        if reason and is_candidate:
            forbidden_in_candidates.append(str(col))

        if reason:
            rows.append(
                {
                    "Column": str(col),
                    "Column role": "Candidate" if is_candidate else "Panel audit/export",
                    "Leakage status": "Forbidden in model",
                    "Reason": reason,
                }
            )

    if not rows:
        rows.append(
            {
                "Column": "All checked columns",
                "Column role": "Candidate set",
                "Leakage status": "OK",
                "Reason": "Aucune colonne au nom forward/target/tb détectée dans le set candidat.",
            }
        )

    audit = pd.DataFrame(rows)

    audit.attrs["forbidden_candidate_count"] = len(forbidden_in_candidates)

    return audit


def build_v51_feature_missing_unique_audit(
    enriched_panel: pd.DataFrame,
    candidate_features: list[str],
) -> pd.DataFrame:
    """
    Audit basique : missing, unique values, variance.
    """
    if enriched_panel is None or enriched_panel.empty or not candidate_features:
        return pd.DataFrame()

    rows = []

    for col in candidate_features:
        if col not in enriched_panel.columns:
            continue

        series = pd.to_numeric(enriched_panel[col], errors="coerce")
        missing = float(series.isna().mean()) if len(series) else np.nan
        unique_values = int(series.nunique(dropna=True))
        std = _safe_float(series.std(), np.nan)

        if missing > 0.35:
            status = "High missing"
        elif unique_values < 5:
            status = "Low cardinality"
        elif std is None or pd.isna(std) or std == 0:
            status = "No variation"
        else:
            status = "OK"

        rows.append(
            {
                "Feature": col,
                "Missing %": missing,
                "Unique values": unique_values,
                "Mean": series.mean(),
                "Std": series.std(),
                "Min": series.min(),
                "Max": series.max(),
                "Basic status": status,
            }
        )

    if not rows:
        return pd.DataFrame()

    return pd.DataFrame(rows).sort_values(
        ["Basic status", "Missing %", "Feature"],
        ascending=[True, True, True],
    )


def build_v51_correlation_pairs(
    enriched_panel: pd.DataFrame,
    candidate_features: list[str],
    threshold: float = 0.85,
) -> pd.DataFrame:
    """
    Détecte les doublons informationnels via corrélation absolue.
    """
    if enriched_panel is None or enriched_panel.empty or not candidate_features:
        return pd.DataFrame()

    usable_cols = []

    for col in candidate_features:
        if col not in enriched_panel.columns:
            continue

        series = pd.to_numeric(enriched_panel[col], errors="coerce")

        if series.notna().sum() < 30:
            continue

        if series.nunique(dropna=True) < 5:
            continue

        usable_cols.append(col)

    if len(usable_cols) < 2:
        return pd.DataFrame()

    matrix = enriched_panel[usable_cols].apply(pd.to_numeric, errors="coerce")
    corr = matrix.corr().abs()

    rows = []

    for i, f1 in enumerate(usable_cols):
        for f2 in usable_cols[i + 1:]:
            value = _safe_float(corr.loc[f1, f2], np.nan)

            if pd.isna(value):
                continue

            if value >= threshold:
                severity = "High redundancy"
            elif value >= 0.70:
                severity = "Moderate redundancy"
            else:
                severity = "Low"

            if value >= 0.70:
                rows.append(
                    {
                        "Feature 1": f1,
                        "Feature 2": f2,
                        "Abs correlation": value,
                        "Severity": severity,
                    }
                )

    if not rows:
        return pd.DataFrame()

    return pd.DataFrame(rows).sort_values(
        "Abs correlation",
        ascending=False,
    )


def build_v51_correlation_summary(
    corr_pairs: pd.DataFrame,
    candidate_features: list[str],
    hard_threshold: float = 0.85,
) -> pd.DataFrame:
    """
    Résumé de redondance corrélationnelle.
    """
    candidate_count = len(candidate_features)

    if corr_pairs is None or corr_pairs.empty:
        return pd.DataFrame(
            [
                {
                    "Control": "Candidate features",
                    "Status": "Info",
                    "Detail": f"{candidate_count} candidate feature(s).",
                },
                {
                    "Control": "High-correlation pairs",
                    "Status": "OK",
                    "Detail": "Aucune paire >= 70% détectée.",
                },
                {
                    "Control": "Correlation decision",
                    "Status": "OK",
                    "Detail": "Pas de redondance forte détectée.",
                },
            ]
        )

    high = int((corr_pairs["Abs correlation"] >= hard_threshold).sum())
    moderate = int(
        ((corr_pairs["Abs correlation"] >= 0.70) & (corr_pairs["Abs correlation"] < hard_threshold)).sum()
    )

    involved = set(corr_pairs["Feature 1"].astype(str)).union(
        set(corr_pairs["Feature 2"].astype(str))
    )

    if high == 0:
        status = "OK"
        detail = "Aucune paire au-dessus du seuil dur."
    elif high <= max(2, candidate_count // 10):
        status = "Watch"
        detail = "Quelques redondances fortes : prévoir shortlist."
    else:
        status = "High redundancy"
        detail = "Trop de redondances : réduire les features avant modèle."

    rows = [
        {
            "Control": "Candidate features",
            "Status": "Info",
            "Detail": f"{candidate_count} candidate feature(s).",
        },
        {
            "Control": "High-correlation pairs",
            "Status": status,
            "Detail": f"{high} paire(s) >= {hard_threshold:.0%}.",
        },
        {
            "Control": "Moderate-correlation pairs",
            "Status": "Info",
            "Detail": f"{moderate} paire(s) entre 70% et {hard_threshold:.0%}.",
        },
        {
            "Control": "Features involved",
            "Status": "Info",
            "Detail": f"{len(involved)} feature(s) impliquée(s).",
        },
        {
            "Control": "Correlation decision",
            "Status": status,
            "Detail": detail,
        },
    ]

    return pd.DataFrame(rows)


def build_v51_temporal_stability(
    enriched_panel: pd.DataFrame,
    candidate_features: list[str],
    n_splits: int = 5,
) -> pd.DataFrame:
    """
    Drift temporel simple des features.
    Pas de modèle, pas de label.
    """
    if (
        enriched_panel is None
        or enriched_panel.empty
        or "date" not in enriched_panel.columns
        or not candidate_features
    ):
        return pd.DataFrame()

    work = enriched_panel.copy()
    work["date"] = pd.to_datetime(work["date"], errors="coerce")
    work = work.dropna(subset=["date"]).sort_values("date")

    if work.empty:
        return pd.DataFrame()

    unique_dates = np.array(sorted(work["date"].dropna().unique()))

    if len(unique_dates) < n_splits:
        return pd.DataFrame()

    chunks = np.array_split(unique_dates, n_splits)
    fold_map = {}

    for idx, chunk in enumerate(chunks, start=1):
        for date_value in chunk:
            fold_map[pd.Timestamp(date_value)] = idx

    work["_v51_time_fold"] = work["date"].map(lambda x: fold_map.get(pd.Timestamp(x), np.nan))
    work = work.dropna(subset=["_v51_time_fold"])

    rows = []

    for col in candidate_features:
        if col not in work.columns:
            continue

        series = pd.to_numeric(work[col], errors="coerce")
        overall_std = _safe_float(series.std(), np.nan)

        if pd.isna(overall_std) or overall_std == 0:
            drift_score = np.nan
            status = "No variation"
        else:
            fold_means = work.groupby("_v51_time_fold")[col].apply(
                lambda s: pd.to_numeric(s, errors="coerce").mean()
            )
            drift_score = (fold_means.max() - fold_means.min()) / overall_std

            if drift_score <= 0.75:
                status = "Stable"
            elif drift_score <= 1.50:
                status = "Watch"
            else:
                status = "Unstable"

        rows.append(
            {
                "Feature": col,
                "Time folds": int(work["_v51_time_fold"].nunique()),
                "Temporal drift score": drift_score,
                "Temporal status": status,
            }
        )

    if not rows:
        return pd.DataFrame()

    return pd.DataFrame(rows).sort_values(
        ["Temporal status", "Temporal drift score", "Feature"],
        ascending=[True, False, True],
    )


def build_v51_ticker_stability(
    enriched_panel: pd.DataFrame,
    candidate_features: list[str],
) -> pd.DataFrame:
    """
    Stabilité cross-sectional par ticker.
    """
    if (
        enriched_panel is None
        or enriched_panel.empty
        or "ticker" not in enriched_panel.columns
        or not candidate_features
    ):
        return pd.DataFrame()

    work = enriched_panel.copy()
    work["ticker"] = work["ticker"].astype(str)

    rows = []

    for col in candidate_features:
        if col not in work.columns:
            continue

        numeric = pd.to_numeric(work[col], errors="coerce")
        overall_std = _safe_float(numeric.std(), np.nan)

        by_ticker_mean = work.groupby("ticker")[col].apply(
            lambda s: pd.to_numeric(s, errors="coerce").mean()
        )

        by_ticker_missing = work.groupby("ticker")[col].apply(
            lambda s: pd.to_numeric(s, errors="coerce").isna().mean()
        )

        if pd.isna(overall_std) or overall_std == 0:
            dispersion = np.nan
            status = "No variation"
        else:
            dispersion = by_ticker_mean.std() / overall_std

            if dispersion <= 0.75:
                status = "Stable"
            elif dispersion <= 1.50:
                status = "Watch"
            else:
                status = "Ticker-dependent"

        rows.append(
            {
                "Feature": col,
                "Tickers": int(work["ticker"].nunique()),
                "Ticker mean dispersion": dispersion,
                "Max ticker missing %": by_ticker_missing.max(),
                "Ticker stability": status,
            }
        )

    if not rows:
        return pd.DataFrame()

    return pd.DataFrame(rows).sort_values(
        ["Ticker stability", "Ticker mean dispersion", "Feature"],
        ascending=[True, False, True],
    )


def build_v51_feature_scorecard(
    basic_audit: pd.DataFrame,
    temporal_stability: pd.DataFrame,
    ticker_stability: pd.DataFrame,
    corr_pairs: pd.DataFrame,
    leakage_audit: pd.DataFrame,
) -> pd.DataFrame:
    """
    Score final par feature : Keep / Watch / Drop.
    """
    if basic_audit is None or basic_audit.empty:
        return pd.DataFrame()

    score = basic_audit.copy()

    if temporal_stability is not None and not temporal_stability.empty:
        score = score.merge(
            temporal_stability[["Feature", "Temporal drift score", "Temporal status"]],
            on="Feature",
            how="left",
        )
    else:
        score["Temporal drift score"] = np.nan
        score["Temporal status"] = "Unavailable"

    if ticker_stability is not None and not ticker_stability.empty:
        score = score.merge(
            ticker_stability[["Feature", "Ticker mean dispersion", "Max ticker missing %", "Ticker stability"]],
            on="Feature",
            how="left",
        )
    else:
        score["Ticker mean dispersion"] = np.nan
        score["Max ticker missing %"] = np.nan
        score["Ticker stability"] = "Unavailable"

    corr_counts = {}

    if corr_pairs is not None and not corr_pairs.empty:
        high_corr = corr_pairs[corr_pairs["Abs correlation"] >= 0.85].copy()

        for col in ["Feature 1", "Feature 2"]:
            for feature in high_corr[col].astype(str).tolist():
                corr_counts[feature] = corr_counts.get(feature, 0) + 1

    score["High corr pairs"] = score["Feature"].astype(str).map(corr_counts).fillna(0).astype(int)

    forbidden_candidates = set()

    if leakage_audit is not None and not leakage_audit.empty:
        if "Column role" in leakage_audit.columns and "Leakage status" in leakage_audit.columns:
            bad = leakage_audit[
                (leakage_audit["Column role"] == "Candidate")
                & (leakage_audit["Leakage status"] == "Forbidden in model")
            ]

            if not bad.empty and "Column" in bad.columns:
                forbidden_candidates = set(bad["Column"].astype(str).tolist())

    final_scores = []
    decisions = []
    reasons = []

    for _, row in score.iterrows():
        feature = str(row.get("Feature"))
        points = 100.0
        reason = []

        missing = _safe_float(row.get("Missing %"), 0) or 0
        unique_values = int(_safe_float(row.get("Unique values"), 0) or 0)
        high_corr_count = int(_safe_float(row.get("High corr pairs"), 0) or 0)

        temporal_status = str(row.get("Temporal status", "Unavailable"))
        ticker_status = str(row.get("Ticker stability", "Unavailable"))

        if feature in forbidden_candidates:
            points = 0
            reason.append("leakage/name forbidden")

        points -= min(40, missing * 120)

        if unique_values < 5:
            points -= 35
            reason.append("low cardinality")
        elif unique_values < 10:
            points -= 15
            reason.append("limited cardinality")

        if high_corr_count > 0:
            points -= min(25, high_corr_count * 7)
            reason.append("high correlation redundancy")

        if temporal_status == "Unstable":
            points -= 30
            reason.append("temporal drift")
        elif temporal_status == "Watch":
            points -= 10
            reason.append("temporal watch")

        if ticker_status == "Ticker-dependent":
            points -= 25
            reason.append("ticker dependent")
        elif ticker_status == "Watch":
            points -= 10
            reason.append("ticker watch")

        points = clamp(points, 0, 100)

        if points >= 70 and feature not in forbidden_candidates:
            decision = "Keep candidate"
        elif points >= 45 and feature not in forbidden_candidates:
            decision = "Watch candidate"
        else:
            decision = "Drop / block"

        final_scores.append(points)
        decisions.append(decision)
        reasons.append(", ".join(reason) if reason else "clean enough for research audit")

    score["V5.1 quality score"] = final_scores
    score["V5.1 decision"] = decisions
    score["Decision reason"] = reasons

    return score.sort_values(
        ["V5.1 decision", "V5.1 quality score", "Missing %"],
        ascending=[True, False, True],
    )


def build_v51_manifest(
    scorecard: pd.DataFrame,
    corr_summary: pd.DataFrame,
    leakage_audit: pd.DataFrame,
) -> pd.DataFrame:
    """
    Décision read-only V5.1.
    """
    if scorecard is None or scorecard.empty:
        return pd.DataFrame(
            [
                {
                    "Decision item": "V5.1 audit",
                    "Status": "KO",
                    "Detail": "Aucune feature candidate auditée.",
                }
            ]
        )

    total = len(scorecard)
    keep = int((scorecard["V5.1 decision"] == "Keep candidate").sum())
    watch = int((scorecard["V5.1 decision"] == "Watch candidate").sum())
    drop = int((scorecard["V5.1 decision"] == "Drop / block").sum())

    forbidden_candidate_count = 0

    if leakage_audit is not None and not leakage_audit.empty:
        if "Column role" in leakage_audit.columns and "Leakage status" in leakage_audit.columns:
            bad = leakage_audit[
                (leakage_audit["Column role"] == "Candidate")
                & (leakage_audit["Leakage status"] == "Forbidden in model")
            ]
            forbidden_candidate_count = len(bad)

    corr_status = "Unknown"

    if corr_summary is not None and not corr_summary.empty:
        row = corr_summary[corr_summary["Control"] == "Correlation decision"]

        if not row.empty:
            corr_status = str(row.iloc[0].get("Status", "Unknown"))

    if forbidden_candidate_count > 0:
        audit_status = "Blocked"
        detail = "Au moins une feature candidate est interdite par leakage/name guard."
    elif keep >= 10 and corr_status in ["OK", "Watch"]:
        audit_status = "Research constructive"
        detail = "Feature set enrichi exploitable pour prochain audit, sans promotion modèle."
    elif keep >= 5:
        audit_status = "Watchlist"
        detail = "Feature set utilisable mais shortlist nécessaire avant V5.2."
    else:
        audit_status = "Weak"
        detail = "Trop peu de features propres pour relancer un ranker enrichi."

    rows = [
        {
            "Decision item": "V5.1 feature quality audit",
            "Status": audit_status,
            "Detail": detail,
        },
        {
            "Decision item": "Candidate features audited",
            "Status": "Info",
            "Detail": f"{total} candidate feature(s).",
        },
        {
            "Decision item": "Keep candidates",
            "Status": "OK" if keep >= 10 else "À surveiller",
            "Detail": f"{keep} feature(s).",
        },
        {
            "Decision item": "Watch candidates",
            "Status": "Info",
            "Detail": f"{watch} feature(s).",
        },
        {
            "Decision item": "Drop / blocked candidates",
            "Status": "À surveiller" if drop > 0 else "OK",
            "Detail": f"{drop} feature(s).",
        },
        {
            "Decision item": "Leakage guard",
            "Status": "OK" if forbidden_candidate_count == 0 else "Blocked",
            "Detail": f"{forbidden_candidate_count} forbidden candidate feature(s).",
        },
        {
            "Decision item": "Correlation guard",
            "Status": corr_status,
            "Detail": "Réduire les features corrélées avant tout modèle si status != OK.",
        },
        {
            "Decision item": "Decision Engine",
            "Status": "Blocked",
            "Detail": "Aucune intégration. V5.1 reste audit read-only.",
        },
        {
            "Decision item": "Next step",
            "Status": "Research only",
            "Detail": "V5.2 pourra tester un enriched ranker seulement après shortlist Keep/Watch.",
        },
    ]

    return pd.DataFrame(rows)


def run_feature_quality_audit_v51(
    enriched_panel: pd.DataFrame,
    inventory: pd.DataFrame | None = None,
    corr_threshold: float = 0.85,
) -> dict:
    """
    Runner V5.1.
    Aucun modèle.
    Aucun signal.
    Aucun usage de probabilité.
    """
    if enriched_panel is None or enriched_panel.empty:
        return {
            "candidate_features": [],
            "manifest": pd.DataFrame(),
            "basic_audit": pd.DataFrame(),
            "corr_pairs": pd.DataFrame(),
            "corr_summary": pd.DataFrame(),
            "temporal_stability": pd.DataFrame(),
            "ticker_stability": pd.DataFrame(),
            "leakage_audit": pd.DataFrame(),
            "scorecard": pd.DataFrame(),
        }

    candidate_features = _v51_candidate_feature_columns(
        enriched_panel=enriched_panel,
        inventory=inventory,
    )

    leakage_audit = build_v51_leakage_audit(
        enriched_panel=enriched_panel,
        candidate_features=candidate_features,
    )

    basic_audit = build_v51_feature_missing_unique_audit(
        enriched_panel=enriched_panel,
        candidate_features=candidate_features,
    )

    corr_pairs = build_v51_correlation_pairs(
        enriched_panel=enriched_panel,
        candidate_features=candidate_features,
        threshold=float(corr_threshold),
    )

    corr_summary = build_v51_correlation_summary(
        corr_pairs=corr_pairs,
        candidate_features=candidate_features,
        hard_threshold=float(corr_threshold),
    )

    temporal_stability = build_v51_temporal_stability(
        enriched_panel=enriched_panel,
        candidate_features=candidate_features,
        n_splits=5,
    )

    ticker_stability = build_v51_ticker_stability(
        enriched_panel=enriched_panel,
        candidate_features=candidate_features,
    )

    scorecard = build_v51_feature_scorecard(
        basic_audit=basic_audit,
        temporal_stability=temporal_stability,
        ticker_stability=ticker_stability,
        corr_pairs=corr_pairs,
        leakage_audit=leakage_audit,
    )

    manifest = build_v51_manifest(
        scorecard=scorecard,
        corr_summary=corr_summary,
        leakage_audit=leakage_audit,
    )

    return {
        "candidate_features": candidate_features,
        "manifest": manifest,
        "basic_audit": basic_audit,
        "corr_pairs": corr_pairs,
        "corr_summary": corr_summary,
        "temporal_stability": temporal_stability,
        "ticker_stability": ticker_stability,
        "leakage_audit": leakage_audit,
        "scorecard": scorecard,
    }


def render_v51_feature_quality_audit_panel(
    v50_results: dict,
    ticker: str,
) -> None:
    """
    Render V5.1.
    À appeler après le bloc V5.0, au même niveau que le render V5.0.
    """
    st.divider()
    st.subheader("V5.1 — Feature Correlation / Stability / Leakage Audit")

    st.warning(
        "V5.1 est read-only. Il audite les features enrichies V5.0 : corrélations, missing values, "
        "stabilité temporelle, stabilité par ticker et leakage guard. Aucun modèle, aucune probabilité, "
        "aucune intégration Decision Engine."
    )

    if not isinstance(v50_results, dict) or not v50_results:
        st.info("Construis d'abord V5.0 pour activer V5.1.")
        return

    enriched_panel_v50 = v50_results.get("enriched_panel", pd.DataFrame())
    inventory_v50 = v50_results.get("inventory", pd.DataFrame())

    if enriched_panel_v50 is None or enriched_panel_v50.empty:
        st.info("Panel enrichi V5.0 indisponible.")
        return

    v51_corr_threshold = st.selectbox(
        "V5.1 hard correlation threshold",
        [0.80, 0.85, 0.90, 0.95],
        index=1,
        key=f"ml_v51_corr_threshold_{ticker}",
    )

    v51_results_key = f"ml_v51_results_cache_{ticker}"

    run_v51 = st.button(
        "Lancer V5.1 feature quality audit",
        key=f"ml_v51_run_{ticker}",
    )

    if run_v51:
        with st.spinner("V5.1 — audit qualité des features enrichies..."):
            st.session_state[v51_results_key] = run_feature_quality_audit_v51(
                enriched_panel=enriched_panel_v50,
                inventory=inventory_v50,
                corr_threshold=float(v51_corr_threshold),
            )

    v51_results = st.session_state.get(v51_results_key, {})

    if not v51_results:
        st.info("Lance V5.1 pour auditer les features enrichies.")
        return

    manifest_v51 = v51_results.get("manifest", pd.DataFrame())
    scorecard_v51 = v51_results.get("scorecard", pd.DataFrame())
    corr_summary_v51 = v51_results.get("corr_summary", pd.DataFrame())
    corr_pairs_v51 = v51_results.get("corr_pairs", pd.DataFrame())
    temporal_v51 = v51_results.get("temporal_stability", pd.DataFrame())
    ticker_stability_v51 = v51_results.get("ticker_stability", pd.DataFrame())
    leakage_v51 = v51_results.get("leakage_audit", pd.DataFrame())

    if not manifest_v51.empty:
        st.subheader("V5.1 — Feature audit manifest")
        st.dataframe(manifest_v51, width="stretch", hide_index=True)

    if not scorecard_v51.empty:
        display_scorecard_v51 = scorecard_v51.copy()

        for col in [
            "Missing %",
            "Max ticker missing %",
        ]:
            if col in display_scorecard_v51.columns:
                display_scorecard_v51[col] = display_scorecard_v51[col].apply(_fmt_pct)

        for col in [
            "Mean",
            "Std",
            "Min",
            "Max",
            "Temporal drift score",
            "Ticker mean dispersion",
            "V5.1 quality score",
        ]:
            if col in display_scorecard_v51.columns:
                display_scorecard_v51[col] = display_scorecard_v51[col].apply(_fmt_num)

        st.subheader("V5.1 — Feature quality scorecard")
        st.dataframe(display_scorecard_v51, width="stretch", hide_index=True)

    if not corr_summary_v51.empty:
        st.subheader("V5.1 — Correlation summary")
        st.dataframe(corr_summary_v51, width="stretch", hide_index=True)

    if corr_pairs_v51 is not None and not corr_pairs_v51.empty:
        display_corr_v51 = corr_pairs_v51.copy()

        if "Abs correlation" in display_corr_v51.columns:
            display_corr_v51["Abs correlation"] = display_corr_v51["Abs correlation"].apply(_fmt_pct)

        st.subheader("V5.1 — High / moderate correlation pairs")
        st.dataframe(display_corr_v51.head(80), width="stretch", hide_index=True)

    if temporal_v51 is not None and not temporal_v51.empty:
        display_temporal_v51 = temporal_v51.copy()

        if "Temporal drift score" in display_temporal_v51.columns:
            display_temporal_v51["Temporal drift score"] = display_temporal_v51["Temporal drift score"].apply(_fmt_num)

        st.subheader("V5.1 — Temporal feature stability")
        st.dataframe(display_temporal_v51, width="stretch", hide_index=True)

    if ticker_stability_v51 is not None and not ticker_stability_v51.empty:
        display_ticker_stability_v51 = ticker_stability_v51.copy()

        if "Ticker mean dispersion" in display_ticker_stability_v51.columns:
            display_ticker_stability_v51["Ticker mean dispersion"] = display_ticker_stability_v51[
                "Ticker mean dispersion"
            ].apply(_fmt_num)

        if "Max ticker missing %" in display_ticker_stability_v51.columns:
            display_ticker_stability_v51["Max ticker missing %"] = display_ticker_stability_v51[
                "Max ticker missing %"
            ].apply(_fmt_pct)

        st.subheader("V5.1 — Cross-ticker feature stability")
        st.dataframe(display_ticker_stability_v51, width="stretch", hide_index=True)

    if leakage_v51 is not None and not leakage_v51.empty:
        st.subheader("V5.1 — Leakage / forbidden feature audit")
        st.dataframe(leakage_v51, width="stretch", hide_index=True)

    st.info(
        "V5.1 audite uniquement les features enrichies. Le prochain niveau logique est V5.2 : "
        "ranker enrichi research-only sur shortlist Keep/Watch, toujours sans probabilité exploitable."
    )

# ============================================================
# V5.1.1 — FEATURE REDUNDANCY PRUNING / SHORTLIST BUILDER
# ============================================================

def _v511_find(parent: dict, item: str) -> str:
    """Union-find root lookup for redundancy clusters."""
    parent.setdefault(item, item)
    while parent[item] != item:
        parent[item] = parent[parent[item]]
        item = parent[item]
    return item


def _v511_union(parent: dict, a: str, b: str) -> None:
    """Union two feature nodes in the same redundancy cluster."""
    ra = _v511_find(parent, a)
    rb = _v511_find(parent, b)
    if ra != rb:
        parent[rb] = ra


def _v511_feature_priority(row: pd.Series) -> tuple:
    """
    Priority used to choose a representative inside a redundancy cluster.
    Higher is better except missing/correlation counts, which are inverted.
    """
    decision = str(row.get("V5.1 decision", ""))
    decision_priority = {
        "Keep candidate": 2,
        "Watch candidate": 1,
        "Drop / block": 0,
    }.get(decision, 0)

    quality = _safe_float(row.get("V5.1 quality score"), 0) or 0
    missing = _safe_float(row.get("Missing %"), 1) or 1
    high_corr = int(_safe_float(row.get("High corr pairs"), 0) or 0)
    unique_values = int(_safe_float(row.get("Unique values"), 0) or 0)

    return (
        decision_priority,
        quality,
        unique_values,
        -missing,
        -high_corr,
    )


def build_v511_redundancy_clusters(
    scorecard: pd.DataFrame,
    corr_pairs: pd.DataFrame,
    corr_threshold: float = 0.85,
) -> pd.DataFrame:
    """
    Regroupe les features fortement corrélées et choisit une représentante par cluster.

    Lecture seule : aucune colonne n'est supprimée du panel.
    """
    if scorecard is None or scorecard.empty:
        return pd.DataFrame()

    if "Feature" not in scorecard.columns:
        return pd.DataFrame()

    work = scorecard.copy()
    work["Feature"] = work["Feature"].astype(str)

    if "V5.1 decision" in work.columns:
        eligible = work[work["V5.1 decision"].astype(str).isin(["Keep candidate", "Watch candidate"])].copy()
    else:
        eligible = work.copy()

    if eligible.empty:
        return pd.DataFrame()

    candidate_features = eligible["Feature"].astype(str).tolist()
    parent = {feature: feature for feature in candidate_features}

    high_pairs = pd.DataFrame()
    if corr_pairs is not None and not corr_pairs.empty:
        required = ["Feature 1", "Feature 2", "Abs correlation"]
        if all(col in corr_pairs.columns for col in required):
            high_pairs = corr_pairs.copy()
            high_pairs["Feature 1"] = high_pairs["Feature 1"].astype(str)
            high_pairs["Feature 2"] = high_pairs["Feature 2"].astype(str)
            high_pairs["Abs correlation"] = pd.to_numeric(
                high_pairs["Abs correlation"],
                errors="coerce",
            )
            high_pairs = high_pairs[
                (high_pairs["Abs correlation"] >= float(corr_threshold))
                & high_pairs["Feature 1"].isin(candidate_features)
                & high_pairs["Feature 2"].isin(candidate_features)
            ].copy()

            for _, row in high_pairs.iterrows():
                _v511_union(parent, str(row["Feature 1"]), str(row["Feature 2"]))

    cluster_map = {}
    for feature in candidate_features:
        root = _v511_find(parent, feature)
        cluster_map.setdefault(root, []).append(feature)

    rows = []
    feature_lookup = {
        str(row.get("Feature")): row
        for _, row in eligible.iterrows()
    }

    for cluster_idx, (_, features) in enumerate(cluster_map.items(), start=1):
        features = sorted(set(features))

        ranked_features = sorted(
            features,
            key=lambda f: _v511_feature_priority(feature_lookup.get(f, pd.Series(dtype=object))),
            reverse=True,
        )

        representative = ranked_features[0]
        representative_row = feature_lookup.get(representative, pd.Series(dtype=object))

        if len(features) <= 1:
            max_corr = 0.0
        elif not high_pairs.empty:
            pair_mask = (
                high_pairs["Feature 1"].isin(features)
                & high_pairs["Feature 2"].isin(features)
            )
            max_corr = _safe_float(high_pairs.loc[pair_mask, "Abs correlation"].max(), 0) or 0
        else:
            max_corr = 0.0

        if len(features) == 1:
            cluster_status = "Standalone"
            action = "Keep representative"
        else:
            cluster_status = "Redundant cluster"
            action = "Keep representative; block redundant peers"

        rows.append(
            {
                "Cluster ID": f"C{cluster_idx:02d}",
                "Cluster size": len(features),
                "Representative feature": representative,
                "Representative decision": str(representative_row.get("V5.1 decision", "N/A")),
                "Representative quality score": _safe_float(
                    representative_row.get("V5.1 quality score"),
                    np.nan,
                ),
                "Representative missing %": _safe_float(
                    representative_row.get("Missing %"),
                    np.nan,
                ),
                "Max abs corr in cluster": max_corr,
                "Cluster status": cluster_status,
                "Action": action,
                "Cluster features": ", ".join(features),
            }
        )

    out = pd.DataFrame(rows)
    if out.empty:
        return out

    return out.sort_values(
        ["Cluster size", "Representative quality score", "Max abs corr in cluster"],
        ascending=[False, False, False],
    )


def build_v511_feature_shortlist(
    scorecard: pd.DataFrame,
    clusters: pd.DataFrame,
) -> pd.DataFrame:
    """
    Construit une shortlist modèle future : une seule représentante par cluster corrélé.
    """
    if scorecard is None or scorecard.empty or "Feature" not in scorecard.columns:
        return pd.DataFrame()

    work = scorecard.copy()
    work["Feature"] = work["Feature"].astype(str)

    feature_to_cluster = {}
    feature_to_representative = {}
    representative_set = set()

    if clusters is not None and not clusters.empty:
        for _, row in clusters.iterrows():
            cluster_id = str(row.get("Cluster ID"))
            representative = str(row.get("Representative feature"))
            features = str(row.get("Cluster features", "")).split(",")
            features = [f.strip() for f in features if f.strip()]

            representative_set.add(representative)

            for feature in features:
                feature_to_cluster[feature] = cluster_id
                feature_to_representative[feature] = representative

    rows = []

    for _, row in work.iterrows():
        feature = str(row.get("Feature"))
        decision = str(row.get("V5.1 decision", "Unknown"))
        cluster_id = feature_to_cluster.get(feature, "Unclustered")
        representative = feature_to_representative.get(feature, feature)
        is_representative = feature == representative

        if decision == "Drop / block":
            role = "Drop / block"
            reason = "V5.1 rejected this feature before redundancy pruning."
        elif is_representative and decision == "Keep candidate":
            role = "Shortlist keep"
            reason = "Best representative of its redundancy cluster."
        elif is_representative and decision == "Watch candidate":
            role = "Shortlist watch"
            reason = "Representative kept only as watch candidate."
        elif not is_representative:
            role = "Redundant / block"
            reason = f"Redundant with representative {representative}."
        else:
            role = "Watch / review"
            reason = "Defensive fallback; review manually."

        rows.append(
            {
                "Feature": feature,
                "V5.1 decision": decision,
                "V5.1 quality score": row.get("V5.1 quality score", np.nan),
                "Missing %": row.get("Missing %", np.nan),
                "Unique values": row.get("Unique values", np.nan),
                "High corr pairs": row.get("High corr pairs", np.nan),
                "Temporal status": row.get("Temporal status", "N/A"),
                "Ticker stability": row.get("Ticker stability", "N/A"),
                "Redundancy cluster": cluster_id,
                "Cluster representative": representative,
                "V5.1.1 shortlist role": role,
                "V5.1.1 reason": reason,
            }
        )

    out = pd.DataFrame(rows)
    if out.empty:
        return out

    role_order = {
        "Shortlist keep": 0,
        "Shortlist watch": 1,
        "Watch / review": 2,
        "Redundant / block": 3,
        "Drop / block": 4,
    }

    out["_role_order"] = out["V5.1.1 shortlist role"].map(role_order).fillna(99)
    out = out.sort_values(
        ["_role_order", "V5.1 quality score", "Missing %", "Feature"],
        ascending=[True, False, True, True],
    ).drop(columns=["_role_order"])

    return out


def build_v511_manifest(
    shortlist: pd.DataFrame,
    clusters: pd.DataFrame,
) -> pd.DataFrame:
    """
    Manifest research-only après pruning redondance.
    """
    if shortlist is None or shortlist.empty:
        return pd.DataFrame(
            [
                {
                    "Decision item": "V5.1.1 shortlist",
                    "Status": "KO",
                    "Detail": "Aucune shortlist construite.",
                }
            ]
        )

    keep = int((shortlist["V5.1.1 shortlist role"] == "Shortlist keep").sum())
    watch = int((shortlist["V5.1.1 shortlist role"] == "Shortlist watch").sum())
    redundant = int((shortlist["V5.1.1 shortlist role"] == "Redundant / block").sum())
    drop = int((shortlist["V5.1.1 shortlist role"] == "Drop / block").sum())
    total = len(shortlist)

    cluster_count = 0
    redundant_clusters = 0
    max_cluster_size = 0

    if clusters is not None and not clusters.empty:
        cluster_count = len(clusters)
        redundant_clusters = int((clusters["Cluster size"] > 1).sum())
        max_cluster_size = int(clusters["Cluster size"].max())

    shortlist_count = keep + watch

    if keep >= 8:
        status = "Research shortlist ready"
        detail = f"{keep} Keep features après pruning. V5.2 peut être testé en research-only."
    elif shortlist_count >= 8:
        status = "Watchlist shortlist"
        detail = f"{keep} Keep + {watch} Watch features. V5.2 possible mais fragile."
    elif shortlist_count >= 5:
        status = "Thin shortlist"
        detail = f"Shortlist limitée : {shortlist_count} features seulement. Ajouter features avant V5.2."
    else:
        status = "Rejected"
        detail = "Shortlist trop courte après pruning. Ne pas lancer V5.2."

    rows = [
        {
            "Decision item": "V5.1.1 redundancy pruning",
            "Status": status,
            "Detail": detail,
        },
        {
            "Decision item": "Candidate features audited",
            "Status": "Info",
            "Detail": f"{total} feature(s) auditées depuis V5.1.",
        },
        {
            "Decision item": "Shortlist keep",
            "Status": "OK" if keep >= 8 else "À surveiller",
            "Detail": f"{keep} feature(s).",
        },
        {
            "Decision item": "Shortlist watch",
            "Status": "Info",
            "Detail": f"{watch} feature(s).",
        },
        {
            "Decision item": "Redundant blocked",
            "Status": "OK" if redundant > 0 else "Info",
            "Detail": f"{redundant} feature(s) bloquée(s) par redondance.",
        },
        {
            "Decision item": "Drop / block",
            "Status": "Info",
            "Detail": f"{drop} feature(s) déjà rejetée(s).",
        },
        {
            "Decision item": "Redundancy clusters",
            "Status": "OK" if redundant_clusters > 0 else "Info",
            "Detail": f"{redundant_clusters}/{cluster_count} cluster(s) redondant(s), taille max {max_cluster_size}.",
        },
        {
            "Decision item": "Model training",
            "Status": "Blocked",
            "Detail": "V5.1.1 ne lance aucun modèle. Il prépare seulement une shortlist.",
        },
        {
            "Decision item": "Probability usage",
            "Status": "Blocked",
            "Detail": "Aucune probabilité exploitable n'est créée.",
        },
        {
            "Decision item": "Decision Engine",
            "Status": "Blocked",
            "Detail": "Aucune intégration autorisée.",
        },
        {
            "Decision item": "Next step",
            "Status": "Research only",
            "Detail": "V5.2 devra utiliser uniquement Shortlist keep/watch, avec purge OOS et probabilités toujours bloquées.",
        },
    ]

    return pd.DataFrame(rows)


def run_v511_redundancy_pruning(
    v51_results: dict,
    corr_threshold: float = 0.85,
) -> dict:
    """
    Runner V5.1.1.
    Aucun modèle, aucune probabilité, aucune intégration.
    """
    if not isinstance(v51_results, dict) or not v51_results:
        return {
            "clusters": pd.DataFrame(),
            "shortlist": pd.DataFrame(),
            "manifest": pd.DataFrame(),
        }

    scorecard = v51_results.get("scorecard", pd.DataFrame())
    corr_pairs = v51_results.get("corr_pairs", pd.DataFrame())

    clusters = build_v511_redundancy_clusters(
        scorecard=scorecard,
        corr_pairs=corr_pairs,
        corr_threshold=float(corr_threshold),
    )

    shortlist = build_v511_feature_shortlist(
        scorecard=scorecard,
        clusters=clusters,
    )

    manifest = build_v511_manifest(
        shortlist=shortlist,
        clusters=clusters,
    )

    return {
        "clusters": clusters,
        "shortlist": shortlist,
        "manifest": manifest,
    }


def render_v511_redundancy_pruning_panel(
    v51_results: dict,
    ticker: str,
) -> None:
    """
    Render V5.1.1.
    À appeler après le render V5.1.
    """
    st.divider()
    st.subheader("V5.1.1 — Feature Redundancy Pruning / Shortlist Builder")

    st.warning(
        "V5.1.1 est read-only. Il transforme l'audit V5.1 en shortlist de features non redondantes. "
        "Aucun modèle, aucune probabilité exploitable, aucune intégration Decision Engine."
    )

    if not isinstance(v51_results, dict) or not v51_results:
        st.info("Lance d'abord V5.1 pour activer V5.1.1.")
        return

    scorecard_v51 = v51_results.get("scorecard", pd.DataFrame())

    if scorecard_v51 is None or scorecard_v51.empty:
        st.info("Scorecard V5.1 indisponible.")
        return

    v511_corr_threshold = st.selectbox(
        "V5.1.1 redundancy threshold",
        [0.80, 0.85, 0.90, 0.95],
        index=1,
        key=f"ml_v511_corr_threshold_{ticker}",
    )

    v511_results_key = f"ml_v511_results_cache_{ticker}"

    run_v511 = st.button(
        "Lancer V5.1.1 redundancy pruning / shortlist",
        key=f"ml_v511_run_{ticker}",
    )

    if run_v511:
        with st.spinner("V5.1.1 — pruning des features redondantes..."):
            st.session_state[v511_results_key] = run_v511_redundancy_pruning(
                v51_results=v51_results,
                corr_threshold=float(v511_corr_threshold),
            )

    v511_results = st.session_state.get(v511_results_key, {})

    if not v511_results:
        st.info("Lance V5.1.1 pour générer la shortlist non redondante.")
        return

    manifest_v511 = v511_results.get("manifest", pd.DataFrame())
    clusters_v511 = v511_results.get("clusters", pd.DataFrame())
    shortlist_v511 = v511_results.get("shortlist", pd.DataFrame())

    if manifest_v511 is not None and not manifest_v511.empty:
        st.subheader("V5.1.1 — Shortlist manifest")
        st.dataframe(manifest_v511, width="stretch", hide_index=True)

    if clusters_v511 is not None and not clusters_v511.empty:
        display_clusters_v511 = clusters_v511.copy()

        for col in [
            "Representative missing %",
            "Max abs corr in cluster",
        ]:
            if col in display_clusters_v511.columns:
                display_clusters_v511[col] = display_clusters_v511[col].apply(_fmt_pct)

        if "Representative quality score" in display_clusters_v511.columns:
            display_clusters_v511["Representative quality score"] = display_clusters_v511[
                "Representative quality score"
            ].apply(_fmt_num)

        st.subheader("V5.1.1 — Redundancy clusters")
        st.dataframe(display_clusters_v511, width="stretch", hide_index=True)

    if shortlist_v511 is not None and not shortlist_v511.empty:
        display_shortlist_v511 = shortlist_v511.copy()

        if "Missing %" in display_shortlist_v511.columns:
            display_shortlist_v511["Missing %"] = display_shortlist_v511["Missing %"].apply(_fmt_pct)

        if "V5.1 quality score" in display_shortlist_v511.columns:
            display_shortlist_v511["V5.1 quality score"] = display_shortlist_v511[
                "V5.1 quality score"
            ].apply(_fmt_num)

        st.subheader("V5.1.1 — Feature shortlist")
        st.dataframe(display_shortlist_v511, width="stretch", hide_index=True)

        csv_v511 = shortlist_v511.to_csv(index=False).encode("utf-8")

        st.download_button(
            label="Télécharger shortlist V5.1.1 CSV",
            data=csv_v511,
            file_name=f"ml_feature_shortlist_v511_{ticker}.csv",
            mime="text/csv",
            key=f"ml_v511_download_{ticker}",
        )

    st.info(
        "V5.1.1 ne valide aucun modèle. Il produit uniquement une shortlist non redondante. "
        "Le prochain niveau logique est V5.2 : ranker enrichi research-only sur cette shortlist, "
        "toujours sans probabilité exploitable ni Decision Engine."
    )


# ============================================================
# V5.2 — ENRICHED SHORTLIST RANKER, RESEARCH-ONLY
# ============================================================

def get_v52_shortlist_feature_columns(
    shortlist_v511: pd.DataFrame,
    enriched_panel_v50: pd.DataFrame,
    include_watch: bool = False,
) -> list[str]:
    """
    Retourne uniquement les features autorisées par V5.1.1.

    Règles :
    - Shortlist keep par défaut ;
    - Shortlist watch optionnel ;
    - feature présente dans le panel enrichi ;
    - feature numérique uniquement ;
    - aucun fallback vers toutes les features V5.0.
    """
    if shortlist_v511 is None or shortlist_v511.empty:
        return []

    if enriched_panel_v50 is None or enriched_panel_v50.empty:
        return []

    required = ["Feature", "V5.1.1 shortlist role"]
    if any(col not in shortlist_v511.columns for col in required):
        return []

    allowed_roles = ["Shortlist keep"]
    if include_watch:
        allowed_roles.append("Shortlist watch")

    candidates = (
        shortlist_v511.loc[
            shortlist_v511["V5.1.1 shortlist role"].astype(str).isin(allowed_roles),
            "Feature",
        ]
        .astype(str)
        .tolist()
    )

    feature_cols = []
    for col in candidates:
        if col not in enriched_panel_v50.columns:
            continue

        if not pd.api.types.is_numeric_dtype(enriched_panel_v50[col]):
            continue

        if str(col).startswith(("tb_", "forward_return_", "target_", "label_", "research_")):
            continue

        feature_cols.append(col)

    return list(dict.fromkeys(feature_cols))


def prepare_enriched_shortlist_dataset_v52(
    enriched_panel_v50: pd.DataFrame,
    shortlist_v511: pd.DataFrame,
    include_watch: bool = False,
) -> tuple[pd.DataFrame, pd.Series, pd.DataFrame, pd.DataFrame]:
    """
    Prépare X/y/meta pour V5.2.

    V5.2 ne doit utiliser que la shortlist V5.1.1.
    Aucune feature rejetée/redondante ne doit rentrer dans X.
    """
    if enriched_panel_v50 is None or enriched_panel_v50.empty:
        return pd.DataFrame(), pd.Series(dtype=int), pd.DataFrame(), pd.DataFrame()

    work = _ensure_panel_event_dates_v41(enriched_panel_v50)

    if work.empty:
        return pd.DataFrame(), pd.Series(dtype=int), pd.DataFrame(), pd.DataFrame()

    required = ["ticker", "date", "tb_label", "tb_event_start", "tb_event_end"]
    if any(col not in work.columns for col in required):
        return pd.DataFrame(), pd.Series(dtype=int), pd.DataFrame(), pd.DataFrame()

    feature_cols = get_v52_shortlist_feature_columns(
        shortlist_v511=shortlist_v511,
        enriched_panel_v50=work,
        include_watch=include_watch,
    )

    if not feature_cols:
        return pd.DataFrame(), pd.Series(dtype=int), pd.DataFrame(), pd.DataFrame()

    valid = work.dropna(
        subset=["ticker", "date", "tb_label", "tb_event_start", "tb_event_end"]
    ).copy()

    if valid.empty:
        return pd.DataFrame(), pd.Series(dtype=int), pd.DataFrame(), pd.DataFrame()

    valid["date"] = pd.to_datetime(valid["date"], errors="coerce")
    valid["tb_event_start"] = pd.to_datetime(valid["tb_event_start"], errors="coerce")
    valid["tb_event_end"] = pd.to_datetime(valid["tb_event_end"], errors="coerce")
    valid = valid.dropna(subset=["date", "tb_event_start", "tb_event_end"])

    if valid.empty:
        return pd.DataFrame(), pd.Series(dtype=int), pd.DataFrame(), pd.DataFrame()

    X = valid[feature_cols].copy().replace([np.inf, -np.inf], np.nan)
    y = (valid["tb_label"].astype(float) == 1.0).astype(int)

    meta_cols = [
        "ticker",
        "date",
        "tb_label",
        "tb_event",
        "tb_event_start",
        "tb_event_end",
        "tb_return",
        "tb_mfe",
        "tb_mae",
        "tb_holding_days",
    ]
    meta_cols = [col for col in meta_cols if col in valid.columns]
    meta = valid[meta_cols].copy()

    feature_usage_rows = []
    for col in feature_cols:
        feature_usage_rows.append(
            {
                "Feature": col,
                "Role": "V5.2 X feature",
                "Missing %": float(valid[col].isna().mean()) if col in valid.columns else np.nan,
                "Unique values": int(valid[col].nunique(dropna=True)) if col in valid.columns else 0,
                "Dtype": str(valid[col].dtype) if col in valid.columns else "N/A",
                "Source": "V5.1.1 shortlist",
            }
        )

    feature_usage = pd.DataFrame(feature_usage_rows)

    return X, y, meta, feature_usage


def run_enriched_shortlist_ranker_v52(
    enriched_panel_v50: pd.DataFrame,
    shortlist_v511: pd.DataFrame,
    n_splits: int = 5,
    embargo_days: int = 5,
    min_train_size: int = 300,
    min_test_size: int = 50,
    model_name: str = "Logistic strong regularization",
    include_watch: bool = False,
) -> dict:
    """
    V5.2 — ranker enrichi sur shortlist V5.1.1.

    Contraintes :
    - research-only ;
    - validation OOS purgée ;
    - ranking intra-fold uniquement ;
    - probabilités brutes bloquées ;
    - aucune intégration Decision Engine.
    """
    empty_result = {
        "folds": pd.DataFrame(),
        "predictions": pd.DataFrame(),
        "bucket_summary": pd.DataFrame(),
        "cumulative_summary": pd.DataFrame(),
        "ticker_breakdown": pd.DataFrame(),
        "feature_usage": pd.DataFrame(),
        "summary": pd.DataFrame(),
        "manifest": pd.DataFrame(),
    }

    if not SKLEARN_AVAILABLE:
        empty_result["manifest"] = pd.DataFrame(
            [
                {
                    "Decision item": "V5.2 enriched ranker",
                    "Status": "KO",
                    "Detail": "scikit-learn indisponible.",
                }
            ]
        )
        return empty_result

    X, y, meta, feature_usage = prepare_enriched_shortlist_dataset_v52(
        enriched_panel_v50=enriched_panel_v50,
        shortlist_v511=shortlist_v511,
        include_watch=include_watch,
    )

    if X.empty or y.empty or meta.empty:
        empty_result["feature_usage"] = feature_usage
        empty_result["manifest"] = pd.DataFrame(
            [
                {
                    "Decision item": "V5.2 enriched ranker",
                    "Status": "KO",
                    "Detail": "Dataset V5.2 indisponible : panel enrichi ou shortlist vide.",
                }
            ]
        )
        return empty_result

    valid = pd.concat(
        [meta.reset_index(drop=True), X.reset_index(drop=True)],
        axis=1,
    )

    valid["_y_success"] = y.values
    valid["date"] = pd.to_datetime(valid["date"], errors="coerce")
    valid["tb_event_start"] = pd.to_datetime(valid["tb_event_start"], errors="coerce")
    valid["tb_event_end"] = pd.to_datetime(valid["tb_event_end"], errors="coerce")

    valid = valid.dropna(
        subset=["ticker", "date", "tb_event_start", "tb_event_end", "_y_success"]
    ).copy()

    valid = valid.sort_values(["tb_event_start", "ticker"]).reset_index(drop=True)

    feature_cols = list(X.columns)

    if valid.empty or len(valid) < min_train_size + min_test_size:
        empty_result["feature_usage"] = feature_usage
        empty_result["manifest"] = pd.DataFrame(
            [
                {
                    "Decision item": "V5.2 enriched ranker",
                    "Status": "KO",
                    "Detail": "Historique insuffisant pour folds OOS.",
                }
            ]
        )
        return empty_result

    unique_dates = np.array(sorted(valid["tb_event_start"].dropna().unique()))

    if len(unique_dates) < n_splits + 20:
        empty_result["feature_usage"] = feature_usage
        empty_result["manifest"] = pd.DataFrame(
            [
                {
                    "Decision item": "V5.2 enriched ranker",
                    "Status": "KO",
                    "Detail": "Trop peu de dates uniques pour split cross-sectional.",
                }
            ]
        )
        return empty_result

    initial_train_dates = max(60, int(len(unique_dates) * 0.35))
    test_dates = unique_dates[initial_train_dates:]

    if len(test_dates) < n_splits:
        empty_result["feature_usage"] = feature_usage
        empty_result["manifest"] = pd.DataFrame(
            [
                {
                    "Decision item": "V5.2 enriched ranker",
                    "Status": "KO",
                    "Detail": "Trop peu de dates test pour les folds demandés.",
                }
            ]
        )
        return empty_result

    date_chunks = np.array_split(test_dates, n_splits)
    embargo_delta = pd.Timedelta(days=int(embargo_days))

    fold_rows = []
    pred_rows = []

    for fold_id, chunk in enumerate(date_chunks, start=1):
        if len(chunk) == 0:
            continue

        test_start = pd.to_datetime(chunk[0])
        test_end = pd.to_datetime(chunk[-1])

        test_mask = (
            (valid["tb_event_start"] >= test_start)
            & (valid["tb_event_start"] <= test_end)
        )

        embargo_cutoff = test_start - embargo_delta

        train_mask = (
            (valid["tb_event_start"] < test_start)
            & (valid["tb_event_end"] < embargo_cutoff)
        )

        train = valid.loc[train_mask].copy()
        test = valid.loc[test_mask].copy()

        status = "OK"

        if len(train) < min_train_size:
            status = "Skipped - train too small"

        if len(test) < min_test_size:
            status = "Skipped - test too small"

        if train["ticker"].nunique() < 5 or test["ticker"].nunique() < 5:
            status = "Skipped - ticker coverage weak"

        if not train.empty and train["_y_success"].nunique() < 2:
            status = "Skipped - train single class"

        if status != "OK":
            fold_rows.append(
                {
                    "Fold": fold_id,
                    "Status": status,
                    "Train size": len(train),
                    "Test size": len(test),
                    "Train tickers": train["ticker"].nunique() if not train.empty else 0,
                    "Test tickers": test["ticker"].nunique() if not test.empty else 0,
                    "Feature count": len(feature_cols),
                }
            )
            continue

        X_train = train[feature_cols].copy()
        y_train = train["_y_success"].astype(int)

        X_test = test[feature_cols].copy()
        y_test = test["_y_success"].astype(int)

        try:
            model = _make_cross_sectional_ranker_v42(model_name)

            dummy = Pipeline(
                steps=[
                    ("imputer", SimpleImputer(strategy="median")),
                    ("model", DummyClassifier(strategy="prior")),
                ]
            )

            model.fit(X_train, y_train)
            dummy.fit(X_train, y_train)

            proba = model.predict_proba(X_test)[:, 1]
            dummy_proba = dummy.predict_proba(X_test)[:, 1]

            metrics = _classification_metrics_v30(y_test, proba, threshold=0.50)
            dummy_metrics = _classification_metrics_v30(y_test, dummy_proba, threshold=0.50)

            ranked_test = test[
                [
                    "ticker",
                    "date",
                    "tb_label",
                    "tb_event",
                    "tb_return",
                    "tb_mfe",
                    "tb_mae",
                    "tb_holding_days",
                ]
            ].copy()

            ranked_test["Fold"] = fold_id
            ranked_test["Model"] = model_name
            ranked_test["Feature set"] = "V5.1.1 shortlist"
            ranked_test["Feature count"] = len(feature_cols)
            ranked_test["y_true_success"] = y_test.values
            ranked_test["p_raw"] = proba
            ranked_test["p_dummy"] = dummy_proba
            ranked_test["rank_pct_in_fold"] = pd.Series(proba).rank(method="average", pct=True).values

            ranked_test["rank_bucket"] = np.select(
                [
                    ranked_test["rank_pct_in_fold"] >= 0.90,
                    ranked_test["rank_pct_in_fold"] >= 0.80,
                    ranked_test["rank_pct_in_fold"] >= 0.70,
                    ranked_test["rank_pct_in_fold"] <= 0.20,
                ],
                [
                    "Top 10%",
                    "Top 20%",
                    "Top 30%",
                    "Bottom 20%",
                ],
                default="Middle 40%",
            )

            pred_rows.append(ranked_test)

            top20 = ranked_test[ranked_test["rank_pct_in_fold"] >= 0.80]
            bottom20 = ranked_test[ranked_test["rank_pct_in_fold"] <= 0.20]

            all_tp = ranked_test["y_true_success"].mean()
            all_return = ranked_test["tb_return"].mean()

            top20_tp = top20["y_true_success"].mean() if not top20.empty else np.nan
            top20_return = top20["tb_return"].mean() if not top20.empty else np.nan
            bottom20_return = bottom20["tb_return"].mean() if not bottom20.empty else np.nan

            fold_rows.append(
                {
                    "Fold": fold_id,
                    "Status": "OK",
                    "Train size": len(train),
                    "Test size": len(test),
                    "Train tickers": train["ticker"].nunique(),
                    "Test tickers": test["ticker"].nunique(),
                    "Feature count": len(feature_cols),
                    "Train TP %": y_train.mean(),
                    "Test TP %": y_test.mean(),
                    "AUC": metrics["ROC AUC"],
                    "Balanced accuracy": metrics["Balanced accuracy"],
                    "Brier": metrics["Brier score"],
                    "Dummy Brier": dummy_metrics["Brier score"],
                    "Brier improvement": dummy_metrics["Brier score"] - metrics["Brier score"],
                    "Avg raw p": metrics["Avg predicted TP %"],
                    "Realized TP %": metrics["Realized TP %"],
                    "Top20 count": len(top20),
                    "Top20 TP %": top20_tp,
                    "Top20 TP lift": top20_tp - all_tp if not pd.isna(top20_tp) else np.nan,
                    "Top20 return": top20_return,
                    "Top20 return lift": top20_return - all_return if not pd.isna(top20_return) else np.nan,
                    "Bottom20 return": bottom20_return,
                    "Top20 minus Bottom20": (
                        top20_return - bottom20_return
                        if not pd.isna(top20_return) and not pd.isna(bottom20_return)
                        else np.nan
                    ),
                    "All return": all_return,
                }
            )

        except Exception as e:
            fold_rows.append(
                {
                    "Fold": fold_id,
                    "Status": f"Error: {str(e)[:100]}",
                    "Train size": len(train),
                    "Test size": len(test),
                    "Train tickers": train["ticker"].nunique() if not train.empty else 0,
                    "Test tickers": test["ticker"].nunique() if not test.empty else 0,
                    "Feature count": len(feature_cols),
                }
            )

    fold_results = pd.DataFrame(fold_rows)

    if pred_rows:
        predictions = pd.concat(pred_rows, ignore_index=True)
    else:
        predictions = pd.DataFrame()

    bucket_summary = build_v52_rank_bucket_summary(predictions)
    cumulative_summary = build_v52_cumulative_rank_summary(predictions)
    ticker_breakdown = build_v52_ticker_breakdown(predictions)
    summary = build_v52_ranker_summary(fold_results, cumulative_summary)
    manifest = build_v52_manifest(
        fold_results=fold_results,
        cumulative_summary=cumulative_summary,
        ticker_breakdown=ticker_breakdown,
        feature_usage=feature_usage,
        include_watch=include_watch,
    )

    return {
        "folds": fold_results,
        "predictions": predictions,
        "bucket_summary": bucket_summary,
        "cumulative_summary": cumulative_summary,
        "ticker_breakdown": ticker_breakdown,
        "feature_usage": feature_usage,
        "summary": summary,
        "manifest": manifest,
    }


def build_v52_rank_bucket_summary(predictions: pd.DataFrame) -> pd.DataFrame:
    """
    Résumé par bandes de rang non cumulatives.
    """
    if predictions is None or predictions.empty:
        return pd.DataFrame()

    required = ["rank_bucket", "y_true_success", "tb_return", "tb_mfe", "tb_mae", "p_raw", "ticker"]
    if any(col not in predictions.columns for col in required):
        return pd.DataFrame()

    rows = []

    for bucket, group in predictions.groupby("rank_bucket"):
        if group.empty:
            continue

        rows.append(
            {
                "Rank bucket": str(bucket),
                "Count": len(group),
                "TP %": group["y_true_success"].mean(),
                "Avg return": group["tb_return"].mean(),
                "Avg MFE": group["tb_mfe"].mean(),
                "Avg MAE": group["tb_mae"].mean(),
                "Avg raw p": group["p_raw"].mean(),
                "Tickers": group["ticker"].nunique(),
            }
        )

    out = pd.DataFrame(rows)

    if out.empty:
        return out

    order = {
        "Top 10%": 0,
        "Top 20%": 1,
        "Top 30%": 2,
        "Middle 40%": 3,
        "Bottom 20%": 4,
    }

    out["_order"] = out["Rank bucket"].map(order).fillna(99)
    return out.sort_values("_order").drop(columns=["_order"])


def build_v52_cumulative_rank_summary(predictions: pd.DataFrame) -> pd.DataFrame:
    """
    Résumé cumulatif :
    Top 20% = rank >= 80%.
    """
    if predictions is None or predictions.empty:
        return pd.DataFrame()

    required = ["rank_pct_in_fold", "y_true_success", "tb_return", "tb_mfe", "tb_mae", "ticker"]
    if any(col not in predictions.columns for col in required):
        return pd.DataFrame()

    work = predictions.copy()

    for col in ["rank_pct_in_fold", "y_true_success", "tb_return", "tb_mfe", "tb_mae"]:
        work[col] = pd.to_numeric(work[col], errors="coerce")

    work = work.dropna(subset=["rank_pct_in_fold", "y_true_success"])

    if work.empty:
        return pd.DataFrame()

    all_tp = work["y_true_success"].mean()
    all_return = work["tb_return"].mean()

    selections = [
        ("Top 10% cumulative", work["rank_pct_in_fold"] >= 0.90),
        ("Top 20% cumulative", work["rank_pct_in_fold"] >= 0.80),
        ("Top 30% cumulative", work["rank_pct_in_fold"] >= 0.70),
        ("Middle 40%", (work["rank_pct_in_fold"] > 0.30) & (work["rank_pct_in_fold"] < 0.70)),
        ("Bottom 20%", work["rank_pct_in_fold"] <= 0.20),
        ("All OOS", work["rank_pct_in_fold"] >= 0.00),
    ]

    rows = []

    for selection_name, mask in selections:
        group = work.loc[mask].copy()

        if group.empty:
            continue

        rows.append(
            {
                "Selection": selection_name,
                "Count": len(group),
                "Tickers": group["ticker"].nunique(),
                "TP %": group["y_true_success"].mean(),
                "Avg return": group["tb_return"].mean(),
                "Avg MFE": group["tb_mfe"].mean(),
                "Avg MAE": group["tb_mae"].mean(),
                "TP lift vs all": group["y_true_success"].mean() - all_tp,
                "Return lift vs all": group["tb_return"].mean() - all_return,
                "All TP %": all_tp,
                "All avg return": all_return,
            }
        )

    return pd.DataFrame(rows)


def build_v52_ticker_breakdown(predictions: pd.DataFrame) -> pd.DataFrame:
    """
    Analyse Top20 enrichi par ticker.
    """
    if predictions is None or predictions.empty:
        return pd.DataFrame()

    required = ["ticker", "rank_pct_in_fold", "y_true_success", "tb_return", "tb_mfe", "tb_mae"]
    if any(col not in predictions.columns for col in required):
        return pd.DataFrame()

    rows = []

    for ticker_name, group in predictions.groupby("ticker"):
        all_tp = group["y_true_success"].mean()
        all_return = group["tb_return"].mean()

        top20 = group[group["rank_pct_in_fold"] >= 0.80]
        bottom20 = group[group["rank_pct_in_fold"] <= 0.20]

        if top20.empty:
            continue

        bottom20_return = bottom20["tb_return"].mean() if not bottom20.empty else np.nan
        top20_return = top20["tb_return"].mean()

        rows.append(
            {
                "Ticker": ticker_name,
                "OOS obs": len(group),
                "Top20 obs": len(top20),
                "All TP %": all_tp,
                "Top20 TP %": top20["y_true_success"].mean(),
                "Top20 TP lift": top20["y_true_success"].mean() - all_tp,
                "All avg return": all_return,
                "Top20 avg return": top20_return,
                "Top20 return lift": top20_return - all_return,
                "Bottom20 avg return": bottom20_return,
                "Top20 minus Bottom20": (
                    top20_return - bottom20_return
                    if not pd.isna(bottom20_return)
                    else np.nan
                ),
                "Top20 avg MFE": top20["tb_mfe"].mean(),
                "Top20 avg MAE": top20["tb_mae"].mean(),
            }
        )

    out = pd.DataFrame(rows)

    if out.empty:
        return out

    return out.sort_values("Top20 return lift", ascending=False)


def build_v52_ranker_summary(
    fold_results: pd.DataFrame,
    cumulative_summary: pd.DataFrame,
) -> pd.DataFrame:
    """
    Résumé institutionnel V5.2.
    """
    if fold_results is None or fold_results.empty:
        return pd.DataFrame()

    ok = fold_results[fold_results["Status"] == "OK"].copy()

    if ok.empty:
        return pd.DataFrame(
            [
                {
                    "Contrôle": "V5.2 enriched ranker status",
                    "Statut": "KO",
                    "Détail": "Aucun fold modèle exploitable.",
                }
            ]
        )

    avg_auc = ok["AUC"].mean()
    avg_brier_improvement = ok["Brier improvement"].mean()
    avg_top20_lift = ok["Top20 return lift"].mean()
    avg_top20_tp_lift = ok["Top20 TP lift"].mean()
    avg_top20_spread = ok["Top20 minus Bottom20"].mean()

    positive_top20_return_folds = int((ok["Top20 return"] > 0).sum())
    positive_top20_lift_folds = int((ok["Top20 return lift"] > 0).sum())
    positive_spread_folds = int((ok["Top20 minus Bottom20"] > 0).sum())

    if (
        positive_top20_lift_folds >= max(1, len(ok) - 1)
        and positive_spread_folds >= max(1, len(ok) - 1)
        and avg_top20_lift > 0
        and avg_top20_spread > 0
    ):
        rank_status = "Research constructive"
        detail = "Top20 enrichi améliore le return et bat Bottom20 sur la majorité des folds."
    elif positive_top20_lift_folds >= max(1, len(ok) - 1) and avg_top20_lift > 0:
        rank_status = "Watchlist"
        detail = "Top20 enrichi améliore le return, mais séparation Top/Bottom incomplète."
    else:
        rank_status = "Weak"
        detail = "Top20 enrichi ne montre pas assez de robustesse OOS."

    return pd.DataFrame(
        [
            {
                "Contrôle": "V5.2 enriched ranker status",
                "Statut": rank_status,
                "Détail": detail,
            },
            {
                "Contrôle": "Folds modèle OK",
                "Statut": "OK",
                "Détail": f"{len(ok)}/{len(fold_results)} folds.",
            },
            {
                "Contrôle": "Feature count",
                "Statut": "OK" if ok["Feature count"].mean() >= 8 else "À surveiller",
                "Détail": f"{ok['Feature count'].mean():.1f} features utilisées.",
            },
            {
                "Contrôle": "AUC moyen",
                "Statut": "OK" if avg_auc >= 0.55 else "Weak",
                "Détail": "N/A" if pd.isna(avg_auc) else f"{avg_auc:.3f}",
            },
            {
                "Contrôle": "Brier improvement moyen",
                "Statut": "Info",
                "Détail": f"{avg_brier_improvement:.4f}",
            },
            {
                "Contrôle": "Top20 return folds positifs",
                "Statut": "OK" if positive_top20_return_folds >= max(1, len(ok) - 1) else "À surveiller",
                "Détail": f"{positive_top20_return_folds}/{len(ok)} folds.",
            },
            {
                "Contrôle": "Top20 lift folds positifs",
                "Statut": "OK" if positive_top20_lift_folds >= max(1, len(ok) - 1) else "À surveiller",
                "Détail": f"{positive_top20_lift_folds}/{len(ok)} folds.",
            },
            {
                "Contrôle": "Top20 beats Bottom20 folds",
                "Statut": "OK" if positive_spread_folds >= max(1, len(ok) - 1) else "À surveiller",
                "Détail": f"{positive_spread_folds}/{len(ok)} folds.",
            },
            {
                "Contrôle": "Avg Top20 return lift",
                "Statut": "OK" if avg_top20_lift > 0 else "Weak",
                "Détail": _fmt_pct(avg_top20_lift),
            },
            {
                "Contrôle": "Avg Top20 TP lift",
                "Statut": "OK" if avg_top20_tp_lift > 0 else "Weak",
                "Détail": _fmt_pct(avg_top20_tp_lift),
            },
            {
                "Contrôle": "Avg Top20 minus Bottom20",
                "Statut": "OK" if avg_top20_spread > 0 else "Weak",
                "Détail": _fmt_pct(avg_top20_spread),
            },
            {
                "Contrôle": "Probability usage",
                "Statut": "Blocked",
                "Détail": "Probabilités non calibrées. Usage rank-only.",
            },
            {
                "Contrôle": "Decision Engine",
                "Statut": "Blocked",
                "Détail": "Aucune intégration.",
            },
        ]
    )


def build_v52_manifest(
    fold_results: pd.DataFrame,
    cumulative_summary: pd.DataFrame,
    ticker_breakdown: pd.DataFrame,
    feature_usage: pd.DataFrame,
    include_watch: bool = False,
) -> pd.DataFrame:
    """
    Manifest de sécurité V5.2.
    """
    feature_count = len(feature_usage) if feature_usage is not None else 0
    ok_folds = 0
    total_folds = 0

    if fold_results is not None and not fold_results.empty:
        total_folds = len(fold_results)
        ok_folds = int((fold_results["Status"] == "OK").sum())

    top20_return_lift = np.nan
    top20_tp_lift = np.nan

    if cumulative_summary is not None and not cumulative_summary.empty:
        top20 = cumulative_summary[cumulative_summary["Selection"] == "Top 20% cumulative"]

        if not top20.empty:
            top20_return_lift = _safe_float(top20.iloc[0].get("Return lift vs all"), np.nan)
            top20_tp_lift = _safe_float(top20.iloc[0].get("TP lift vs all"), np.nan)

    supportive_tickers = 0
    damaging_tickers = 0

    if ticker_breakdown is not None and not ticker_breakdown.empty:
        supportive_tickers = int(
            (
                (ticker_breakdown["Top20 return lift"] > 0)
                & (ticker_breakdown["Top20 minus Bottom20"] > 0)
            ).sum()
        )
        damaging_tickers = int(
            (
                (ticker_breakdown["Top20 return lift"] < 0)
                | (ticker_breakdown["Top20 minus Bottom20"] <= 0)
            ).sum()
        )

    if (
        ok_folds >= max(1, total_folds - 1)
        and not pd.isna(top20_return_lift)
        and top20_return_lift > 0
        and supportive_tickers >= 2
    ):
        status = "Research constructive"
        detail = "Ranker enrichi positif en recherche, mais non promouvable sans calibration/stabilité."
    elif ok_folds > 0:
        status = "Watchlist / diagnostic"
        detail = "V5.2 exploitable pour diagnostic, pas assez robuste pour promotion."
    else:
        status = "Weak"
        detail = "V5.2 ne fournit pas de ranking enrichi exploitable."

    rows = [
        {
            "Decision item": "V5.2 enriched shortlist ranker",
            "Status": status,
            "Detail": detail,
        },
        {
            "Decision item": "Feature source",
            "Status": "OK" if feature_count >= 5 else "À surveiller",
            "Detail": f"{feature_count} feature(s) utilisées depuis V5.1.1 shortlist uniquement.",
        },
        {
            "Decision item": "Watch features included",
            "Status": "Info",
            "Detail": "Yes" if include_watch else "No",
        },
        {
            "Decision item": "Folds modèle OK",
            "Status": "OK" if ok_folds == total_folds and total_folds > 0 else "À surveiller",
            "Detail": f"{ok_folds}/{total_folds} folds.",
        },
        {
            "Decision item": "Top20 cumulative",
            "Status": "OK" if not pd.isna(top20_return_lift) and top20_return_lift > 0 else "Weak",
            "Detail": (
                "N/A"
                if pd.isna(top20_return_lift)
                else f"TP lift {top20_tp_lift:.2%}, return lift {top20_return_lift:.2%}."
            ),
        },
        {
            "Decision item": "Ticker support",
            "Status": "Info",
            "Detail": f"{supportive_tickers} supportive ticker(s), {damaging_tickers} weak/damaging ticker(s).",
        },
        {
            "Decision item": "Probability usage",
            "Status": "Blocked",
            "Detail": "Les probabilités brutes restent interdites comme probabilités exploitables.",
        },
        {
            "Decision item": "Decision Engine",
            "Status": "Blocked",
            "Detail": "Aucune intégration autorisée.",
        },
        {
            "Decision item": "Next step",
            "Status": "Research only",
            "Detail": "Comparer V4.2 vs V5.2, puis ajouter stabilité régime/calibration fold-aware avant tout modèle promouvable.",
        },
    ]

    return pd.DataFrame(rows)


def render_v52_enriched_shortlist_ranker_panel(
    v50_results: dict,
    v511_results: dict,
    ticker: str,
    panel_interval: str,
    panel_horizon: int,
    panel_pt: float,
    panel_sl: float,
) -> None:
    """
    Render V5.2.
    À appeler après V5.1.1.
    """
    st.divider()
    st.subheader("V5.2 — Enriched Shortlist Ranker")

    st.warning(
        "V5.2 entraîne un ranker enrichi uniquement sur la shortlist V5.1.1. "
        "Research-only : aucune probabilité exploitable, aucun signal, aucune intégration Decision Engine."
    )

    if not isinstance(v50_results, dict) or not v50_results:
        st.info("Lance d'abord V5.0 pour construire le panel enrichi.")
        return

    if not isinstance(v511_results, dict) or not v511_results:
        st.info("Lance d'abord V5.1.1 pour construire la shortlist.")
        return

    enriched_panel_v50 = v50_results.get("enriched_panel", pd.DataFrame())
    shortlist_v511 = v511_results.get("shortlist", pd.DataFrame())

    if enriched_panel_v50 is None or enriched_panel_v50.empty:
        st.info("Panel enrichi V5.0 indisponible.")
        return

    if shortlist_v511 is None or shortlist_v511.empty:
        st.info("Shortlist V5.1.1 indisponible.")
        return

    v52_col1, v52_col2, v52_col3, v52_col4 = st.columns(4)

    v52_model = v52_col1.selectbox(
        "V5.2 model",
        [
            "Logistic strong regularization",
            "Logistic unweighted",
            "Logistic balanced",
        ],
        index=0,
        key=f"ml_v52_model_{ticker}",
    )

    v52_folds = v52_col2.selectbox(
        "V5.2 folds",
        [3, 4, 5, 6],
        index=2,
        key=f"ml_v52_folds_{ticker}",
    )

    v52_embargo = v52_col3.selectbox(
        "V5.2 embargo days",
        [0, 2, 5, 10, 20],
        index=2,
        key=f"ml_v52_embargo_{ticker}",
    )

    v52_min_train = v52_col4.selectbox(
        "V5.2 min train",
        [200, 300, 500, 800],
        index=1,
        key=f"ml_v52_min_train_{ticker}",
    )

    include_watch_v52 = st.checkbox(
        "Inclure aussi les features Shortlist watch",
        value=False,
        key=f"ml_v52_include_watch_{ticker}",
    )

    feature_cols_v52 = get_v52_shortlist_feature_columns(
        shortlist_v511=shortlist_v511,
        enriched_panel_v50=enriched_panel_v50,
        include_watch=bool(include_watch_v52),
    )

    st.caption(
        f"V5.2 feature set : {len(feature_cols_v52)} feature(s) depuis V5.1.1 shortlist uniquement."
    )

    v52_results_key = f"ml_v52_results_cache_{ticker}"

    run_v52 = st.button(
        "Lancer V5.2 enriched shortlist ranker",
        key=f"ml_v52_run_{ticker}",
    )

    if run_v52:
        with st.spinner("V5.2 — entraînement OOS research-only sur shortlist enrichie..."):
            st.session_state[v52_results_key] = run_enriched_shortlist_ranker_v52(
                enriched_panel_v50=enriched_panel_v50,
                shortlist_v511=shortlist_v511,
                n_splits=int(v52_folds),
                embargo_days=int(v52_embargo),
                min_train_size=int(v52_min_train),
                min_test_size=50,
                model_name=str(v52_model),
                include_watch=bool(include_watch_v52),
            )

    v52_results = st.session_state.get(v52_results_key, {})

    if not v52_results:
        st.info("Lance V5.2 pour tester le ranker enrichi sur shortlist.")
        return

    manifest_v52 = v52_results.get("manifest", pd.DataFrame())
    summary_v52 = v52_results.get("summary", pd.DataFrame())
    folds_v52 = v52_results.get("folds", pd.DataFrame())
    bucket_summary_v52 = v52_results.get("bucket_summary", pd.DataFrame())
    cumulative_summary_v52 = v52_results.get("cumulative_summary", pd.DataFrame())
    ticker_breakdown_v52 = v52_results.get("ticker_breakdown", pd.DataFrame())
    feature_usage_v52 = v52_results.get("feature_usage", pd.DataFrame())
    predictions_v52 = v52_results.get("predictions", pd.DataFrame())

    if manifest_v52 is not None and not manifest_v52.empty:
        st.subheader("V5.2 — Research manifest")
        st.dataframe(manifest_v52, width="stretch", hide_index=True)

    if summary_v52 is not None and not summary_v52.empty:
        st.subheader("V5.2 — Ranker summary")
        st.dataframe(summary_v52, width="stretch", hide_index=True)

    if feature_usage_v52 is not None and not feature_usage_v52.empty:
        display_features_v52 = feature_usage_v52.copy()

        if "Missing %" in display_features_v52.columns:
            display_features_v52["Missing %"] = display_features_v52["Missing %"].apply(_fmt_pct)

        st.subheader("V5.2 — Feature usage")
        st.dataframe(display_features_v52, width="stretch", hide_index=True)

    if folds_v52 is not None and not folds_v52.empty:
        display_folds_v52 = folds_v52.copy()

        for col in [
            "Train TP %",
            "Test TP %",
            "AUC",
            "Balanced accuracy",
            "Avg raw p",
            "Realized TP %",
            "Top20 TP %",
            "Top20 TP lift",
            "Top20 return",
            "Top20 return lift",
            "Bottom20 return",
            "Top20 minus Bottom20",
            "All return",
        ]:
            if col in display_folds_v52.columns:
                display_folds_v52[col] = display_folds_v52[col].apply(_fmt_pct)

        for col in ["Brier", "Dummy Brier", "Brier improvement"]:
            if col in display_folds_v52.columns:
                display_folds_v52[col] = display_folds_v52[col].apply(_fmt_num)

        st.subheader("V5.2 — Fold results")
        st.dataframe(display_folds_v52, width="stretch", hide_index=True)

    if bucket_summary_v52 is not None and not bucket_summary_v52.empty:
        display_buckets_v52 = bucket_summary_v52.copy()

        for col in ["TP %", "Avg return", "Avg MFE", "Avg MAE", "Avg raw p"]:
            if col in display_buckets_v52.columns:
                display_buckets_v52[col] = display_buckets_v52[col].apply(_fmt_pct)

        st.subheader("V5.2 — Rank band summary")
        st.caption(
            "Bandes non cumulatives : Top 20% correspond à la bande 80–90%. "
            "La sélection cumulative est affichée juste après."
        )
        st.dataframe(display_buckets_v52, width="stretch", hide_index=True)

    if cumulative_summary_v52 is not None and not cumulative_summary_v52.empty:
        display_cumulative_v52 = cumulative_summary_v52.copy()

        for col in [
            "TP %",
            "Avg return",
            "Avg MFE",
            "Avg MAE",
            "TP lift vs all",
            "Return lift vs all",
            "All TP %",
            "All avg return",
        ]:
            if col in display_cumulative_v52.columns:
                display_cumulative_v52[col] = display_cumulative_v52[col].apply(_fmt_pct)

        st.subheader("V5.2 — Cumulative rank selection summary")
        st.dataframe(display_cumulative_v52, width="stretch", hide_index=True)

    if ticker_breakdown_v52 is not None and not ticker_breakdown_v52.empty:
        display_ticker_v52 = ticker_breakdown_v52.copy()

        for col in [
            "All TP %",
            "Top20 TP %",
            "Top20 TP lift",
            "All avg return",
            "Top20 avg return",
            "Top20 return lift",
            "Bottom20 avg return",
            "Top20 minus Bottom20",
            "Top20 avg MFE",
            "Top20 avg MAE",
        ]:
            if col in display_ticker_v52.columns:
                display_ticker_v52[col] = display_ticker_v52[col].apply(_fmt_pct)

        st.subheader("V5.2 — Ticker Top20 breakdown")
        st.dataframe(display_ticker_v52, width="stretch", hide_index=True)

    if predictions_v52 is not None and not predictions_v52.empty:
        preview_v52 = predictions_v52.tail(200).copy()

        if "date" in preview_v52.columns:
            preview_v52["date"] = pd.to_datetime(
                preview_v52["date"],
                errors="coerce",
            ).dt.strftime("%Y-%m-%d")

        for col in ["tb_return", "tb_mfe", "tb_mae", "p_raw", "p_dummy", "rank_pct_in_fold"]:
            if col in preview_v52.columns:
                preview_v52[col] = preview_v52[col].apply(_fmt_pct)

        st.subheader("V5.2 — OOS prediction preview")
        st.dataframe(preview_v52, width="stretch", hide_index=True)

        csv_v52 = predictions_v52.to_csv(index=False).encode("utf-8")

        st.download_button(
            label="Télécharger predictions V5.2 CSV",
            data=csv_v52,
            file_name=f"ml_v52_predictions_{panel_interval}_{panel_horizon}d.csv",
            mime="text/csv",
            key=f"ml_v52_predictions_download_{ticker}",
        )

    st.info(
        "V5.2 reste shadow/research-only. Même si le ranking s'améliore, aucune probabilité "
        "et aucun signal ne sont validés."
    )



# ============================================================
# V5.3 → V6.3 — INSTITUTIONAL ML CONTINUATION SUITE
# ============================================================
# Read-only / research-only continuation after V5.2.
# No probability promotion. No BUY/SELL signal. No Decision Engine integration.


def _ml_next_required_columns(df: pd.DataFrame, required: list[str]) -> bool:
    if df is None or df.empty:
        return False
    return all(col in df.columns for col in required)


def _ml_next_block_name(feature: str) -> str:
    """Classify feature into a conservative research block."""
    f = str(feature).lower()

    if f.startswith("rs_") or "relative" in f or "momentum" in f or "composite" in f:
        return "Relative strength"
    if f.startswith("liq_") or "liquidity" in f or "volume" in f or "dollar" in f or "turnover" in f:
        return "Liquidity / volume"
    if f.startswith("risk_") or "gap" in f or "drawdown" in f or "atr" in f or "range" in f or "mae" in f or "mfe" in f:
        return "Path risk / gap risk"
    if f.startswith("int_") or "interaction" in f or "regime" in f:
        return "Regime interactions"
    if (
        "return_" in f
        or "vol_" in f
        or "rsi" in f
        or "price_vs" in f
        or "breakout" in f
        or "breakdown" in f
    ):
        return "Baseline technical"
    return "Other enriched"


def _ml_next_rank_bucket_from_pct(rank_pct: float) -> str:
    rank_pct = _safe_float(rank_pct, 0) or 0
    if rank_pct >= 0.90:
        return "Top 10%"
    if rank_pct >= 0.80:
        return "Top 20%"
    if rank_pct >= 0.70:
        return "Top 30%"
    if rank_pct <= 0.20:
        return "Bottom 20%"
    return "Middle 40%"


def _ml_next_select_top_mask(df: pd.DataFrame, selection: str) -> pd.Series:
    if df is None or df.empty or "rank_pct_in_fold" not in df.columns:
        return pd.Series(False, index=df.index if df is not None else None)

    r = pd.to_numeric(df["rank_pct_in_fold"], errors="coerce")

    if selection in ["Top 10%", "Top 10"]:
        return r >= 0.90
    if selection in ["Top 20%", "Top 20"]:
        return r >= 0.80
    if selection in ["Top 30%", "Top 30"]:
        return r >= 0.70
    if selection in ["Bottom 20%", "Bottom 20"]:
        return r <= 0.20
    if selection in ["Middle 40%", "Middle"]:
        return (r > 0.30) & (r < 0.70)
    return r >= 0.00


def _ml_next_feature_cols_from_shortlist(
    enriched_panel_v50: pd.DataFrame,
    shortlist_v511: pd.DataFrame,
    include_watch: bool = False,
) -> list[str]:
    try:
        return get_v52_shortlist_feature_columns(
            shortlist_v511=shortlist_v511,
            enriched_panel_v50=enriched_panel_v50,
            include_watch=include_watch,
        )
    except Exception:
        return []


def _ml_next_make_research_model(model_name: str):
    """Model factory for research-only benchmark. Optional families are imported lazily."""
    if model_name in [
        "Logistic strong regularization",
        "Logistic unweighted",
        "Logistic balanced",
    ]:
        return _make_cross_sectional_ranker_v42(model_name)

    if model_name == "Logistic very strong regularization":
        model = LogisticRegression(
            max_iter=1000,
            class_weight=None,
            solver="liblinear",
            C=0.03,
            random_state=42,
        )
        return Pipeline(
            steps=[
                ("imputer", SimpleImputer(strategy="median")),
                ("scaler", StandardScaler()),
                ("model", model),
            ]
        )

    if model_name == "Random forest shallow":
        try:
            from sklearn.ensemble import RandomForestClassifier
        except Exception:
            return None
        model = RandomForestClassifier(
            n_estimators=30,
            max_depth=2,
            min_samples_leaf=25,
            max_features="sqrt",
            random_state=42,
            n_jobs=1,
            class_weight=None,
        )
        return Pipeline(
            steps=[
                ("imputer", SimpleImputer(strategy="median")),
                ("model", model),
            ]
        )

    if model_name == "HistGradientBoosting shallow":
        try:
            from sklearn.ensemble import HistGradientBoostingClassifier
        except Exception:
            return None
        model = HistGradientBoostingClassifier(
            max_iter=30,
            max_leaf_nodes=5,
            learning_rate=0.05,
            l2_regularization=1.0,
            min_samples_leaf=30,
            random_state=42,
        )
        return Pipeline(
            steps=[
                ("imputer", SimpleImputer(strategy="median")),
                ("model", model),
            ]
        )

    return _make_cross_sectional_ranker_v42("Logistic strong regularization")


def _ml_next_prepare_dataset_with_features(
    enriched_panel_v50: pd.DataFrame,
    feature_cols: list[str],
) -> tuple[pd.DataFrame, pd.Series, pd.DataFrame]:
    """Prepare X/y/meta with explicit feature columns."""
    if enriched_panel_v50 is None or enriched_panel_v50.empty or not feature_cols:
        return pd.DataFrame(), pd.Series(dtype=int), pd.DataFrame()

    work = _ensure_panel_event_dates_v41(enriched_panel_v50)
    if work.empty:
        return pd.DataFrame(), pd.Series(dtype=int), pd.DataFrame()

    required = ["ticker", "date", "tb_label", "tb_event_start", "tb_event_end"]
    if any(col not in work.columns for col in required):
        return pd.DataFrame(), pd.Series(dtype=int), pd.DataFrame()

    clean_features = []
    for col in feature_cols:
        if col not in work.columns:
            continue
        if str(col).startswith(("tb_", "forward_return_", "target_", "label_", "research_")):
            continue
        if not pd.api.types.is_numeric_dtype(work[col]):
            continue
        clean_features.append(col)

    clean_features = list(dict.fromkeys(clean_features))
    if not clean_features:
        return pd.DataFrame(), pd.Series(dtype=int), pd.DataFrame()

    valid = work.dropna(subset=required).copy()
    valid["date"] = pd.to_datetime(valid["date"], errors="coerce")
    valid["tb_event_start"] = pd.to_datetime(valid["tb_event_start"], errors="coerce")
    valid["tb_event_end"] = pd.to_datetime(valid["tb_event_end"], errors="coerce")
    valid = valid.dropna(subset=["date", "tb_event_start", "tb_event_end"])

    if valid.empty:
        return pd.DataFrame(), pd.Series(dtype=int), pd.DataFrame()

    X = valid[clean_features].copy().replace([np.inf, -np.inf], np.nan)
    y = (valid["tb_label"].astype(float) == 1.0).astype(int)

    meta_cols = [
        "ticker",
        "date",
        "tb_label",
        "tb_event",
        "tb_event_start",
        "tb_event_end",
        "tb_return",
        "tb_mfe",
        "tb_mae",
        "tb_holding_days",
    ]
    meta_cols = [col for col in meta_cols if col in valid.columns]
    meta = valid[meta_cols].copy()

    return X, y, meta


def run_research_ranker_with_feature_cols_vnext(
    enriched_panel_v50: pd.DataFrame,
    feature_cols: list[str],
    model_name: str = "Logistic strong regularization",
    n_splits: int = 5,
    embargo_days: int = 5,
    min_train_size: int = 300,
    min_test_size: int = 50,
    run_label: str = "Research ranker",
) -> dict:
    """
    Generic purged cross-sectional OOS ranker.
    Used by V5.4, V5.5, V5.6 and V5.9.
    """
    empty = {
        "label": run_label,
        "folds": pd.DataFrame(),
        "predictions": pd.DataFrame(),
        "cumulative_summary": pd.DataFrame(),
        "ticker_breakdown": pd.DataFrame(),
        "summary": pd.DataFrame(),
    }

    if not SKLEARN_AVAILABLE:
        return empty

    X, y, meta = _ml_next_prepare_dataset_with_features(enriched_panel_v50, feature_cols)
    if X.empty or y.empty or meta.empty:
        return empty

    valid = pd.concat([meta.reset_index(drop=True), X.reset_index(drop=True)], axis=1)
    valid["_y_success"] = y.values
    valid["date"] = pd.to_datetime(valid["date"], errors="coerce")
    valid["tb_event_start"] = pd.to_datetime(valid["tb_event_start"], errors="coerce")
    valid["tb_event_end"] = pd.to_datetime(valid["tb_event_end"], errors="coerce")
    valid = valid.dropna(subset=["ticker", "date", "tb_event_start", "tb_event_end", "_y_success"])
    valid = valid.sort_values(["tb_event_start", "ticker"]).reset_index(drop=True)

    if valid.empty or len(valid) < min_train_size + min_test_size:
        return empty

    feature_cols = list(X.columns)
    unique_dates = np.array(sorted(valid["tb_event_start"].dropna().unique()))
    if len(unique_dates) < n_splits + 20:
        return empty

    initial_train_dates = max(60, int(len(unique_dates) * 0.35))
    test_dates = unique_dates[initial_train_dates:]
    if len(test_dates) < n_splits:
        return empty

    date_chunks = np.array_split(test_dates, n_splits)
    embargo_delta = pd.Timedelta(days=int(embargo_days))

    fold_rows = []
    pred_rows = []

    for fold_id, chunk in enumerate(date_chunks, start=1):
        if len(chunk) == 0:
            continue

        test_start = pd.to_datetime(chunk[0])
        test_end = pd.to_datetime(chunk[-1])

        test_mask = (valid["tb_event_start"] >= test_start) & (valid["tb_event_start"] <= test_end)
        embargo_cutoff = test_start - embargo_delta
        train_mask = (valid["tb_event_start"] < test_start) & (valid["tb_event_end"] < embargo_cutoff)

        train = valid.loc[train_mask].copy()
        test = valid.loc[test_mask].copy()

        status = "OK"
        if len(train) < min_train_size:
            status = "Skipped - train too small"
        if len(test) < min_test_size:
            status = "Skipped - test too small"
        if train["ticker"].nunique() < 3 or test["ticker"].nunique() < 1:
            status = "Skipped - ticker coverage weak"
        if not train.empty and train["_y_success"].nunique() < 2:
            status = "Skipped - train single class"

        if status != "OK":
            fold_rows.append(
                {
                    "Fold": fold_id,
                    "Status": status,
                    "Run label": run_label,
                    "Model": model_name,
                    "Train size": len(train),
                    "Test size": len(test),
                    "Train tickers": train["ticker"].nunique() if not train.empty else 0,
                    "Test tickers": test["ticker"].nunique() if not test.empty else 0,
                    "Feature count": len(feature_cols),
                }
            )
            continue

        try:
            model = _ml_next_make_research_model(model_name)
            if model is None:
                fold_rows.append(
                    {
                        "Fold": fold_id,
                        "Status": "Skipped - model unavailable",
                        "Run label": run_label,
                        "Model": model_name,
                        "Train size": len(train),
                        "Test size": len(test),
                        "Feature count": len(feature_cols),
                    }
                )
                continue

            dummy = Pipeline(
                steps=[
                    ("imputer", SimpleImputer(strategy="median")),
                    ("model", DummyClassifier(strategy="prior")),
                ]
            )

            X_train = train[feature_cols].copy()
            y_train = train["_y_success"].astype(int)
            X_test = test[feature_cols].copy()
            y_test = test["_y_success"].astype(int)

            model.fit(X_train, y_train)
            dummy.fit(X_train, y_train)

            if not hasattr(model, "predict_proba"):
                continue

            proba = model.predict_proba(X_test)[:, 1]
            dummy_proba = dummy.predict_proba(X_test)[:, 1]

            metrics = _classification_metrics_v30(y_test, proba, threshold=0.50)
            dummy_metrics = _classification_metrics_v30(y_test, dummy_proba, threshold=0.50)

            ranked_test = test[
                [
                    "ticker",
                    "date",
                    "tb_label",
                    "tb_event",
                    "tb_return",
                    "tb_mfe",
                    "tb_mae",
                    "tb_holding_days",
                ]
            ].copy()
            ranked_test["Fold"] = fold_id
            ranked_test["Model"] = model_name
            ranked_test["Run label"] = run_label
            ranked_test["Feature count"] = len(feature_cols)
            ranked_test["y_true_success"] = y_test.values
            ranked_test["p_raw"] = proba
            ranked_test["p_dummy"] = dummy_proba
            ranked_test["rank_pct_in_fold"] = pd.Series(proba).rank(method="average", pct=True).values
            ranked_test["rank_bucket"] = ranked_test["rank_pct_in_fold"].apply(_ml_next_rank_bucket_from_pct)
            pred_rows.append(ranked_test)

            top20 = ranked_test[ranked_test["rank_pct_in_fold"] >= 0.80]
            bottom20 = ranked_test[ranked_test["rank_pct_in_fold"] <= 0.20]
            all_tp = ranked_test["y_true_success"].mean()
            all_return = ranked_test["tb_return"].mean()
            top20_tp = top20["y_true_success"].mean() if not top20.empty else np.nan
            top20_return = top20["tb_return"].mean() if not top20.empty else np.nan
            bottom20_return = bottom20["tb_return"].mean() if not bottom20.empty else np.nan

            fold_rows.append(
                {
                    "Fold": fold_id,
                    "Status": "OK",
                    "Run label": run_label,
                    "Model": model_name,
                    "Train size": len(train),
                    "Test size": len(test),
                    "Train tickers": train["ticker"].nunique(),
                    "Test tickers": test["ticker"].nunique(),
                    "Feature count": len(feature_cols),
                    "Train TP %": y_train.mean(),
                    "Test TP %": y_test.mean(),
                    "AUC": metrics["ROC AUC"],
                    "Balanced accuracy": metrics["Balanced accuracy"],
                    "Brier": metrics["Brier score"],
                    "Dummy Brier": dummy_metrics["Brier score"],
                    "Brier improvement": dummy_metrics["Brier score"] - metrics["Brier score"],
                    "Avg raw p": metrics["Avg predicted TP %"],
                    "Realized TP %": metrics["Realized TP %"],
                    "Top20 count": len(top20),
                    "Top20 TP %": top20_tp,
                    "Top20 TP lift": top20_tp - all_tp if not pd.isna(top20_tp) else np.nan,
                    "Top20 return": top20_return,
                    "Top20 return lift": top20_return - all_return if not pd.isna(top20_return) else np.nan,
                    "Bottom20 return": bottom20_return,
                    "Top20 minus Bottom20": (
                        top20_return - bottom20_return
                        if not pd.isna(top20_return) and not pd.isna(bottom20_return)
                        else np.nan
                    ),
                    "All return": all_return,
                }
            )

        except Exception as e:
            fold_rows.append(
                {
                    "Fold": fold_id,
                    "Status": f"Error: {str(e)[:100]}",
                    "Run label": run_label,
                    "Model": model_name,
                    "Train size": len(train),
                    "Test size": len(test),
                    "Feature count": len(feature_cols),
                }
            )

    folds = pd.DataFrame(fold_rows)
    predictions = pd.concat(pred_rows, ignore_index=True) if pred_rows else pd.DataFrame()
    cumulative = build_v52_cumulative_rank_summary(predictions)
    ticker_breakdown = build_v52_ticker_breakdown(predictions)
    summary = build_v52_ranker_summary(folds, cumulative)

    return {
        "label": run_label,
        "folds": folds,
        "predictions": predictions,
        "cumulative_summary": cumulative,
        "ticker_breakdown": ticker_breakdown,
        "summary": summary,
    }


def build_v53_enriched_failure_attribution(v52_results: dict) -> dict:
    """V5.3 — Failure attribution for V5.2 enriched ranker."""
    folds = v52_results.get("folds", pd.DataFrame()) if isinstance(v52_results, dict) else pd.DataFrame()
    predictions = v52_results.get("predictions", pd.DataFrame()) if isinstance(v52_results, dict) else pd.DataFrame()
    cumulative = v52_results.get("cumulative_summary", pd.DataFrame()) if isinstance(v52_results, dict) else pd.DataFrame()
    ticker_breakdown = v52_results.get("ticker_breakdown", pd.DataFrame()) if isinstance(v52_results, dict) else pd.DataFrame()
    feature_usage = v52_results.get("feature_usage", pd.DataFrame()) if isinstance(v52_results, dict) else pd.DataFrame()

    manifest_rows = []
    fold_diag = pd.DataFrame()
    ticker_diag = pd.DataFrame()
    feature_diag = pd.DataFrame()

    if folds is not None and not folds.empty:
        ok = folds[folds["Status"] == "OK"].copy()
        if not ok.empty:
            fold_diag = ok.copy()
            fold_diag["Failure driver"] = np.select(
                [
                    pd.to_numeric(ok.get("Top20 return lift"), errors="coerce") <= 0,
                    pd.to_numeric(ok.get("Top20 minus Bottom20"), errors="coerce") <= 0,
                    pd.to_numeric(ok.get("AUC"), errors="coerce") < 0.55,
                    pd.to_numeric(ok.get("Brier improvement"), errors="coerce") <= 0,
                ],
                [
                    "Top20 return lift <= 0",
                    "Top20 does not beat Bottom20",
                    "AUC weak",
                    "Brier not better than dummy",
                ],
                default="No critical fold failure",
            )
            weak_folds = int((fold_diag["Failure driver"] != "No critical fold failure").sum())
            manifest_rows.append(
                {
                    "Decision item": "V5.3 fold attribution",
                    "Status": "Weak" if weak_folds > 0 else "OK",
                    "Detail": f"{weak_folds}/{len(ok)} OK folds carry a failure flag.",
                }
            )

    if ticker_breakdown is not None and not ticker_breakdown.empty:
        ticker_diag = ticker_breakdown.copy()
        ticker_diag["Ticker failure role"] = np.select(
            [
                pd.to_numeric(ticker_diag.get("Top20 obs"), errors="coerce") < 15,
                pd.to_numeric(ticker_diag.get("Top20 return lift"), errors="coerce") <= 0,
                pd.to_numeric(ticker_diag.get("Top20 minus Bottom20"), errors="coerce") <= 0,
                pd.to_numeric(ticker_diag.get("Top20 TP lift"), errors="coerce") <= 0,
            ],
            [
                "Small Top20 sample",
                "Return lift failure",
                "Top/Bottom spread failure",
                "Hit-rate lift failure",
            ],
            default="Supportive / neutral",
        )
        damaging = int((ticker_diag["Ticker failure role"] != "Supportive / neutral").sum())
        manifest_rows.append(
            {
                "Decision item": "V5.3 ticker attribution",
                "Status": "Research path" if damaging < len(ticker_diag) else "Weak",
                "Detail": f"{damaging}/{len(ticker_diag)} tickers have a failure flag.",
            }
        )

    if feature_usage is not None and not feature_usage.empty:
        feature_diag = feature_usage.copy()
        feature_diag["Feature block"] = feature_diag["Feature"].astype(str).apply(_ml_next_block_name)
        block_cov = (
            feature_diag.groupby("Feature block", as_index=False)
            .agg(
                Features=("Feature", "count"),
                Avg_missing=("Missing %", "mean"),
                Min_unique=("Unique values", "min"),
            )
            .sort_values(["Features", "Avg_missing"], ascending=[False, True])
        )
        manifest_rows.append(
            {
                "Decision item": "V5.3 feature block coverage",
                "Status": "Info",
                "Detail": f"{len(block_cov)} feature blocks detected in V5.2 feature usage.",
            }
        )
    else:
        block_cov = pd.DataFrame()

    top20_return_lift = np.nan
    if cumulative is not None and not cumulative.empty:
        top20 = cumulative[cumulative["Selection"] == "Top 20% cumulative"]
        if not top20.empty:
            top20_return_lift = _safe_float(top20.iloc[0].get("Return lift vs all"), np.nan)

    if pd.isna(top20_return_lift) or top20_return_lift <= 0:
        next_step = "Run V5.4 ablation and V5.5 rescue before any advanced model."
    else:
        next_step = "Validate whether the positive Top20 is stable by block, ticker, regime and horizon."

    manifest_rows.extend(
        [
            {
                "Decision item": "V5.3 global failure attribution",
                "Status": "Research-only",
                "Detail": "Attribution only. No model promotion, no probability, no Decision Engine.",
            },
            {
                "Decision item": "Next step",
                "Status": "Research only",
                "Detail": next_step,
            },
        ]
    )

    return {
        "manifest": pd.DataFrame(manifest_rows),
        "fold_diagnostics": fold_diag,
        "ticker_diagnostics": ticker_diag,
        "feature_block_coverage": block_cov,
        "feature_diagnostics": feature_diag,
    }


def run_v54_feature_block_ablation(
    enriched_panel_v50: pd.DataFrame,
    shortlist_v511: pd.DataFrame,
    n_splits: int = 5,
    embargo_days: int = 5,
    min_train_size: int = 300,
    min_test_size: int = 50,
    model_name: str = "Logistic strong regularization",
    include_watch: bool = False,
) -> dict:
    """V5.4 — Conservative feature block ablation."""
    all_features = _ml_next_feature_cols_from_shortlist(enriched_panel_v50, shortlist_v511, include_watch=include_watch)
    if not all_features:
        return {"manifest": pd.DataFrame(), "runs": {}, "comparison": pd.DataFrame()}

    blocks = {}
    for feature in all_features:
        blocks.setdefault(_ml_next_block_name(feature), []).append(feature)

    baseline = blocks.get("Baseline technical", [])
    ordered_specs = []

    for block_name, cols in sorted(blocks.items()):
        ordered_specs.append((block_name, cols))

    if baseline:
        for block_name, cols in sorted(blocks.items()):
            if block_name == "Baseline technical":
                continue
            combo = list(dict.fromkeys(baseline + cols))
            ordered_specs.append((f"Baseline + {block_name}", combo))

    ordered_specs.append(("All V5.1.1 shortlisted features", all_features))

    runs = {}
    comparison_rows = []

    for label, cols in ordered_specs:
        cols = list(dict.fromkeys([c for c in cols if c in enriched_panel_v50.columns]))
        if len(cols) < 2:
            comparison_rows.append(
                {
                    "Feature block": label,
                    "Status": "Skipped",
                    "Feature count": len(cols),
                    "Detail": "Moins de 2 features exploitables.",
                }
            )
            continue

        result = run_research_ranker_with_feature_cols_vnext(
            enriched_panel_v50=enriched_panel_v50,
            feature_cols=cols,
            model_name=model_name,
            n_splits=n_splits,
            embargo_days=embargo_days,
            min_train_size=min_train_size,
            min_test_size=min_test_size,
            run_label=f"V5.4 {label}",
        )
        runs[label] = result
        folds = result.get("folds", pd.DataFrame())
        ok = folds[folds["Status"] == "OK"].copy() if folds is not None and not folds.empty else pd.DataFrame()

        if ok.empty:
            comparison_rows.append(
                {
                    "Feature block": label,
                    "Status": "No valid fold",
                    "Feature count": len(cols),
                    "Folds OK": 0,
                    "Avg AUC": np.nan,
                    "Avg Top20 TP lift": np.nan,
                    "Avg Top20 return lift": np.nan,
                    "Avg Top20 spread": np.nan,
                    "Positive return folds": 0,
                    "Positive spread folds": 0,
                    "Detail": "Aucun fold OOS exploitable.",
                }
            )
            continue

        avg_auc = ok["AUC"].mean()
        avg_tp_lift = ok["Top20 TP lift"].mean()
        avg_ret_lift = ok["Top20 return lift"].mean()
        avg_spread = ok["Top20 minus Bottom20"].mean()
        pos_ret = int((ok["Top20 return lift"] > 0).sum())
        pos_spread = int((ok["Top20 minus Bottom20"] > 0).sum())

        if avg_ret_lift > 0 and avg_spread > 0 and pos_ret >= max(1, len(ok) - 1):
            status = "Constructive block"
            detail = "Return lift et séparation Top/Bottom constructifs."
        elif avg_ret_lift > 0 or avg_tp_lift > 0.05:
            status = "Watch block"
            detail = "Signal partiel, à ne pas promouvoir."
        else:
            status = "Weak block"
            detail = "Bloc non robuste en OOS."

        comparison_rows.append(
            {
                "Feature block": label,
                "Status": status,
                "Feature count": len(cols),
                "Folds OK": len(ok),
                "Avg AUC": avg_auc,
                "Avg Top20 TP lift": avg_tp_lift,
                "Avg Top20 return lift": avg_ret_lift,
                "Avg Top20 spread": avg_spread,
                "Positive return folds": pos_ret,
                "Positive spread folds": pos_spread,
                "Detail": detail,
            }
        )

    comparison = pd.DataFrame(comparison_rows)
    if not comparison.empty:
        comparison = comparison.sort_values(
            ["Status", "Avg Top20 return lift", "Avg Top20 spread"],
            ascending=[True, False, False],
        )

    constructive = int((comparison["Status"] == "Constructive block").sum()) if not comparison.empty else 0
    weak = int((comparison["Status"] == "Weak block").sum()) if not comparison.empty else 0

    manifest = pd.DataFrame(
        [
            {
                "Decision item": "V5.4 ablation scope",
                "Status": "Research-only",
                "Detail": f"{len(comparison)} block tests executed/skipped. No integration.",
            },
            {
                "Decision item": "Constructive blocks",
                "Status": "OK" if constructive > 0 else "Weak",
                "Detail": f"{constructive} constructive block(s).",
            },
            {
                "Decision item": "Weak blocks",
                "Status": "Info",
                "Detail": f"{weak} weak block(s).",
            },
            {
                "Decision item": "Decision Engine",
                "Status": "Blocked",
                "Detail": "Aucune intégration.",
            },
        ]
    )

    return {"manifest": manifest, "runs": runs, "comparison": comparison}


def run_v55_feature_rescue_shortlist(
    enriched_panel_v50: pd.DataFrame,
    shortlist_v511: pd.DataFrame,
    ablation_v54: dict,
    include_watch: bool = False,
) -> dict:
    """V5.5 — Build a rescued shortlist from V5.4 block evidence."""
    base_features = _ml_next_feature_cols_from_shortlist(enriched_panel_v50, shortlist_v511, include_watch=include_watch)
    if not base_features:
        return {"manifest": pd.DataFrame(), "rescue_shortlist": pd.DataFrame(), "block_policy": pd.DataFrame()}

    comparison = ablation_v54.get("comparison", pd.DataFrame()) if isinstance(ablation_v54, dict) else pd.DataFrame()
    block_status = {}
    if comparison is not None and not comparison.empty:
        for _, row in comparison.iterrows():
            name = str(row.get("Feature block"))
            status = str(row.get("Status"))
            if name.startswith("Baseline +") or name.startswith("All "):
                continue
            block_status[name] = status

    rows = []
    for feature in base_features:
        block = _ml_next_block_name(feature)
        status = block_status.get(block, "No ablation evidence")

        missing = float(enriched_panel_v50[feature].isna().mean()) if feature in enriched_panel_v50.columns else np.nan
        unique = int(enriched_panel_v50[feature].nunique(dropna=True)) if feature in enriched_panel_v50.columns else 0

        if missing > 0.35 or unique < 5:
            role = "Rescue blocked"
            reason = "Missing/unique guard failed."
        elif status == "Constructive block":
            role = "Rescue keep"
            reason = "Feature belongs to constructive V5.4 block."
        elif status == "Watch block":
            role = "Rescue watch"
            reason = "Feature belongs to watch V5.4 block."
        elif status == "Weak block":
            role = "Rescue reject"
            reason = "Feature belongs to weak V5.4 block."
        else:
            role = "Rescue watch"
            reason = "No direct block evidence; keep as watch only."

        rows.append(
            {
                "Feature": feature,
                "Feature block": block,
                "V5.5 rescue role": role,
                "Missing %": missing,
                "Unique values": unique,
                "Reason": reason,
                "V5.1.1 shortlist role": "Shortlist keep" if role == "Rescue keep" else "Shortlist watch",
            }
        )

    rescue = pd.DataFrame(rows)
    keep = int((rescue["V5.5 rescue role"] == "Rescue keep").sum()) if not rescue.empty else 0
    watch = int((rescue["V5.5 rescue role"] == "Rescue watch").sum()) if not rescue.empty else 0
    reject = int((rescue["V5.5 rescue role"].isin(["Rescue reject", "Rescue blocked"])).sum()) if not rescue.empty else 0

    block_policy = pd.DataFrame(
        [
            {"Feature block": k, "V5.4 status": v, "V5.5 policy": "Keep" if v == "Constructive block" else "Watch" if v == "Watch block" else "Reject"}
            for k, v in block_status.items()
        ]
    )

    manifest = pd.DataFrame(
        [
            {
                "Decision item": "V5.5 rescue shortlist",
                "Status": "Research-only",
                "Detail": f"{keep} keep, {watch} watch, {reject} reject/blocked features.",
            },
            {
                "Decision item": "Promotion",
                "Status": "Blocked",
                "Detail": "La shortlist rescue ne promeut aucun modèle. Elle prépare uniquement V5.6/V5.9.",
            },
            {
                "Decision item": "Decision Engine",
                "Status": "Blocked",
                "Detail": "Aucune intégration.",
            },
        ]
    )

    return {"manifest": manifest, "rescue_shortlist": rescue, "block_policy": block_policy}


def run_v56_ticker_gated_enriched_ranker(
    enriched_panel_v50: pd.DataFrame,
    rescue_v55: dict,
    v52_results: dict,
    n_splits: int = 5,
    embargo_days: int = 5,
    min_train_size: int = 300,
    min_test_size: int = 50,
    model_name: str = "Logistic strong regularization",
) -> dict:
    """V5.6 — Ticker-gated enriched ranker using only supportive tickers and rescued features."""
    rescue = rescue_v55.get("rescue_shortlist", pd.DataFrame()) if isinstance(rescue_v55, dict) else pd.DataFrame()
    v52_ticker = v52_results.get("ticker_breakdown", pd.DataFrame()) if isinstance(v52_results, dict) else pd.DataFrame()

    if rescue is None or rescue.empty:
        return {"manifest": pd.DataFrame(), "ticker_gate": pd.DataFrame(), "result": {}}

    if v52_ticker is None or v52_ticker.empty:
        return {"manifest": pd.DataFrame(), "ticker_gate": pd.DataFrame(), "result": {}}

    gate_rows = []
    for _, row in v52_ticker.iterrows():
        ticker_name = str(row.get("Ticker"))
        top20_obs = int(_safe_float(row.get("Top20 obs"), 0) or 0)
        tp_lift = _safe_float(row.get("Top20 TP lift"), 0) or 0
        ret_lift = _safe_float(row.get("Top20 return lift"), 0) or 0
        spread = _safe_float(row.get("Top20 minus Bottom20"), np.nan)
        top_ret = _safe_float(row.get("Top20 avg return"), 0) or 0

        if top20_obs < 15:
            gate = "Small sample"
        elif tp_lift > 0.05 and ret_lift > 0 and top_ret > 0 and not pd.isna(spread) and spread > 0:
            gate = "Strict supportive"
        elif ret_lift > 0 and top_ret > 0:
            gate = "Watchlist"
        elif ret_lift < 0 or (not pd.isna(spread) and spread <= 0):
            gate = "Rejected"
        else:
            gate = "Neutral"

        gate_rows.append(
            {
                "Ticker": ticker_name,
                "Ticker gate": gate,
                "Top20 obs": top20_obs,
                "Top20 TP lift": tp_lift,
                "Top20 return lift": ret_lift,
                "Top20 minus Bottom20": spread,
                "Top20 avg return": top_ret,
            }
        )

    ticker_gate = pd.DataFrame(gate_rows)
    strict_tickers = ticker_gate.loc[ticker_gate["Ticker gate"] == "Strict supportive", "Ticker"].astype(str).tolist()

    feature_cols = rescue.loc[rescue["V5.5 rescue role"].isin(["Rescue keep", "Rescue watch"]), "Feature"].astype(str).tolist()

    gated_panel = pd.DataFrame()
    result = {}
    if strict_tickers and feature_cols:
        gated_panel = enriched_panel_v50[enriched_panel_v50["ticker"].astype(str).isin(strict_tickers)].copy()
        result = run_research_ranker_with_feature_cols_vnext(
            enriched_panel_v50=gated_panel,
            feature_cols=feature_cols,
            model_name=model_name,
            n_splits=n_splits,
            embargo_days=embargo_days,
            min_train_size=max(80, min_train_size // 3),
            min_test_size=max(15, min_test_size // 3),
            run_label="V5.6 ticker-gated enriched ranker",
        )

    folds = result.get("folds", pd.DataFrame()) if isinstance(result, dict) else pd.DataFrame()
    ok = folds[folds["Status"] == "OK"].copy() if folds is not None and not folds.empty else pd.DataFrame()
    avg_lift = ok["Top20 return lift"].mean() if not ok.empty and "Top20 return lift" in ok.columns else np.nan

    if not strict_tickers:
        status = "Rejected"
        detail = "No strict supportive ticker from V5.2 diagnostics."
    elif ok.empty:
        status = "No valid OOS fold"
        detail = f"Strict tickers: {', '.join(strict_tickers)}."
    elif avg_lift > 0:
        status = "Ticker-gated constructive"
        detail = f"Strict tickers: {', '.join(strict_tickers)}; avg Top20 return lift {_fmt_pct(avg_lift)}."
    else:
        status = "Ticker-gated weak"
        detail = f"Strict tickers: {', '.join(strict_tickers)}; avg Top20 return lift {_fmt_pct(avg_lift)}."

    manifest = pd.DataFrame(
        [
            {"Decision item": "V5.6 ticker gate", "Status": status, "Detail": detail},
            {"Decision item": "Strict tickers", "Status": "Info", "Detail": ", ".join(strict_tickers) if strict_tickers else "None"},
            {"Decision item": "Probability", "Status": "Blocked", "Detail": "Raw probabilities remain blocked."},
            {"Decision item": "Decision Engine", "Status": "Blocked", "Detail": "Aucune intégration."},
        ]
    )

    return {"manifest": manifest, "ticker_gate": ticker_gate, "strict_tickers": strict_tickers, "result": result}


def _ml_next_regime_frame_from_predictions(enriched_panel_v50: pd.DataFrame, predictions: pd.DataFrame) -> pd.DataFrame:
    if enriched_panel_v50 is None or enriched_panel_v50.empty or predictions is None or predictions.empty:
        return pd.DataFrame()
    if not _ml_next_required_columns(predictions, ["ticker", "date", "Fold", "rank_pct_in_fold", "y_true_success", "tb_return", "tb_mfe", "tb_mae"]):
        return pd.DataFrame()

    pred = predictions.copy()
    pred["date"] = pd.to_datetime(pred["date"], errors="coerce")

    features = enriched_panel_v50.copy()
    features["date"] = pd.to_datetime(features["date"], errors="coerce")
    regime_cols = [
        "ticker", "date", "vol_20d", "vol_60d", "atr_pct", "drawdown", "return_20d", "return_60d",
        "price_vs_ema20", "price_vs_ema50", "rsi_14", "volume_zscore", "breakout_20d", "breakdown_20d",
    ]
    regime_cols = [c for c in regime_cols if c in features.columns]
    merged = pd.merge(pred, features[regime_cols], on=["ticker", "date"], how="left")

    for col in [
        "rank_pct_in_fold", "y_true_success", "tb_return", "tb_mfe", "tb_mae", "vol_20d", "vol_60d",
        "atr_pct", "drawdown", "return_20d", "return_60d", "price_vs_ema20", "price_vs_ema50",
        "rsi_14", "volume_zscore",
    ]:
        if col in merged.columns:
            merged[col] = pd.to_numeric(merged[col], errors="coerce")

    if "vol_20d" in merged.columns:
        merged["vol_regime"] = _rank_bucket_v35(merged["vol_20d"], ["Low vol", "Mid vol", "High vol"])
    if "atr_pct" in merged.columns:
        merged["atr_regime"] = _rank_bucket_v35(merged["atr_pct"], ["Low ATR", "Mid ATR", "High ATR"])
    if "drawdown" in merged.columns:
        merged["drawdown_regime"] = pd.cut(
            merged["drawdown"],
            bins=[-np.inf, -0.15, -0.05, np.inf],
            labels=["Deep drawdown", "Moderate drawdown", "Near highs"],
            include_lowest=True,
        ).astype("object")
    if "rsi_14" in merged.columns:
        merged["rsi_regime"] = pd.cut(
            merged["rsi_14"],
            bins=[-np.inf, 35, 55, 70, np.inf],
            labels=["RSI weak", "RSI neutral", "RSI strong", "RSI extended"],
            include_lowest=True,
        ).astype("object")
    if "return_20d" in merged.columns and "price_vs_ema50" in merged.columns:
        merged["trend_regime"] = np.select(
            [
                (merged["return_20d"] > 0) & (merged["price_vs_ema50"] > 0),
                (merged["return_20d"] < 0) & (merged["price_vs_ema50"] < 0),
            ],
            ["Positive trend", "Negative trend"],
            default="Mixed trend",
        )
    if "volume_zscore" in merged.columns:
        merged["volume_regime"] = pd.cut(
            merged["volume_zscore"],
            bins=[-np.inf, -0.5, 1.0, np.inf],
            labels=["Low volume", "Normal volume", "High volume"],
            include_lowest=True,
        ).astype("object")

    return merged


def run_v57_regime_gated_enriched_ranker(enriched_panel_v50: pd.DataFrame, predictions: pd.DataFrame) -> dict:
    """V5.7 — Regime diagnostics for current enriched/ticker-gated predictions."""
    frame = _ml_next_regime_frame_from_predictions(enriched_panel_v50, predictions)
    if frame.empty:
        return {"manifest": pd.DataFrame(), "regime_table": pd.DataFrame(), "regime_frame": pd.DataFrame()}

    regime_cols = ["vol_regime", "atr_regime", "drawdown_regime", "rsi_regime", "trend_regime", "volume_regime"]
    regime_cols = [c for c in regime_cols if c in frame.columns]
    rows = []

    for regime_col in regime_cols:
        for bucket, group in frame.groupby(regime_col, dropna=True):
            if group.empty:
                continue
            top20 = group[group["rank_pct_in_fold"] >= 0.80]
            bottom20 = group[group["rank_pct_in_fold"] <= 0.20]
            all_tp = group["y_true_success"].mean()
            all_ret = group["tb_return"].mean()
            top_tp = top20["y_true_success"].mean() if not top20.empty else np.nan
            top_ret = top20["tb_return"].mean() if not top20.empty else np.nan
            bottom_ret = bottom20["tb_return"].mean() if not bottom20.empty else np.nan
            ret_lift = top_ret - all_ret if not pd.isna(top_ret) else np.nan
            tp_lift = top_tp - all_tp if not pd.isna(top_tp) else np.nan
            spread = top_ret - bottom_ret if not pd.isna(top_ret) and not pd.isna(bottom_ret) else np.nan

            if len(group) < 20 or len(top20) < 3:
                verdict = "Small sample"
            elif ret_lift > 0 and tp_lift > 0.05 and (pd.isna(spread) or spread > 0):
                verdict = "Supportive regime"
            elif ret_lift > 0:
                verdict = "Return supportive"
            elif ret_lift < -0.005 or (not pd.isna(spread) and spread <= 0):
                verdict = "Weak / avoid regime"
            else:
                verdict = "Neutral"

            rows.append(
                {
                    "Regime dimension": regime_col,
                    "Regime bucket": str(bucket),
                    "OOS count": len(group),
                    "Top20 count": len(top20),
                    "All TP %": all_tp,
                    "Top20 TP %": top_tp,
                    "Top20 TP lift": tp_lift,
                    "All avg return": all_ret,
                    "Top20 avg return": top_ret,
                    "Top20 return lift": ret_lift,
                    "Bottom20 avg return": bottom_ret,
                    "Top20 minus Bottom20": spread,
                    "Top20 avg MFE": top20["tb_mfe"].mean() if not top20.empty else np.nan,
                    "Top20 avg MAE": top20["tb_mae"].mean() if not top20.empty else np.nan,
                    "Regime verdict": verdict,
                }
            )

    table = pd.DataFrame(rows)
    if not table.empty:
        table = table.sort_values(["Regime dimension", "Regime verdict", "Top20 return lift"], ascending=[True, True, False])

    supportive = int(table["Regime verdict"].isin(["Supportive regime", "Return supportive"]).sum()) if not table.empty else 0
    weak = int((table["Regime verdict"] == "Weak / avoid regime").sum()) if not table.empty else 0

    if supportive > 0 and weak == 0:
        status = "Constructive"
        detail = "Regime table has supportive buckets and no avoid bucket."
    elif supportive > 0 and weak > 0:
        status = "Regime-sensitive"
        detail = "Supportive and weak regimes coexist."
    else:
        status = "Inconclusive"
        detail = "No robust regime edge."

    manifest = pd.DataFrame(
        [
            {"Decision item": "V5.7 regime gate", "Status": status, "Detail": detail},
            {"Decision item": "Supportive regimes", "Status": "Info", "Detail": f"{supportive} supportive/return-supportive buckets."},
            {"Decision item": "Weak regimes", "Status": "OK" if weak == 0 else "À surveiller", "Detail": f"{weak} weak/avoid buckets."},
            {"Decision item": "Decision Engine", "Status": "Blocked", "Detail": "Aucune intégration."},
        ]
    )

    return {"manifest": manifest, "regime_table": table, "regime_frame": frame}


def run_v58_label_robustness_diagnostics(enriched_panel_v50: pd.DataFrame) -> dict:
    """V5.8 — Multi-horizon / multi-barrier label robustness, read-only."""
    if enriched_panel_v50 is None or enriched_panel_v50.empty or "ticker" not in enriched_panel_v50.columns:
        return {"manifest": pd.DataFrame(), "label_grid": pd.DataFrame()}

    scenarios = [
        (5, 1.0, 1.0),
        (10, 1.0, 1.0),
        (20, 1.5, 1.5),
        (20, 2.0, 1.0),
        (40, 1.5, 1.5),
        (60, 2.0, 2.0),
    ]
    rows = []

    for horizon, tp_mult, sl_mult in scenarios:
        label_frames = []
        for ticker_name, group in enriched_panel_v50.groupby("ticker"):
            needed = ["date", "open", "high", "low", "close"]
            if any(c not in group.columns for c in needed):
                continue
            try:
                base = group.sort_values("date").copy()
                labeled = make_triple_barrier_labels_v1(
                    feature_df=base,
                    horizon=int(horizon),
                    pt_mult=float(tp_mult),
                    sl_mult=float(sl_mult),
                    conservative_intraday=True,
                )
                labeled["ticker"] = ticker_name
                label_frames.append(labeled)
            except Exception:
                continue

        if not label_frames:
            continue

        panel = pd.concat(label_frames, ignore_index=True)
        labels = panel.dropna(subset=["tb_label"]).copy()
        if labels.empty:
            continue

        per_ticker = labels.groupby("ticker")["tb_label"].count()
        rows.append(
            {
                "Scenario": f"H{horizon} TP{tp_mult} SL{sl_mult}",
                "Horizon": horizon,
                "TP ATR": tp_mult,
                "SL ATR": sl_mult,
                "Labels": len(labels),
                "Tickers": labels["ticker"].nunique(),
                "Min labels/ticker": int(per_ticker.min()) if not per_ticker.empty else 0,
                "TP %": (labels["tb_label"] == 1).mean(),
                "SL %": (labels["tb_label"] == -1).mean(),
                "Timeout %": (labels["tb_label"] == 0).mean(),
                "Avg return": labels["tb_return"].mean(),
                "Avg MFE": labels["tb_mfe"].mean(),
                "Avg MAE": labels["tb_mae"].mean(),
            }
        )

    grid = pd.DataFrame(rows)
    if not grid.empty:
        grid["Label balance score"] = (
            100
            - (grid["TP %"] - 0.50).abs() * 100
            - (grid["SL %"] - 0.50).abs() * 50
            - grid["Timeout %"] * 20
        ).clip(0, 100)
        grid["Robustness status"] = np.where(
            (grid["Labels"] >= 500)
            & (grid["Tickers"] >= 5)
            & (grid["TP %"].between(0.25, 0.70))
            & (grid["SL %"].between(0.20, 0.75)),
            "Usable label scenario",
            "Watch label scenario",
        )
        grid = grid.sort_values(["Robustness status", "Label balance score"], ascending=[True, False])

    usable = int((grid["Robustness status"] == "Usable label scenario").sum()) if not grid.empty else 0
    manifest = pd.DataFrame(
        [
            {"Decision item": "V5.8 label robustness", "Status": "OK" if usable > 0 else "Watch", "Detail": f"{usable} usable scenario(s) detected."},
            {"Decision item": "Interpretation", "Status": "Research-only", "Detail": "This validates label construction only; no model promotion."},
            {"Decision item": "Decision Engine", "Status": "Blocked", "Detail": "Aucune intégration."},
        ]
    )
    return {"manifest": manifest, "label_grid": grid}


def run_v59_model_family_benchmark(
    enriched_panel_v50: pd.DataFrame,
    rescue_v55: dict,
    n_splits: int = 5,
    embargo_days: int = 5,
    min_train_size: int = 300,
    min_test_size: int = 50,
) -> dict:
    """V5.9 — Conservative model family benchmark, research-only."""
    rescue = rescue_v55.get("rescue_shortlist", pd.DataFrame()) if isinstance(rescue_v55, dict) else pd.DataFrame()
    if rescue is None or rescue.empty:
        return {"manifest": pd.DataFrame(), "benchmark": pd.DataFrame(), "runs": {}}

    feature_cols = rescue.loc[rescue["V5.5 rescue role"].isin(["Rescue keep", "Rescue watch"]), "Feature"].astype(str).tolist()
    if not feature_cols:
        return {"manifest": pd.DataFrame(), "benchmark": pd.DataFrame(), "runs": {}}

    models = [
        "Logistic very strong regularization",
        "Logistic strong regularization",
        "Logistic unweighted",
        "Logistic balanced",
        "Random forest shallow",
    ]
    rows = []
    runs = {}

    for model_name in models:
        result = run_research_ranker_with_feature_cols_vnext(
            enriched_panel_v50=enriched_panel_v50,
            feature_cols=feature_cols,
            model_name=model_name,
            n_splits=n_splits,
            embargo_days=embargo_days,
            min_train_size=min_train_size,
            min_test_size=min_test_size,
            run_label=f"V5.9 {model_name}",
        )
        runs[model_name] = result
        folds = result.get("folds", pd.DataFrame())
        ok = folds[folds["Status"] == "OK"].copy() if folds is not None and not folds.empty else pd.DataFrame()

        if ok.empty:
            rows.append({"Model": model_name, "Status": "No valid fold", "Folds OK": 0})
            continue

        avg_auc = ok["AUC"].mean()
        avg_brier = ok["Brier improvement"].mean()
        avg_ret = ok["Top20 return lift"].mean()
        avg_tp = ok["Top20 TP lift"].mean()
        avg_spread = ok["Top20 minus Bottom20"].mean()
        pos_folds = int((ok["Top20 return lift"] > 0).sum())

        if avg_ret > 0 and avg_spread > 0 and pos_folds >= max(1, len(ok) - 1):
            status = "Research candidate"
        elif avg_ret > 0 or avg_tp > 0.05:
            status = "Watchlist"
        else:
            status = "Rejected"

        rows.append(
            {
                "Model": model_name,
                "Status": status,
                "Folds OK": len(ok),
                "Avg AUC": avg_auc,
                "Avg Brier improvement": avg_brier,
                "Avg Top20 TP lift": avg_tp,
                "Avg Top20 return lift": avg_ret,
                "Avg Top20 spread": avg_spread,
                "Positive return folds": pos_folds,
            }
        )

    benchmark = pd.DataFrame(rows)
    if not benchmark.empty:
        benchmark = benchmark.sort_values(["Status", "Avg Top20 return lift", "Avg Top20 spread"], ascending=[True, False, False])

    candidates = int((benchmark["Status"] == "Research candidate").sum()) if not benchmark.empty and "Status" in benchmark.columns else 0
    manifest = pd.DataFrame(
        [
            {"Decision item": "V5.9 model benchmark", "Status": "Research-only", "Detail": f"{len(benchmark)} model families evaluated/skipped."},
            {"Decision item": "Research candidates", "Status": "OK" if candidates > 0 else "Weak", "Detail": f"{candidates} candidate model(s)."},
            {"Decision item": "Promotion", "Status": "Blocked", "Detail": "Even candidate models require V6.0–V6.2 checks."},
            {"Decision item": "Decision Engine", "Status": "Blocked", "Detail": "Aucune intégration."},
        ]
    )
    return {"manifest": manifest, "benchmark": benchmark, "runs": runs}


def run_v60_probability_calibration_lab(predictions: pd.DataFrame, n_bins: int = 10) -> dict:
    """V6.0 — Probability diagnostics only. No calibrated probability is promoted."""
    if predictions is None or predictions.empty or not _ml_next_required_columns(predictions, ["p_raw", "y_true_success", "Fold"]):
        return {"manifest": pd.DataFrame(), "calibration_bins": pd.DataFrame(), "fold_calibration": pd.DataFrame()}

    work = predictions.copy()
    work["p_raw"] = pd.to_numeric(work["p_raw"], errors="coerce")
    work["y_true_success"] = pd.to_numeric(work["y_true_success"], errors="coerce")
    work = work.dropna(subset=["p_raw", "y_true_success"])
    if work.empty:
        return {"manifest": pd.DataFrame(), "calibration_bins": pd.DataFrame(), "fold_calibration": pd.DataFrame()}

    work["calibration_bin"] = pd.cut(work["p_raw"], bins=np.linspace(0, 1, int(n_bins) + 1), include_lowest=True)
    bin_rows = []
    ece = 0.0
    for b, group in work.groupby("calibration_bin", observed=False):
        if group.empty:
            continue
        avg_p = group["p_raw"].mean()
        realized = group["y_true_success"].mean()
        gap = avg_p - realized
        weight = len(group) / len(work)
        ece += abs(gap) * weight
        bin_rows.append(
            {
                "Calibration bin": str(b),
                "Count": len(group),
                "Avg raw probability": avg_p,
                "Realized TP %": realized,
                "Calibration gap": gap,
                "Abs gap": abs(gap),
                "Weight": weight,
            }
        )
    bins = pd.DataFrame(bin_rows)

    fold_rows = []
    for fold, group in work.groupby("Fold"):
        avg_p = group["p_raw"].mean()
        realized = group["y_true_success"].mean()
        try:
            brier = brier_score_loss(group["y_true_success"].astype(int), group["p_raw"])
        except Exception:
            brier = np.nan
        fold_rows.append(
            {
                "Fold": int(fold),
                "Count": len(group),
                "Avg raw probability": avg_p,
                "Realized TP %": realized,
                "Calibration gap": avg_p - realized,
                "Abs calibration gap": abs(avg_p - realized),
                "Brier": brier,
            }
        )
    fold_cal = pd.DataFrame(fold_rows)

    mean_abs_gap = fold_cal["Abs calibration gap"].mean() if not fold_cal.empty else np.nan
    if ece <= 0.07 and mean_abs_gap <= 0.10:
        status = "Diagnostic acceptable"
        detail = "Calibration looks acceptable globally but probability remains blocked."
    elif ece <= 0.15:
        status = "Moderate calibration error"
        detail = "Calibration still too weak for probability usage."
    else:
        status = "Poor calibration"
        detail = "Raw probability is not usable."

    manifest = pd.DataFrame(
        [
            {"Decision item": "V6.0 calibration lab", "Status": status, "Detail": detail},
            {"Decision item": "ECE", "Status": "Info", "Detail": f"{ece:.4f}"},
            {"Decision item": "Probability usage", "Status": "Blocked", "Detail": "No raw or calibrated probability may be used."},
            {"Decision item": "Decision Engine", "Status": "Blocked", "Detail": "Aucune intégration."},
        ]
    )
    return {"manifest": manifest, "calibration_bins": bins, "fold_calibration": fold_cal, "ece": ece}


def run_v61_shadow_policy_backtest(predictions: pd.DataFrame, cost_bps: float = 10.0) -> dict:
    """V6.1 — Shadow policy backtest over OOS predictions, rank-only."""
    if predictions is None or predictions.empty or not _ml_next_required_columns(predictions, ["date", "rank_pct_in_fold", "tb_return", "y_true_success"]):
        return {"manifest": pd.DataFrame(), "policy_summary": pd.DataFrame(), "policy_by_fold": pd.DataFrame()}

    work = predictions.copy()
    work["date"] = pd.to_datetime(work["date"], errors="coerce")
    for col in ["rank_pct_in_fold", "tb_return", "tb_mfe", "tb_mae", "y_true_success"]:
        if col in work.columns:
            work[col] = pd.to_numeric(work[col], errors="coerce")
    work = work.dropna(subset=["date", "rank_pct_in_fold", "tb_return", "y_true_success"])
    if work.empty:
        return {"manifest": pd.DataFrame(), "policy_summary": pd.DataFrame(), "policy_by_fold": pd.DataFrame()}

    cost = float(cost_bps) / 10000.0
    policies = ["Top 10%", "Top 20%", "Top 30%", "Bottom 20%", "All OOS"]
    rows = []
    fold_rows = []

    for policy in policies:
        selected = work.loc[_ml_next_select_top_mask(work, policy)].copy()
        if selected.empty:
            continue
        selected = selected.sort_values("date")
        selected["net_return"] = selected["tb_return"] - cost
        daily = selected.groupby("date")["net_return"].mean().sort_index()
        equity = (1 + daily.fillna(0)).cumprod()
        drawdown = equity / equity.cummax() - 1 if not equity.empty else pd.Series(dtype=float)
        max_dd = drawdown.min() if not drawdown.empty else np.nan
        avg_return = selected["net_return"].mean()
        hit_rate = selected["y_true_success"].mean()
        turnover_proxy = len(selected) / max(1, work["date"].nunique())
        exposure_proxy = selected["date"].nunique() / max(1, work["date"].nunique())

        rows.append(
            {
                "Policy": policy,
                "Count": len(selected),
                "Dates": selected["date"].nunique(),
                "Hit rate": hit_rate,
                "Avg gross return": selected["tb_return"].mean(),
                "Avg net return": avg_return,
                "Avg MFE": selected["tb_mfe"].mean() if "tb_mfe" in selected.columns else np.nan,
                "Avg MAE": selected["tb_mae"].mean() if "tb_mae" in selected.columns else np.nan,
                "Cumulative net return proxy": equity.iloc[-1] - 1 if not equity.empty else np.nan,
                "Max drawdown proxy": max_dd,
                "Turnover proxy": turnover_proxy,
                "Exposure proxy": exposure_proxy,
                "Cost bps": cost_bps,
            }
        )

        if "Fold" in selected.columns:
            for fold, group in selected.groupby("Fold"):
                fold_rows.append(
                    {
                        "Policy": policy,
                        "Fold": int(fold),
                        "Count": len(group),
                        "Hit rate": group["y_true_success"].mean(),
                        "Avg gross return": group["tb_return"].mean(),
                        "Avg net return": group["tb_return"].mean() - cost,
                    }
                )

    summary = pd.DataFrame(rows)
    by_fold = pd.DataFrame(fold_rows)

    top20 = summary[summary["Policy"] == "Top 20%"] if not summary.empty else pd.DataFrame()
    if top20.empty:
        status = "Unavailable"
        detail = "Top20 policy unavailable."
    elif float(top20.iloc[0].get("Avg net return", 0)) > 0:
        status = "Shadow positive"
        detail = "Top20 net return proxy positive, still research-only."
    else:
        status = "Shadow weak"
        detail = "Top20 net return proxy not positive."

    manifest = pd.DataFrame(
        [
            {"Decision item": "V6.1 shadow policy", "Status": status, "Detail": detail},
            {"Decision item": "Cost model", "Status": "Info", "Detail": f"{cost_bps:.1f} bps deducted per selected event."},
            {"Decision item": "Trading signal", "Status": "Blocked", "Detail": "This is a historical shadow policy only."},
            {"Decision item": "Decision Engine", "Status": "Blocked", "Detail": "Aucune intégration."},
        ]
    )
    return {"manifest": manifest, "policy_summary": summary, "policy_by_fold": by_fold}


def run_v62_promotion_gate_v2(
    v59: dict,
    v60: dict,
    v61: dict,
    v57: dict,
) -> dict:
    """V6.2 — Hard promotion gate. Intended to block unless all institutional checks pass."""
    benchmark = v59.get("benchmark", pd.DataFrame()) if isinstance(v59, dict) else pd.DataFrame()
    cal_manifest = v60.get("manifest", pd.DataFrame()) if isinstance(v60, dict) else pd.DataFrame()
    policy_summary = v61.get("policy_summary", pd.DataFrame()) if isinstance(v61, dict) else pd.DataFrame()
    regime_table = v57.get("regime_table", pd.DataFrame()) if isinstance(v57, dict) else pd.DataFrame()

    best_model = None
    best = pd.DataFrame()
    if benchmark is not None and not benchmark.empty and "Status" in benchmark.columns:
        candidates = benchmark[benchmark["Status"] == "Research candidate"].copy()
        if not candidates.empty:
            candidates = candidates.sort_values(["Avg Top20 return lift", "Avg Top20 spread"], ascending=[False, False])
            best = candidates.iloc[[0]].copy()
            best_model = str(best.iloc[0].get("Model"))

    criteria_rows = []

    def add(name, passed, detail, critical=True):
        criteria_rows.append(
            {
                "Criterion": name,
                "Passed": bool(passed),
                "Critical": bool(critical),
                "Detail": detail,
            }
        )

    if best.empty:
        add("Model candidate", False, "No V5.9 research candidate.")
    else:
        r = best.iloc[0]
        add("AUC", _safe_float(r.get("Avg AUC"), 0) >= 0.55, _fmt_num(r.get("Avg AUC")))
        add("Top20 return lift", _safe_float(r.get("Avg Top20 return lift"), 0) > 0, _fmt_pct(r.get("Avg Top20 return lift")))
        add("Top20 TP lift", _safe_float(r.get("Avg Top20 TP lift"), 0) > 0, _fmt_pct(r.get("Avg Top20 TP lift")))
        add("Top/Bottom spread", _safe_float(r.get("Avg Top20 spread"), 0) > 0, _fmt_pct(r.get("Avg Top20 spread")))
        add("Positive return folds", _safe_float(r.get("Positive return folds"), 0) >= max(1, _safe_float(r.get("Folds OK"), 0) - 1), f"{r.get('Positive return folds')}/{r.get('Folds OK')}")

    ece = v60.get("ece", np.nan) if isinstance(v60, dict) else np.nan
    add("Calibration ECE", not pd.isna(ece) and ece <= 0.07, "N/A" if pd.isna(ece) else f"{ece:.4f}")

    top20 = policy_summary[policy_summary["Policy"] == "Top 20%"] if policy_summary is not None and not policy_summary.empty and "Policy" in policy_summary.columns else pd.DataFrame()
    if top20.empty:
        add("Shadow policy Top20", False, "Top20 policy unavailable.")
    else:
        add("Shadow policy net return", _safe_float(top20.iloc[0].get("Avg net return"), 0) > 0, _fmt_pct(top20.iloc[0].get("Avg net return")))
        add("Shadow policy drawdown", _safe_float(top20.iloc[0].get("Max drawdown proxy"), -1) > -0.20, _fmt_pct(top20.iloc[0].get("Max drawdown proxy")), critical=False)

    weak_regimes = 0
    if regime_table is not None and not regime_table.empty and "Regime verdict" in regime_table.columns:
        weak_regimes = int((regime_table["Regime verdict"] == "Weak / avoid regime").sum())
    add("Regime fragility", weak_regimes == 0, f"{weak_regimes} weak regime bucket(s).")

    criteria = pd.DataFrame(criteria_rows)
    critical_failures = int(((criteria["Passed"] == False) & (criteria["Critical"] == True)).sum()) if not criteria.empty else 1

    if critical_failures == 0:
        eligibility = "Shadow monitor eligible"
        detail = "All critical checks passed, but Decision Engine remains blocked until live shadow monitoring."
    else:
        eligibility = "Blocked"
        detail = f"{critical_failures} critical failure(s). No promotion."

    manifest = pd.DataFrame(
        [
            {"Decision item": "V6.2 promotion eligibility", "Status": eligibility, "Detail": detail},
            {"Decision item": "Selected research model", "Status": "Info", "Detail": best_model or "None"},
            {"Decision item": "Probability", "Status": "Blocked", "Detail": "No probability is promoted."},
            {"Decision item": "Decision Engine", "Status": "Blocked", "Detail": "Aucune intégration autorisée."},
        ]
    )

    return {"manifest": manifest, "criteria": criteria, "selected_model": best_model, "eligibility": eligibility}


def run_v63_shadow_live_monitor(
    enriched_panel_v50: pd.DataFrame,
    rescue_v55: dict,
    selected_model: str | None,
    reference_predictions: pd.DataFrame,
) -> dict:
    """V6.3 — Current shadow monitor. Rank only. No action."""
    if not selected_model:
        return {"manifest": pd.DataFrame([{"Decision item": "V6.3 shadow monitor", "Status": "Blocked", "Detail": "No selected model from V6.2."}]), "current_scores": pd.DataFrame()}

    rescue = rescue_v55.get("rescue_shortlist", pd.DataFrame()) if isinstance(rescue_v55, dict) else pd.DataFrame()
    if rescue is None or rescue.empty or enriched_panel_v50 is None or enriched_panel_v50.empty:
        return {"manifest": pd.DataFrame(), "current_scores": pd.DataFrame()}

    feature_cols = rescue.loc[rescue["V5.5 rescue role"].isin(["Rescue keep", "Rescue watch"]), "Feature"].astype(str).tolist()
    X, y, meta = _ml_next_prepare_dataset_with_features(enriched_panel_v50, feature_cols)
    if X.empty or y.empty or meta.empty:
        return {"manifest": pd.DataFrame(), "current_scores": pd.DataFrame()}

    valid = pd.concat([meta.reset_index(drop=True), X.reset_index(drop=True)], axis=1)
    valid["_y_success"] = y.values
    valid["date"] = pd.to_datetime(valid["date"], errors="coerce")
    valid = valid.dropna(subset=["date", "ticker"])
    if valid.empty or valid["_y_success"].nunique() < 2:
        return {"manifest": pd.DataFrame(), "current_scores": pd.DataFrame()}

    latest_date = valid["date"].max()
    train = valid[valid["date"] < latest_date].copy()
    latest = valid[valid["date"] == latest_date].copy()
    if train.empty or latest.empty or len(train) < 100:
        return {"manifest": pd.DataFrame(), "current_scores": pd.DataFrame()}

    try:
        model = _ml_next_make_research_model(selected_model)
        if model is None:
            return {"manifest": pd.DataFrame(), "current_scores": pd.DataFrame()}
        model.fit(train[feature_cols], train["_y_success"].astype(int))
        raw = model.predict_proba(latest[feature_cols])[:, 1]
        latest = latest[["ticker", "date", "tb_label", "tb_return", "tb_mfe", "tb_mae"]].copy()
        latest["Model"] = selected_model
        latest["raw_probability_blocked"] = raw

        ref = reference_predictions.copy() if reference_predictions is not None and not reference_predictions.empty else pd.DataFrame()
        scores = []
        for _, row in latest.iterrows():
            ticker_name = str(row.get("ticker"))
            raw_p = _safe_float(row.get("raw_probability_blocked"), np.nan)
            if ref is not None and not ref.empty and "p_raw" in ref.columns:
                ref_probs = pd.to_numeric(ref.loc[ref["ticker"].astype(str) == ticker_name, "p_raw"], errors="coerce").dropna()
                if ref_probs.empty:
                    ref_probs = pd.to_numeric(ref["p_raw"], errors="coerce").dropna()
            else:
                ref_probs = pd.Series(dtype=float)
            if ref_probs.empty or pd.isna(raw_p):
                rank_pct = np.nan
            else:
                rank_pct = float((ref_probs <= raw_p).mean())
            scores.append(
                {
                    "Date": row.get("date"),
                    "Ticker": ticker_name,
                    "Model": selected_model,
                    "Raw probability": raw_p,
                    "Raw probability status": "Blocked",
                    "Shadow rank percentile": rank_pct,
                    "Shadow bucket": _ml_next_rank_bucket_from_pct(rank_pct) if not pd.isna(rank_pct) else "Unavailable",
                    "Decision Engine": "Blocked",
                    "Research interpretation": "Monitor only",
                }
            )
        current_scores = pd.DataFrame(scores)
    except Exception as e:
        current_scores = pd.DataFrame([{"Error": str(e)[:120]}])

    manifest = pd.DataFrame(
        [
            {"Decision item": "V6.3 shadow live monitor", "Status": "Research-only", "Detail": "Current rank scores displayed for monitoring only."},
            {"Decision item": "Trading signal", "Status": "Blocked", "Detail": "No BUY/SELL signal."},
            {"Decision item": "Probability", "Status": "Blocked", "Detail": "Raw probability is shown only as blocked diagnostic."},
            {"Decision item": "Decision Engine", "Status": "Blocked", "Detail": "Aucune intégration."},
        ]
    )
    return {"manifest": manifest, "current_scores": current_scores}


def run_v53_to_v63_institutional_suite(
    enriched_panel_v50: pd.DataFrame,
    shortlist_v511: pd.DataFrame,
    v52_results: dict,
    n_splits: int = 5,
    embargo_days: int = 5,
    min_train_size: int = 300,
    min_test_size: int = 50,
    include_watch: bool = False,
    cost_bps: float = 10.0,
) -> dict:
    """One-shot institutional continuation from V5.3 to V6.3."""
    v53 = build_v53_enriched_failure_attribution(v52_results)
    v54 = run_v54_feature_block_ablation(
        enriched_panel_v50=enriched_panel_v50,
        shortlist_v511=shortlist_v511,
        n_splits=n_splits,
        embargo_days=embargo_days,
        min_train_size=min_train_size,
        min_test_size=min_test_size,
        include_watch=include_watch,
    )
    v55 = run_v55_feature_rescue_shortlist(
        enriched_panel_v50=enriched_panel_v50,
        shortlist_v511=shortlist_v511,
        ablation_v54=v54,
        include_watch=include_watch,
    )
    v56 = run_v56_ticker_gated_enriched_ranker(
        enriched_panel_v50=enriched_panel_v50,
        rescue_v55=v55,
        v52_results=v52_results,
        n_splits=n_splits,
        embargo_days=embargo_days,
        min_train_size=min_train_size,
        min_test_size=min_test_size,
    )

    v56_predictions = pd.DataFrame()
    if isinstance(v56, dict):
        v56_result = v56.get("result", {})
        if isinstance(v56_result, dict):
            v56_predictions = v56_result.get("predictions", pd.DataFrame())

    base_predictions = v56_predictions if v56_predictions is not None and not v56_predictions.empty else v52_results.get("predictions", pd.DataFrame())

    v57 = run_v57_regime_gated_enriched_ranker(enriched_panel_v50, base_predictions)
    v58 = run_v58_label_robustness_diagnostics(enriched_panel_v50)
    v59 = run_v59_model_family_benchmark(
        enriched_panel_v50=enriched_panel_v50,
        rescue_v55=v55,
        n_splits=n_splits,
        embargo_days=embargo_days,
        min_train_size=min_train_size,
        min_test_size=min_test_size,
    )

    best_predictions = base_predictions
    if isinstance(v59, dict):
        bench = v59.get("benchmark", pd.DataFrame())
        runs = v59.get("runs", {})
        if bench is not None and not bench.empty and "Model" in bench.columns:
            candidates = bench[bench["Status"].isin(["Research candidate", "Watchlist"])].copy() if "Status" in bench.columns else pd.DataFrame()
            if not candidates.empty:
                candidates = candidates.sort_values("Avg Top20 return lift", ascending=False)
                candidate_model = str(candidates.iloc[0].get("Model"))
                candidate_run = runs.get(candidate_model, {}) if isinstance(runs, dict) else {}
                if isinstance(candidate_run, dict) and not candidate_run.get("predictions", pd.DataFrame()).empty:
                    best_predictions = candidate_run.get("predictions", pd.DataFrame())

    v60 = run_v60_probability_calibration_lab(best_predictions)
    v61 = run_v61_shadow_policy_backtest(best_predictions, cost_bps=cost_bps)
    v62 = run_v62_promotion_gate_v2(v59=v59, v60=v60, v61=v61, v57=v57)
    v63 = run_v63_shadow_live_monitor(
        enriched_panel_v50=enriched_panel_v50,
        rescue_v55=v55,
        selected_model=v62.get("selected_model") if isinstance(v62, dict) else None,
        reference_predictions=best_predictions,
    )

    final_manifest = pd.DataFrame(
        [
            {"Gate": "V5.3 failure attribution", "Status": "Completed", "Decision Engine": "Blocked"},
            {"Gate": "V5.4 feature block ablation", "Status": "Completed", "Decision Engine": "Blocked"},
            {"Gate": "V5.5 feature rescue", "Status": "Completed", "Decision Engine": "Blocked"},
            {"Gate": "V5.6 ticker-gated ranker", "Status": "Completed", "Decision Engine": "Blocked"},
            {"Gate": "V5.7 regime diagnostics", "Status": "Completed", "Decision Engine": "Blocked"},
            {"Gate": "V5.8 label robustness", "Status": "Completed", "Decision Engine": "Blocked"},
            {"Gate": "V5.9 model family benchmark", "Status": "Completed", "Decision Engine": "Blocked"},
            {"Gate": "V6.0 calibration lab", "Status": "Completed", "Decision Engine": "Blocked"},
            {"Gate": "V6.1 shadow policy backtest", "Status": "Completed", "Decision Engine": "Blocked"},
            {"Gate": "V6.2 promotion gate", "Status": v62.get("eligibility", "Blocked") if isinstance(v62, dict) else "Blocked", "Decision Engine": "Blocked"},
            {"Gate": "V6.3 shadow live monitor", "Status": "Research-only", "Decision Engine": "Blocked"},
        ]
    )

    return {
        "final_manifest": final_manifest,
        "v53": v53,
        "v54": v54,
        "v55": v55,
        "v56": v56,
        "v57": v57,
        "v58": v58,
        "v59": v59,
        "v60": v60,
        "v61": v61,
        "v62": v62,
        "v63": v63,
    }


def _ml_next_display_percent_columns(df: pd.DataFrame, pct_cols: list[str]) -> pd.DataFrame:
    display = df.copy()
    for col in pct_cols:
        if col in display.columns:
            display[col] = display[col].apply(_fmt_pct)
    return display


def render_v53_to_v63_institutional_suite_panel(
    v50_results: dict,
    v511_results: dict,
    v52_results: dict,
    ticker: str,
) -> None:
    """Render V5.3 → V6.3 continuation suite below V5.2."""
    st.divider()
    st.subheader("V5.3 → V6.3 — Institutional ML Continuation Suite")
    st.info(
        "Suite research-only : failure attribution, ablation, rescue shortlist, ticker/regime gates, "
        "model benchmark, calibration diagnostics, shadow policy and promotion gate. "
        "Aucune probabilité exploitable, aucun signal, aucune intégration Decision Engine."
    )

    if not isinstance(v50_results, dict) or not v50_results:
        st.info("Lance d'abord V5.0 pour construire le panel enrichi.")
        return
    if not isinstance(v511_results, dict) or not v511_results:
        st.info("Lance d'abord V5.1.1 pour construire la shortlist.")
        return
    if not isinstance(v52_results, dict) or not v52_results:
        st.info("Lance d'abord V5.2 pour produire les prédictions OOS de référence.")
        return

    enriched_panel_v50 = v50_results.get("enriched_panel", pd.DataFrame())
    shortlist_v511 = v511_results.get("shortlist", pd.DataFrame())
    predictions_v52 = v52_results.get("predictions", pd.DataFrame())

    if enriched_panel_v50 is None or enriched_panel_v50.empty:
        st.info("Panel enrichi V5.0 indisponible.")
        return
    if shortlist_v511 is None or shortlist_v511.empty:
        st.info("Shortlist V5.1.1 indisponible.")
        return
    if predictions_v52 is None or predictions_v52.empty:
        st.info("Prédictions V5.2 indisponibles. Lance V5.2 avant la suite institutionnelle.")
        return

    c1, c2, c3, c4 = st.columns(4)
    next_folds = c1.selectbox("Suite folds", [3, 5, 7], index=1, key=f"ml_v53v63_folds_{ticker}")
    next_embargo = c2.selectbox("Suite embargo days", [3, 5, 10], index=1, key=f"ml_v53v63_embargo_{ticker}")
    next_min_train = c3.selectbox("Suite min train", [200, 300, 500, 800], index=1, key=f"ml_v53v63_min_train_{ticker}")
