def build_ml_regression_test_harness_v73(
    v50_results,
    v511_results,
    v52_results,
    suite_v53_v63,
    completion_v64_v72,
):
    """
    Institutional regression harness.
    It checks that the current ML stack remains research-only and internally coherent.
    No model is trained here. No Decision Engine connection is made.
    """
    v50_results = _mlqa_safe_dict(v50_results)
    v511_results = _mlqa_safe_dict(v511_results)
    v52_results = _mlqa_safe_dict(v52_results)
    suite_v53_v63 = _mlqa_safe_dict(suite_v53_v63)
    completion_v64_v72 = _mlqa_safe_dict(completion_v64_v72)

    enriched_panel = _mlqa_get_df(v50_results, "enriched_panel")
    v50_manifest = _mlqa_get_df(v50_results, "manifest")
    shortlist = _mlqa_get_df(v511_results, "shortlist")
    v511_manifest = _mlqa_get_df(v511_results, "manifest")
    v52_predictions = _mlqa_get_df(v52_results, "predictions")
    v52_folds = _mlqa_get_df(v52_results, "folds")
    v52_summary = _mlqa_get_df(v52_results, "summary")
    v52_cumulative = _mlqa_get_df(v52_results, "cumulative_summary")
    v64_final_manifest = _mlqa_get_df(completion_v64_v72, "final_manifest")

    rows = []

    def add(test, status, detail, severity="Hard"):
        rows.append(
            {
                "Test": test,
                "Status": status,
                "Severity": severity,
                "Detail": detail,
            }
        )

    add(
        "V5.0 enriched panel available",
        "PASS" if not enriched_panel.empty else "FAIL",
        f"{len(enriched_panel):,} rows." if not enriched_panel.empty else "Missing enriched_panel from V5.0 cache.",
    )

    add(
        "V5.0 labels available",
        "PASS" if (not enriched_panel.empty and "tb_label" in enriched_panel.columns and enriched_panel["tb_label"].notna().sum() > 0) else "FAIL",
        f"{int(enriched_panel['tb_label'].notna().sum()):,} labels." if (not enriched_panel.empty and "tb_label" in enriched_panel.columns) else "No usable tb_label column.",
    )

    add(
        "V5.1.1 feature shortlist available",
        "PASS" if not shortlist.empty else "FAIL",
        f"{len(shortlist):,} shortlisted feature rows." if not shortlist.empty else "Missing V5.1.1 shortlist.",
    )

    add(
        "V5.2 predictions available",
        "PASS" if not v52_predictions.empty else "FAIL",
        f"{len(v52_predictions):,} OOS predictions." if not v52_predictions.empty else "Missing V5.2 predictions.",
    )

    add(
        "V5.2 fold results available",
        "PASS" if not v52_folds.empty else "FAIL",
        f"{len(v52_folds):,} fold rows." if not v52_folds.empty else "Missing V5.2 folds.",
    )

    required_pred_cols = [
        "date",
        "ticker",
        "Fold",
        "rank_pct_in_fold",
        "y_true_success",
        "tb_return",
        "tb_mfe",
        "tb_mae",
    ]
    pred_missing = [col for col in required_pred_cols if col not in v52_predictions.columns]
    add(
        "V5.2 prediction schema",
        "PASS" if not pred_missing else "FAIL",
        "All required OOS prediction columns present." if not pred_missing else f"Missing columns: {', '.join(pred_missing)}.",
    )

    suite_keys = [f"v{i}" for i in range(53, 64)]
    present_suite_keys = [key for key in suite_keys if key in suite_v53_v63]
    add(
        "V5.3 -> V6.3 suite cache",
        "PASS" if len(present_suite_keys) >= 6 else "WARN",
        f"{len(present_suite_keys)}/{len(suite_keys)} expected suite keys detected.",
        severity="Soft",
    )

    completion_keys = [f"v{i}" for i in range(64, 73)]
    present_completion_keys = [key for key in completion_keys if key in completion_v64_v72]
    add(
        "V6.4 -> V7.2 completion cache",
        "PASS" if len(present_completion_keys) >= 7 else "WARN",
        f"{len(present_completion_keys)}/{len(completion_keys)} expected completion keys detected.",
        severity="Soft",
    )

    add(
        "V6.4 -> V7.2 final manifest available",
        "PASS" if not v64_final_manifest.empty else "WARN",
        f"{len(v64_final_manifest):,} manifest rows." if not v64_final_manifest.empty else "Final manifest not found; run V6.4 -> V7.2 first.",
        severity="Soft",
    )

    decision_blocked = any(
        [
            _mlqa_contains_blocked_status(v50_manifest, ["Decision"]),
            _mlqa_contains_blocked_status(v511_manifest, ["Decision"]),
            _mlqa_contains_blocked_status(v52_summary, ["Decision"]),
            _mlqa_contains_blocked_status(v64_final_manifest, ["Decision"]),
        ]
    )
    add(
        "Decision Engine remains blocked",
        "PASS" if decision_blocked else "WARN",
        "A blocked Decision Engine status was detected." if decision_blocked else "No explicit blocked Decision Engine row detected in cached manifests.",
    )

    probability_blocked = any(
        [
            _mlqa_contains_blocked_status(v50_manifest, ["Probability", "probabilité", "probability"]),
            _mlqa_contains_blocked_status(v52_summary, ["Probability", "probabilité", "probability"]),
            _mlqa_contains_blocked_status(v64_final_manifest, ["Probability", "probabilité", "probability"]),
        ]
    )
    add(
        "Raw probability remains blocked",
        "PASS" if probability_blocked else "WARN",
        "A blocked raw-probability status was detected." if probability_blocked else "No explicit probability-block row detected in cached manifests.",
    )

    forbidden_signal_cols = [
        col for col in v52_predictions.columns
        if str(col).lower() in {"signal", "buy", "sell", "buy_signal", "sell_signal", "decision_signal", "trade_signal"}
    ]
    add(
        "No BUY/SELL signal column exported",
        "PASS" if not forbidden_signal_cols else "FAIL",
        "No executable signal columns detected." if not forbidden_signal_cols else f"Forbidden signal-like columns detected: {', '.join(forbidden_signal_cols)}.",
    )

    if not v52_predictions.empty and "rank_pct_in_fold" in v52_predictions.columns:
        ranks = pd.to_numeric(v52_predictions["rank_pct_in_fold"], errors="coerce")
        rank_ok = bool(ranks.dropna().between(0, 1).all()) if ranks.notna().any() else False
        add(
            "Rank percentile bounded",
            "PASS" if rank_ok else "FAIL",
            "rank_pct_in_fold is within [0, 1]." if rank_ok else "rank_pct_in_fold has missing or out-of-range values.",
        )
    else:
        add("Rank percentile bounded", "FAIL", "rank_pct_in_fold missing.")

    out = pd.DataFrame(rows)
    if out.empty:
        return out

    order = {"FAIL": 0, "WARN": 1, "PASS": 2}
    out["_order"] = out["Status"].map(order).fillna(9)
    out = out.sort_values(["_order", "Severity", "Test"]).drop(columns=["_order"])
    return out


def build_ml_regression_test_manifest_v73(test_harness):
    if test_harness is None or test_harness.empty:
        return pd.DataFrame(
            [
                {
                    "Item": "V7.3 regression harness",
                    "Status": "Unavailable",
                    "Detail": "No test result available.",
                }
            ]
        )

    hard = test_harness[test_harness["Severity"] == "Hard"].copy()
    fail_count = int((test_harness["Status"] == "FAIL").sum())
    warn_count = int((test_harness["Status"] == "WARN").sum())
    pass_count = int((test_harness["Status"] == "PASS").sum())
    hard_fail_count = int((hard["Status"] == "FAIL").sum()) if not hard.empty else fail_count

    if hard_fail_count == 0 and fail_count == 0:
        status = "PASS"
        detail = "Core ML research stack passed the regression harness."
    elif hard_fail_count == 0:
        status = "PASS with warnings"
        detail = "No hard failure, but some optional layers are missing or incomplete."
    else:
        status = "FAIL"
        detail = "At least one hard regression test failed. Do not add advanced models."

    return pd.DataFrame(
        [
            {"Item": "V7.3 harness status", "Status": status, "Detail": detail},
            {"Item": "Passed tests", "Status": "Info", "Detail": f"{pass_count} PASS."},
            {"Item": "Warnings", "Status": "Info", "Detail": f"{warn_count} WARN."},
            {"Item": "Failures", "Status": "Info", "Detail": f"{fail_count} FAIL, including {hard_fail_count} hard failure(s)."},
            {"Item": "Decision Engine", "Status": "Blocked", "Detail": "No integration authorized by this harness."},
            {"Item": "Probability usage", "Status": "Blocked", "Detail": "Raw probabilities remain non-promotable."},
        ]
    )


