def build_ml_current_run_record_v74(
    ticker,
    v50_results,
    v511_results,
    v52_results,
    suite_v53_v63,
    completion_v64_v72,
    test_manifest_v73,
    panel_period="",
    panel_interval="",
    panel_horizon=None,
    panel_pt=None,
    panel_sl=None,
):
    v50_results = _mlqa_safe_dict(v50_results)
    v511_results = _mlqa_safe_dict(v511_results)
    v52_results = _mlqa_safe_dict(v52_results)
    suite_v53_v63 = _mlqa_safe_dict(suite_v53_v63)
    completion_v64_v72 = _mlqa_safe_dict(completion_v64_v72)

    enriched_panel = _mlqa_get_df(v50_results, "enriched_panel")
    shortlist = _mlqa_get_df(v511_results, "shortlist")
    predictions = _mlqa_get_df(v52_results, "predictions")
    folds = _mlqa_get_df(v52_results, "folds")
    cumulative = _mlqa_get_df(v52_results, "cumulative_summary")
    final_manifest = _mlqa_get_df(completion_v64_v72, "final_manifest")

    labels = int(enriched_panel["tb_label"].notna().sum()) if (not enriched_panel.empty and "tb_label" in enriched_panel.columns) else 0
    tickers = int(enriched_panel["ticker"].nunique()) if (not enriched_panel.empty and "ticker" in enriched_panel.columns) else 0
    features = len(shortlist) if not shortlist.empty else 0
    predictions_count = len(predictions) if not predictions.empty else 0
    folds_ok = int((folds["Status"].astype(str) == "OK").sum()) if (not folds.empty and "Status" in folds.columns) else 0
    folds_total = len(folds) if not folds.empty else 0

    top20_return_lift = np.nan
    top20_tp_lift = np.nan
    if not cumulative.empty and "Selection" in cumulative.columns:
        top20 = cumulative[cumulative["Selection"].astype(str).str.contains("Top 20", case=False, na=False)]
        if not top20.empty:
            top20_return_lift = _mlqa_safe_float(top20.iloc[0].get("Return lift vs all"), np.nan)
            top20_tp_lift = _mlqa_safe_float(top20.iloc[0].get("TP lift vs all"), np.nan)

    harness_status = _mlqa_find_status(
        test_manifest_v73,
        key_col_candidates=["Item", "Test"],
        key_value="V7.3 harness status",
        status_col_candidates=["Status"],
    )

    final_status = "Unavailable"
    if not final_manifest.empty:
        status_cols = [c for c in ["Status", "Statut"] if c in final_manifest.columns]
        if status_cols:
            final_status = str(final_manifest[status_cols[0]].iloc[0])

    run_id = datetime.utcnow().strftime("%Y%m%d_%H%M%S")

    return pd.DataFrame(
        [
            {
                "Run ID": run_id,
                "UTC timestamp": datetime.utcnow().strftime("%Y-%m-%d %H:%M:%S"),
                "Ticker context": str(ticker),
                "Panel period": str(panel_period),
                "Panel interval": str(panel_interval),
                "Horizon": panel_horizon,
                "TP ATR": panel_pt,
                "SL ATR": panel_sl,
                "Tickers": tickers,
                "Labels": labels,
                "Shortlist features": features,
                "OOS predictions": predictions_count,
                "Folds OK": folds_ok,
                "Folds total": folds_total,
                "Top20 TP lift": top20_tp_lift,
                "Top20 return lift": top20_return_lift,
                "Harness status": harness_status,
                "Final guardrail status": final_status,
                "Decision Engine": "Blocked",
                "Probability usage": "Blocked",
            }
        ]
    )


def build_ml_run_comparison_v74(run_registry):
    registry = _mlqa_safe_df(run_registry)
    if registry.empty:
        return pd.DataFrame()

    numeric_cols = ["Labels", "Shortlist features", "OOS predictions", "Folds OK", "Folds total", "Top20 TP lift", "Top20 return lift"]
    for col in numeric_cols:
        if col in registry.columns:
            registry[col] = pd.to_numeric(registry[col], errors="coerce")

    rows = []
    for _, row in registry.iterrows():
        folds_total = _mlqa_safe_float(row.get("Folds total"), 0) or 0
        folds_ok = _mlqa_safe_float(row.get("Folds OK"), 0) or 0
        fold_pass_rate = folds_ok / folds_total if folds_total else np.nan
        top20_ret = _mlqa_safe_float(row.get("Top20 return lift"), np.nan)
        top20_tp = _mlqa_safe_float(row.get("Top20 TP lift"), np.nan)
        harness_status = str(row.get("Harness status", "Unavailable"))

        if harness_status.startswith("PASS") and not pd.isna(top20_ret) and top20_ret > 0 and not pd.isna(top20_tp) and top20_tp > 0:
            verdict = "Research constructive"
        elif harness_status.startswith("PASS"):
            verdict = "Infrastructure OK / edge weak"
        elif harness_status == "Unavailable":
            verdict = "Incomplete"
        else:
            verdict = "Rejected"

        out = row.to_dict()
        out["Fold pass rate"] = fold_pass_rate
        out["Run verdict"] = verdict
        rows.append(out)

    out = pd.DataFrame(rows)
    if out.empty:
        return out
    return out.sort_values(["Run verdict", "Top20 return lift", "Top20 TP lift"], ascending=[True, False, False])


