# V7.5 — ENHANCED SHADOW BACKTEST BRIDGE
# ============================================================

def _mlqa_max_drawdown_from_returns(returns):
    r = pd.to_numeric(pd.Series(returns), errors="coerce").fillna(0.0)
    if r.empty:
        return np.nan
    equity = (1.0 + r).cumprod()
    peak = equity.cummax()
    dd = equity / peak.replace(0, np.nan) - 1.0
    return float(dd.min()) if not dd.empty else np.nan


def _mlqa_turnover_proxy(selection_frame):
    if selection_frame is None or selection_frame.empty:
        return np.nan
    required = ["date", "ticker"]
    if any(col not in selection_frame.columns for col in required):
        return np.nan
    work = selection_frame.copy()
    work["date"] = pd.to_datetime(work["date"], errors="coerce")
    work = work.dropna(subset=["date", "ticker"]).sort_values("date")
    if work.empty:
        return np.nan
    previous = set()
    turnovers = []
    for _, group in work.groupby("date"):
        current = set(group["ticker"].astype(str).tolist())
        if previous:
            union = current.union(previous)
            symmetric_diff = current.symmetric_difference(previous)
            turnovers.append(len(symmetric_diff) / len(union) if union else 0.0)
        previous = current
    return float(np.mean(turnovers)) if turnovers else 0.0


def build_enhanced_shadow_policy_metrics_v75(
    predictions,
    cost_bps=5.0,
    slippage_bps=5.0,
):
    """
    Enhanced shadow policy bridge.
    Uses existing OOS predictions only. It creates proxy metrics, not executable signals.
    """
    predictions = _mlqa_safe_df(predictions)
    if predictions.empty:
        return pd.DataFrame(), pd.DataFrame(), pd.DataFrame(), pd.DataFrame()

    required = ["date", "ticker", "Fold", "rank_pct_in_fold", "y_true_success", "tb_return", "tb_mfe", "tb_mae"]
    if any(col not in predictions.columns for col in required):
        return pd.DataFrame(), pd.DataFrame(), pd.DataFrame(), pd.DataFrame()

    work = predictions.copy()
    work["date"] = pd.to_datetime(work["date"], errors="coerce")
    for col in ["rank_pct_in_fold", "y_true_success", "tb_return", "tb_mfe", "tb_mae"]:
        work[col] = pd.to_numeric(work[col], errors="coerce")
    work = work.dropna(subset=["date", "ticker", "Fold", "rank_pct_in_fold", "y_true_success", "tb_return"])

    if work.empty:
        return pd.DataFrame(), pd.DataFrame(), pd.DataFrame(), pd.DataFrame()

    total_cost = (float(cost_bps) + float(slippage_bps)) / 10000.0

    selections = [
        ("Top 10% shadow", work["rank_pct_in_fold"] >= 0.90),
        ("Top 20% shadow", work["rank_pct_in_fold"] >= 0.80),
        ("Top 30% shadow", work["rank_pct_in_fold"] >= 0.70),
        ("Middle 40% shadow", (work["rank_pct_in_fold"] > 0.30) & (work["rank_pct_in_fold"] < 0.70)),
        ("Bottom 20% shadow", work["rank_pct_in_fold"] <= 0.20),
        ("All OOS", work["rank_pct_in_fold"] >= 0.00),
    ]

    metric_rows = []
    fold_rows = []
    ticker_rows = []
    daily_rows = []

    all_dates = work[["date", "ticker"]].drop_duplicates()
    possible_slots_by_date = all_dates.groupby("date")["ticker"].nunique()

    for selection_name, mask in selections:
        selected = work.loc[mask].copy()
        if selected.empty:
            continue

        selected["gross_return_proxy"] = selected["tb_return"]
        selected["net_return_proxy"] = selected["tb_return"] - total_cost

        daily = (
            selected.groupby("date", as_index=False)
            .agg(
                selected_count=("ticker", "nunique"),
                gross_return_proxy=("gross_return_proxy", "mean"),
                net_return_proxy=("net_return_proxy", "mean"),
                hit_rate=("y_true_success", "mean"),
            )
            .sort_values("date")
        )
        daily["cum_return_proxy"] = (1.0 + daily["net_return_proxy"].fillna(0.0)).cumprod() - 1.0
        daily["drawdown_proxy"] = (1.0 + daily["cum_return_proxy"]) / (1.0 + daily["cum_return_proxy"]).cummax().replace(0, np.nan) - 1.0
        daily["Selection"] = selection_name
        daily_rows.append(daily)

        fold_stats = (
            selected.groupby("Fold", as_index=False)
            .agg(
                Count=("ticker", "count"),
                Tickers=("ticker", "nunique"),
                Hit_rate=("y_true_success", "mean"),
                Avg_gross_return=("gross_return_proxy", "mean"),
                Avg_net_return=("net_return_proxy", "mean"),
                Avg_MFE=("tb_mfe", "mean"),
                Avg_MAE=("tb_mae", "mean"),
            )
        )
        fold_stats["Selection"] = selection_name
        fold_rows.append(fold_stats)

        ticker_stats = (
            selected.groupby("ticker", as_index=False)
            .agg(
                Count=("ticker", "count"),
                Folds=("Fold", "nunique"),
                Hit_rate=("y_true_success", "mean"),
                Avg_gross_return=("gross_return_proxy", "mean"),
                Avg_net_return=("net_return_proxy", "mean"),
                Avg_MFE=("tb_mfe", "mean"),
                Avg_MAE=("tb_mae", "mean"),
            )
        )
        ticker_stats["Selection"] = selection_name
        ticker_rows.append(ticker_stats)

        returns = selected["net_return_proxy"]
        avg_net = returns.mean()
        vol_proxy = returns.std()
        sharpe_proxy = avg_net / vol_proxy * np.sqrt(252) if vol_proxy and not pd.isna(vol_proxy) and vol_proxy > 0 else np.nan
        max_dd = _mlqa_max_drawdown_from_returns(daily["net_return_proxy"])
        exposure_proxy = float((daily.set_index("date")["selected_count"] / possible_slots_by_date).replace([np.inf, -np.inf], np.nan).mean()) if not daily.empty else np.nan
        turnover_proxy = _mlqa_turnover_proxy(selected)

        best_fold = np.nan
        worst_fold = np.nan
        if not fold_stats.empty:
            best_fold = int(fold_stats.sort_values("Avg_net_return", ascending=False).iloc[0]["Fold"])
            worst_fold = int(fold_stats.sort_values("Avg_net_return", ascending=True).iloc[0]["Fold"])

        metric_rows.append(
            {
                "Selection": selection_name,
                "Count": len(selected),
                "Tickers": selected["ticker"].nunique(),
                "Folds": selected["Fold"].nunique(),
                "Hit rate": selected["y_true_success"].mean(),
                "Avg gross return": selected["gross_return_proxy"].mean(),
                "Avg net return proxy": avg_net,
                "Cost bps": float(cost_bps),
                "Slippage bps": float(slippage_bps),
                "Vol proxy": vol_proxy,
                "Sharpe proxy": sharpe_proxy,
                "Max drawdown proxy": max_dd,
                "Exposure proxy": exposure_proxy,
                "Turnover proxy": turnover_proxy,
                "Best fold": best_fold,
                "Worst fold": worst_fold,
                "Avg MFE": selected["tb_mfe"].mean(),
                "Avg MAE": selected["tb_mae"].mean(),
            }
        )

    metrics = pd.DataFrame(metric_rows)
    folds = pd.concat(fold_rows, ignore_index=True) if fold_rows else pd.DataFrame()
    tickers = pd.concat(ticker_rows, ignore_index=True) if ticker_rows else pd.DataFrame()
    daily = pd.concat(daily_rows, ignore_index=True) if daily_rows else pd.DataFrame()

    return metrics, folds, tickers, daily


def build_enhanced_shadow_manifest_v75(metrics):
    metrics = _mlqa_safe_df(metrics)
    if metrics.empty:
        return pd.DataFrame(
            [
                {"Item": "V7.5 shadow bridge", "Status": "Unavailable", "Detail": "No shadow metrics available."},
                {"Item": "Decision Engine", "Status": "Blocked", "Detail": "No integration."},
            ]
        )

    top20 = metrics[metrics["Selection"] == "Top 20% shadow"] if "Selection" in metrics.columns else pd.DataFrame()
    if top20.empty:
        policy_status = "Unavailable"
        detail = "Top20 shadow policy missing."
    else:
        row = top20.iloc[0]
        avg_net = _mlqa_safe_float(row.get("Avg net return proxy"), np.nan)
        max_dd = _mlqa_safe_float(row.get("Max drawdown proxy"), np.nan)
        turnover = _mlqa_safe_float(row.get("Turnover proxy"), np.nan)
        if not pd.isna(avg_net) and avg_net > 0 and (pd.isna(max_dd) or max_dd > -0.25):
            policy_status = "Research constructive"
        elif not pd.isna(avg_net) and avg_net > 0:
            policy_status = "Watchlist"
        else:
            policy_status = "Weak"
        detail = f"Top20 net return proxy {_mlqa_fmt_pct(avg_net)}, max DD {_mlqa_fmt_pct(max_dd)}, turnover {_mlqa_fmt_pct(turnover)}."

    return pd.DataFrame(
        [
            {"Item": "V7.5 enhanced shadow bridge", "Status": policy_status, "Detail": detail},
            {"Item": "Execution realism", "Status": "Proxy only", "Detail": "Costs and slippage are proxy deductions, not broker-level execution simulation."},
            {"Item": "Decision Engine", "Status": "Blocked", "Detail": "No BUY/SELL signal. No production integration."},
            {"Item": "Probability usage", "Status": "Blocked", "Detail": "Rank-only shadow interpretation remains enforced."},
        ]
    )


