def make_ml_research_report_zip_v76(report_dict):
    report_dict = _mlqa_safe_dict(report_dict)
    buffer = io.BytesIO()
    with zipfile.ZipFile(buffer, mode="w", compression=zipfile.ZIP_DEFLATED) as zf:
        for name, df in report_dict.items():
            safe_df = _mlqa_safe_df(df)
            if safe_df.empty:
                continue
            zf.writestr(f"{name}.csv", safe_df.to_csv(index=False))
    buffer.seek(0)
    return buffer.getvalue()


