def build_advanced_model_lab_preflight_v80(test_manifest_v73, run_comparison_v74, shadow_manifest_v75):
    test_manifest_v73 = _mlqa_safe_df(test_manifest_v73)
    run_comparison_v74 = _mlqa_safe_df(run_comparison_v74)
    shadow_manifest_v75 = _mlqa_safe_df(shadow_manifest_v75)

    harness_status = _mlqa_find_status(
        test_manifest_v73,
        key_col_candidates=["Item"],
        key_value="V7.3 harness status",
        status_col_candidates=["Status"],
    )

    constructive_runs = 0
    if not run_comparison_v74.empty and "Run verdict" in run_comparison_v74.columns:
        constructive_runs = int(run_comparison_v74["Run verdict"].astype(str).str.contains("Research constructive", case=False, na=False).sum())

    shadow_status = _mlqa_find_status(
        shadow_manifest_v75,
        key_col_candidates=["Item"],
        key_value="V7.5 enhanced shadow bridge",
        status_col_candidates=["Status"],
    )

    blocked_reasons = []
    if not str(harness_status).startswith("PASS"):
        blocked_reasons.append("V7.3 harness not clean")
    if constructive_runs < 2:
        blocked_reasons.append("less than two constructive saved runs")
    if shadow_status not in ["Research constructive"]:
        blocked_reasons.append("V7.5 shadow bridge not constructive")

    if blocked_reasons:
        eligibility = "Blocked"
        detail = "Blocked reasons: " + ", ".join(blocked_reasons) + "."
    else:
        eligibility = "Research lab allowed"
        detail = "Advanced models may be tested in isolated research mode only."

    return pd.DataFrame(
        [
            {"Gate item": "V7.3 harness", "Status": harness_status, "Detail": "Must pass before any advanced model."},
            {"Gate item": "Saved constructive runs", "Status": str(constructive_runs), "Detail": "Need at least 2 across parameters/universes."},
            {"Gate item": "V7.5 shadow bridge", "Status": shadow_status, "Detail": "Must be constructive after costs/slippage proxy."},
            {"Gate item": "Advanced model eligibility", "Status": eligibility, "Detail": detail},
            {"Gate item": "Decision Engine", "Status": "Blocked", "Detail": "Advanced Model Lab cannot connect to Decision Engine."},
            {"Gate item": "Probability usage", "Status": "Blocked", "Detail": "Advanced models cannot expose tradable probabilities."},
        ]
    )


