def run_v73_to_v80_ml_qa_completion_suite(
    ticker,
    v50_results=None,
    v511_results=None,
    v52_results=None,
    suite_v53_v63=None,
    completion_v64_v72=None,
    panel_period="",
    panel_interval="",
    panel_horizon=None,
    panel_pt=None,
    panel_sl=None,
    cost_bps=5.0,
    slippage_bps=5.0,
    existing_run_registry=None,
):
    v50_results = _mlqa_safe_dict(v50_results)
    v511_results = _mlqa_safe_dict(v511_results)
    v52_results = _mlqa_safe_dict(v52_results)
    suite_v53_v63 = _mlqa_safe_dict(suite_v53_v63)
    completion_v64_v72 = _mlqa_safe_dict(completion_v64_v72)

    tests_v73 = build_ml_regression_test_harness_v73(
        v50_results=v50_results,
        v511_results=v511_results,
        v52_results=v52_results,
        suite_v53_v63=suite_v53_v63,
        completion_v64_v72=completion_v64_v72,
    )
    manifest_v73 = build_ml_regression_test_manifest_v73(tests_v73)

    current_run_v74 = build_ml_current_run_record_v74(
        ticker=ticker,
        v50_results=v50_results,
        v511_results=v511_results,
        v52_results=v52_results,
        suite_v53_v63=suite_v53_v63,
        completion_v64_v72=completion_v64_v72,
        test_manifest_v73=manifest_v73,
        panel_period=panel_period,
        panel_interval=panel_interval,
        panel_horizon=panel_horizon,
        panel_pt=panel_pt,
        panel_sl=panel_sl,
    )

    registry = _mlqa_safe_df(existing_run_registry)
    if registry.empty:
        registry_with_current = current_run_v74.copy()
    else:
        registry_with_current = pd.concat([registry, current_run_v74], ignore_index=True)
        if "Run ID" in registry_with_current.columns:
            registry_with_current = registry_with_current.drop_duplicates(subset=["Run ID"], keep="last")

    comparison_v74 = build_ml_run_comparison_v74(registry_with_current)

    predictions_v52 = _mlqa_get_df(v52_results, "predictions")
    shadow_metrics_v75, shadow_folds_v75, shadow_tickers_v75, shadow_daily_v75 = build_enhanced_shadow_policy_metrics_v75(
        predictions=predictions_v52,
        cost_bps=cost_bps,
        slippage_bps=slippage_bps,
    )
    shadow_manifest_v75 = build_enhanced_shadow_manifest_v75(shadow_metrics_v75)

    report_v76 = build_ml_research_evidence_report_v76(
        ticker=ticker,
        v50_results=v50_results,
        v511_results=v511_results,
        v52_results=v52_results,
        suite_v53_v63=suite_v53_v63,
        completion_v64_v72=completion_v64_v72,
        test_manifest_v73=manifest_v73,
        shadow_manifest_v75=shadow_manifest_v75,
        current_run_v74=current_run_v74,
    )

    signature_v77 = build_ml_feature_store_signature_v77(
        ticker=ticker,
        v50_results=v50_results,
        v511_results=v511_results,
        v52_results=v52_results,
        completion_v64_v72=completion_v64_v72,
        panel_period=panel_period,
        panel_interval=panel_interval,
        panel_horizon=panel_horizon,
        panel_pt=panel_pt,
        panel_sl=panel_sl,
    )
    manifest_v77 = build_ml_feature_store_manifest_v77(signature_v77)

    candidates_v80 = build_advanced_model_candidate_matrix_v80()
    preflight_v80 = build_advanced_model_lab_preflight_v80(
        test_manifest_v73=manifest_v73,
        run_comparison_v74=comparison_v74,
        shadow_manifest_v75=shadow_manifest_v75,
    )

    return {
        "v73": {"tests": tests_v73, "manifest": manifest_v73},
        "v74": {"current_run": current_run_v74, "registry_preview": registry_with_current, "comparison": comparison_v74},
        "v75": {"manifest": shadow_manifest_v75, "metrics": shadow_metrics_v75, "folds": shadow_folds_v75, "tickers": shadow_tickers_v75, "daily": shadow_daily_v75},
        "v76": report_v76,
        "v77": {"signature": signature_v77, "manifest": manifest_v77},
        "v80": {"preflight": preflight_v80, "candidates": candidates_v80},
    }


