# Then paste the render call shown at the bottom inside the Multi-Ticker Panel tab,
# just after render_v73_to_v80_ml_qa_completion_suite_panel(...).
#
# Design doctrine:
# - no Decision Engine integration;
# - no BUY/SELL signal;
# - no exploitable raw probability;
# - no automatic retraining of previous V4/V5/V6/V7 sections;
# - only institutional preflight, model-family readiness, calibration contract,
#   shadow-monitoring protocol, kill-switch and final control gate.


def _ml_adv_safe_df(obj):
    """Return a defensive DataFrame copy."""
    try:
        if isinstance(obj, pd.DataFrame):
            return obj.copy()
        if obj is None:
            return pd.DataFrame()
        return pd.DataFrame(obj)
    except Exception:
        return pd.DataFrame()


def _ml_adv_safe_dict(obj):
    """Return a defensive dict copy."""
    try:
        if isinstance(obj, dict):
            return dict(obj)
        return {}
    except Exception:
        return {}


def _ml_adv_get(container, *path, default=None):
    """Safe nested dict getter."""
    cur = container
    for key in path:
        if not isinstance(cur, dict) or key not in cur:
            return default
        cur = cur.get(key)
    return cur


def _ml_adv_get_df(container, *path):
    """Safe nested DataFrame getter."""
    return _ml_adv_safe_df(_ml_adv_get(container, *path, default=pd.DataFrame()))


def _ml_adv_text_contains(value, tokens):
    text = str(value or "").lower()
    return any(str(tok).lower() in text for tok in tokens)


def _ml_adv_find_row_value(df, key_tokens=None, value_cols=None, fallback="Unknown"):
    """
    Find a status/value in a table using broad token matching.
    Works with the heterogeneous manifests used in V5.3 -> V8.0.
    """
    work = _ml_adv_safe_df(df)
    if work.empty:
        return fallback

    key_tokens = key_tokens or []
    value_cols = value_cols or ["Status", "Statut", "Value", "Decision", "Detail", "Détail"]

    candidate_key_cols = [
        "Item", "Gate item", "Gate", "Decision item", "Control", "Contrôle",
        "Audit item", "Metric", "Layer", "Check", "Test", "Name",
    ]
    candidate_key_cols = [c for c in candidate_key_cols if c in work.columns]

    if not candidate_key_cols:
        candidate_key_cols = list(work.columns[:1])

    for _, row in work.iterrows():
        key_text = " | ".join(str(row.get(c, "")) for c in candidate_key_cols)
        if all(str(tok).lower() in key_text.lower() for tok in key_tokens):
            for col in value_cols:
                if col in work.columns and pd.notna(row.get(col)):
                    return str(row.get(col))
            return str(row.to_dict())

    return fallback


def _ml_adv_format_pct(value):
    try:
        if value is None or pd.isna(value):
            return "N/A"
        return f"{float(value):.2%}"
    except Exception:
        return "N/A"


def _ml_adv_format_num(value):
    try:
        if value is None or pd.isna(value):
            return "N/A"
        return f"{float(value):,.4f}"
    except Exception:
        return "N/A"


def _ml_adv_safe_import_available(module_name):
    try:
        import importlib.util
        return importlib.util.find_spec(module_name) is not None
    except Exception:
        return False


def _ml_adv_make_key(*parts):
    """Streamlit-safe unique key builder."""
    raw = "_".join(str(p) for p in parts if p is not None)
    safe = []
    for ch in raw:
        safe.append(ch if ch.isalnum() else "_")
    return "".join(safe)[:180]


# ------------------------------------------------------------
# V8.1 — Advanced Model Lab lock audit
# ------------------------------------------------------------

def build_v81_advanced_model_lab_lock_audit(v73_v80_results=None, suite_v53_v63=None, completion_v64_v72=None):
    """
    Central lock audit after V8.0.
    It does not train anything. It only decides whether the Advanced Model Lab remains blocked.
    """
    v73_v80_results = _ml_adv_safe_dict(v73_v80_results)
    suite_v53_v63 = _ml_adv_safe_dict(suite_v53_v63)
    completion_v64_v72 = _ml_adv_safe_dict(completion_v64_v72)

    preflight_v80 = _ml_adv_get_df(v73_v80_results, "v80", "preflight")
    tests_v73 = _ml_adv_get_df(v73_v80_results, "v73", "manifest")
    shadow_manifest_v75 = _ml_adv_get_df(v73_v80_results, "v75", "manifest")
    final_manifest_v64 = _ml_adv_get_df(completion_v64_v72, "final_manifest")
    preflight_v70 = _ml_adv_get_df(completion_v64_v72, "v70", "preflight")
    promotion_v62 = _ml_adv_get_df(suite_v53_v63, "v62", "manifest")

    advanced_eligibility = _ml_adv_find_row_value(
        preflight_v80,
        key_tokens=["Advanced", "eligibility"],
        fallback="Blocked",
    )
    harness_status = _ml_adv_find_row_value(
        tests_v73,
        key_tokens=["harness"],
        fallback="Unknown",
    )
    shadow_status = _ml_adv_find_row_value(
        shadow_manifest_v75,
        key_tokens=["shadow"],
        fallback="Unknown",
    )
    preflight70_status = _ml_adv_find_row_value(
        preflight_v70,
        key_tokens=["promotion"],
        fallback="Unknown",
    )
    v62_status = _ml_adv_find_row_value(
        promotion_v62,
        key_tokens=["promotion"],
        fallback="Unknown",
    )

    blockers = []

    if _ml_adv_text_contains(advanced_eligibility, ["blocked", "rejected", "fail"]):
        blockers.append("V8.0 advanced eligibility not open")
    if not _ml_adv_text_contains(harness_status, ["pass", "ok"]):
        blockers.append("V7.3 regression harness not clean")
    if not _ml_adv_text_contains(shadow_status, ["constructive", "ok", "pass"]):
        blockers.append("V7.5 shadow bridge not constructive")
    if _ml_adv_text_contains(preflight70_status, ["blocked", "rejected", "fail"]):
        blockers.append("V7.0 promotion preflight blocked")
    if _ml_adv_text_contains(v62_status, ["blocked", "rejected", "fail"]):
        blockers.append("V6.2 promotion gate blocked")

    if blockers:
        lab_status = "Blocked"
        lab_detail = "Blocked reasons: " + "; ".join(dict.fromkeys(blockers)) + "."
    else:
        lab_status = "Isolated research sandbox only"
        lab_detail = "Advanced model tests may be designed, but still no probability, no signal, no Decision Engine."

    rows = [
        {
            "Control": "V8.0 advanced model eligibility",
            "Status": advanced_eligibility,
            "Detail": "Inherited from V8.0 preflight.",
        },
        {
            "Control": "V7.3 regression harness",
            "Status": harness_status,
            "Detail": "Must be clean before any advanced model family is tested.",
        },
        {
            "Control": "V7.5 shadow bridge",
            "Status": shadow_status,
            "Detail": "Must be constructive after cost/slippage proxy.",
        },
        {
            "Control": "V7.0 / V6.2 promotion gates",
            "Status": f"V7.0={preflight70_status} · V6.2={v62_status}",
            "Detail": "Any promotion blockage keeps advanced models in research-only mode.",
        },
        {
            "Control": "Advanced Model Lab state",
            "Status": lab_status,
            "Detail": lab_detail,
        },
        {
            "Control": "Probability usage",
            "Status": "Hard blocked",
            "Detail": "Raw model output must not be displayed or interpreted as tradable probability.",
        },
        {
            "Control": "Decision Engine",
            "Status": "Hard blocked",
            "Detail": "No connection, no routing, no BUY/SELL impact.",
        },
    ]

    return pd.DataFrame(rows)


