# V8.3 — Probability calibration contract and diagnostics shell
# ------------------------------------------------------------

def _ml_adv_extract_prediction_frame(v52_results=None, suite_v53_v63=None, v73_v80_results=None):
    """Best-effort extraction of OOS prediction tables from previous suites."""
    v52_results = _ml_adv_safe_dict(v52_results)
    suite_v53_v63 = _ml_adv_safe_dict(suite_v53_v63)
    v73_v80_results = _ml_adv_safe_dict(v73_v80_results)

    candidates = [
        _ml_adv_get_df(v52_results, "predictions"),
        _ml_adv_get_df(suite_v53_v63, "v56", "predictions"),
        _ml_adv_get_df(suite_v53_v63, "v52", "predictions"),
        _ml_adv_get_df(v73_v80_results, "v75", "daily"),
    ]

    for df in candidates:
        if not df.empty:
            return df

    return pd.DataFrame()


def build_v83_probability_calibration_contract(v52_results=None, suite_v53_v63=None, v73_v80_results=None):
    """
    Calibration shell. It can compute a rough diagnostic if predictions exist,
    but the result is still blocked from use as a probability.
    """
    preds = _ml_adv_extract_prediction_frame(v52_results, suite_v53_v63, v73_v80_results)

    proba_col = None
    for candidate in ["p_raw", "p_success", "p_success_logistic", "probability", "raw_probability"]:
        if candidate in preds.columns:
            proba_col = candidate
            break

    y_col = None
    for candidate in ["y_true_success", "target", "success", "tb_success"]:
        if candidate in preds.columns:
            y_col = candidate
            break

    diagnostic_rows = []
    ece_value = np.nan
    mce_value = np.nan
    brier_value = np.nan
    count = 0

    if proba_col and y_col:
        work = preds[[proba_col, y_col]].copy()
        work[proba_col] = pd.to_numeric(work[proba_col], errors="coerce")
        work[y_col] = pd.to_numeric(work[y_col], errors="coerce")
        work = work.dropna()
        work = work[(work[proba_col] >= 0) & (work[proba_col] <= 1)]
        count = len(work)

        if count >= 30 and work[y_col].nunique() >= 2:
            try:
                brier_value = brier_score_loss(work[y_col].astype(int), work[proba_col].astype(float))
            except Exception:
                brier_value = np.nan

            bins = pd.cut(
                work[proba_col],
                bins=np.linspace(0, 1, 6),
                include_lowest=True,
                duplicates="drop",
            )
            grouped = work.groupby(bins, observed=False)
            total = len(work)
            weighted_gaps = []
            max_gaps = []
            for _, group in grouped:
                if group.empty:
                    continue
                avg_p = group[proba_col].mean()
                realized = group[y_col].mean()
                gap = abs(avg_p - realized)
                weighted_gaps.append(gap * len(group) / total)
                max_gaps.append(gap)
            ece_value = float(np.sum(weighted_gaps)) if weighted_gaps else np.nan
            mce_value = float(np.max(max_gaps)) if max_gaps else np.nan

    if count == 0:
        data_detail = "No usable OOS prediction/probability table found."
    else:
        data_detail = f"{count:,} OOS rows inspected using {proba_col} vs {y_col}."

    diagnostic_rows.extend(
        [
            {
                "Requirement": "OOS prediction table",
                "Status": "Info" if count > 0 else "Missing",
                "Current diagnostic": data_detail,
                "Promotion rule": "Required for any probability calibration study.",
            },
            {
                "Requirement": "Brier score evidence",
                "Status": "Diagnostic only" if not pd.isna(brier_value) else "Missing",
                "Current diagnostic": _ml_adv_format_num(brier_value),
                "Promotion rule": "Must beat dummy and remain stable fold-by-fold.",
            },
            {
                "Requirement": "Expected calibration error",
                "Status": "Diagnostic only" if not pd.isna(ece_value) else "Missing",
                "Current diagnostic": _ml_adv_format_pct(ece_value),
                "Promotion rule": "ECE must be low and stable by fold/ticker/regime.",
            },
            {
                "Requirement": "Maximum calibration error",
                "Status": "Diagnostic only" if not pd.isna(mce_value) else "Missing",
                "Current diagnostic": _ml_adv_format_pct(mce_value),
                "Promotion rule": "MCE must not be driven by one unstable bucket.",
            },
            {
                "Requirement": "Fold-aware calibration",
                "Status": "Blocked",
                "Current diagnostic": "No fold-specific calibrated mapping is approved.",
                "Promotion rule": "Calibration must be fitted inside train folds only, never on global OOS.",
            },
            {
                "Requirement": "Live shadow calibration",
                "Status": "Blocked",
                "Current diagnostic": "No live paper trail yet.",
                "Promotion rule": "Minimum 30-60 live observations before probability interpretation.",
            },
            {
                "Requirement": "Probability exposure",
                "Status": "Hard blocked",
                "Current diagnostic": "Even if diagnostics look good, raw probability stays hidden.",
                "Promotion rule": "No displayed tradable probability before a separate production approval gate.",
            },
        ]
    )

    return pd.DataFrame(diagnostic_rows)


