    v52_results = _ml_adv_safe_dict(v52_results) or _ml_adv_safe_dict(st.session_state.get(f"ml_v52_results_cache_{ticker}", {}))
    suite_v53_v63 = _ml_adv_safe_dict(suite_v53_v63) or _ml_adv_safe_dict(st.session_state.get(f"ml_v53_v63_results_cache_{ticker}", {}))
