    if not lock_v81.empty:
        st.subheader("V8.1 — Advanced Model Lab lock audit")
        st.dataframe(lock_v81, width="stretch", hide_index=True)

    if not matrix_v82.empty:
        st.subheader("V8.2 — Advanced model family readiness")
        st.dataframe(matrix_v82, width="stretch", hide_index=True)

    if not calibration_v83.empty:
        st.subheader("V8.3 — Probability calibration contract")
        st.dataframe(calibration_v83, width="stretch", hide_index=True)

    if not monitoring_v84.empty:
        st.subheader("V8.4 — Shadow live monitoring protocol")
        st.dataframe(monitoring_v84, width="stretch", hide_index=True)

    if not contract_v85.empty:
        st.subheader("V8.5 — Decision Engine integration contract")
        st.dataframe(contract_v85, width="stretch", hide_index=True)

    if not quarantine_v86.empty:
        st.subheader("V8.6 — Quarantine / kill-switch protocol")
        st.dataframe(quarantine_v86, width="stretch", hide_index=True)

    if not gate_v87.empty:
        st.subheader("V8.7 — Final advanced-model control gate")
        st.dataframe(gate_v87, width="stretch", hide_index=True)

    final_status = _ml_adv_find_row_value(
        gate_v87,
        key_tokens=["Advanced", "final", "status"],
        fallback="Blocked",
    )

    if _ml_adv_text_contains(final_status, ["blocked"]):
        st.warning(
            "V8.1 -> V8.7 confirme le blocage : aucun modèle avancé, aucune probabilité exploitable, "
            "aucun signal, aucune intégration Decision Engine."
        )
    else:
        st.warning(
            "V8.1 -> V8.7 autorise au maximum un design de sandbox isolé. "
            "Le Decision Engine reste OFF et les probabilités restent bloquées."
        )


