# - no BUY/SELL signal;
# - no Decision Engine integration;
# - no button / no heavy rerun: this panel only audits existing caches and produces a preflight plan.


import numpy as np
import pandas as pd
try:
    import streamlit as st
except Exception:
    st = None


def _mlpf_safe_df(obj):
    """Return a defensive DataFrame copy without throwing."""
    try:
        if isinstance(obj, pd.DataFrame):
            return obj.copy()
        if obj is None:
            return pd.DataFrame()
        return pd.DataFrame(obj)
    except Exception:
        return pd.DataFrame()


def _mlpf_safe_dict(obj):
    """Return a defensive dict copy without throwing."""
    try:
        if isinstance(obj, dict):
            return dict(obj)
        return {}
    except Exception:
        return {}


def _mlpf_get(container, *path, default=None):
    """Safe nested dict getter."""
    cur = container
    for key in path:
        if not isinstance(cur, dict):
            return default
        if key not in cur:
            return default
        cur = cur.get(key)
    return cur


def _mlpf_get_df(container, *path):
    """Safe nested dict -> DataFrame getter."""
    return _mlpf_safe_df(_mlpf_get(container, *path, default=pd.DataFrame()))


def _mlpf_text(value):
    try:
        if value is None:
            return ""
        return str(value)
    except Exception:
        return ""


def _mlpf_has(value, tokens):
    text = _mlpf_text(value).lower()
    return any(str(tok).lower() in text for tok in tokens)


def _mlpf_all_has(value, tokens):
    text = _mlpf_text(value).lower()
    return all(str(tok).lower() in text for tok in tokens)


def _mlpf_float(value, default=None):
    try:
        if value is None:
            return default
        if pd.isna(value):
            return default
        return float(value)
    except Exception:
        return default


def _mlpf_int(value, default=0):
    try:
        if value is None:
            return default
        if pd.isna(value):
            return default
        return int(float(value))
    except Exception:
        return default


def _mlpf_pct(value):
    try:
        v = _mlpf_float(value)
        if v is None:
            return "N/A"
        return f"{v:.2%}"
    except Exception:
        return "N/A"


def _mlpf_num(value, digits=4):
    try:
        v = _mlpf_float(value)
        if v is None:
            return "N/A"
        return f"{v:,.{int(digits)}f}"
    except Exception:
        return "N/A"


def _mlpf_import_available(module_name):
    try:
        import importlib.util
        return importlib.util.find_spec(str(module_name)) is not None
    except Exception:
        return False


def _mlpf_find_row_value(df, key_tokens=None, value_cols=None, fallback="Unknown"):
    """
    Find a value/status inside heterogeneous manifest tables.
    The ML Lab uses both English and French table schemas, so this matcher is deliberately broad.
    """
    work = _mlpf_safe_df(df)
    if work.empty:
        return fallback

    key_tokens = key_tokens or []
    value_cols = value_cols or [
        "Status", "Statut", "Value", "Decision", "Eligibility", "Detail", "Détail", "Rule", "Verdict",
    ]

    key_cols = [
        "Item", "Gate item", "Gate", "Decision item", "Control", "Contrôle", "Audit item",
        "Metric", "Layer", "Check", "Test", "Name", "Guardrail", "Action",
    ]
    key_cols = [c for c in key_cols if c in work.columns]
    if not key_cols:
        key_cols = list(work.columns[:1])

    for _, row in work.iterrows():
        haystack = " | ".join(_mlpf_text(row.get(c, "")) for c in key_cols)
        if all(str(tok).lower() in haystack.lower() for tok in key_tokens):
            for col in value_cols:
                if col in work.columns and pd.notna(row.get(col)):
                    return _mlpf_text(row.get(col))
            return _mlpf_text(row.to_dict())

    return fallback


def _mlpf_get_feature_usage_count(feature_usage):
    work = _mlpf_safe_df(feature_usage)
    if work.empty:
        return 0

    for col in ["Feature", "Column", "Feature used", "feature", "column"]:
        if col in work.columns:
            return int(work[col].dropna().astype(str).nunique())

    return int(len(work))


def _mlpf_count_positive_folds(folds_df, return_col="Top20 return lift"):
    folds = _mlpf_safe_df(folds_df)
    if folds.empty or return_col not in folds.columns:
        return 0, 0
    ok = folds.copy()
    if "Status" in ok.columns:
        ok = ok[ok["Status"].astype(str).str.upper().eq("OK")]
    if ok.empty:
        return 0, 0
    values = pd.to_numeric(ok[return_col], errors="coerce")
    return int((values > 0).sum()), int(values.notna().sum())


def _mlpf_display_copy(df, pct_cols=None, num_cols=None, date_cols=None):
    """Create a display-safe formatted DataFrame without modifying source."""
    work = _mlpf_safe_df(df)
    if work.empty:
        return work

    pct_cols = pct_cols or []
    num_cols = num_cols or []
    date_cols = date_cols or []

    for col in date_cols:
        if col in work.columns:
            work[col] = pd.to_datetime(work[col], errors="coerce").dt.strftime("%Y-%m-%d")

    for col in pct_cols:
        if col in work.columns:
            work[col] = work[col].apply(_mlpf_pct)

    for col in num_cols:
        if col in work.columns:
            work[col] = work[col].apply(lambda x: _mlpf_num(x, 4))

    return work


