# V8.8 — Advanced model data preflight
# ------------------------------------------------------------

def build_v88_advanced_model_data_preflight(
    v50_results=None,
    v511_results=None,
    v52_results=None,
    suite_v53_v63=None,
    completion_v64_v72=None,
    v73_v80_results=None,
    v81_v87_results=None,
):
    """
    Preflight data/scope gate for any future advanced model.
    It does not train a model. It only audits whether the current evidence stack is sufficient.
    """
    v50_results = _mlpf_safe_dict(v50_results)
    v511_results = _mlpf_safe_dict(v511_results)
    v52_results = _mlpf_safe_dict(v52_results)
    suite_v53_v63 = _mlpf_safe_dict(suite_v53_v63)
    completion_v64_v72 = _mlpf_safe_dict(completion_v64_v72)
    v73_v80_results = _mlpf_safe_dict(v73_v80_results)
    v81_v87_results = _mlpf_safe_dict(v81_v87_results)

    enriched_panel = _mlpf_safe_df(v50_results.get("enriched_panel", pd.DataFrame()))
    shortlist = _mlpf_safe_df(v511_results.get("shortlist", pd.DataFrame()))
    predictions = _mlpf_safe_df(v52_results.get("predictions", pd.DataFrame()))
    folds = _mlpf_safe_df(v52_results.get("folds", pd.DataFrame()))
    feature_usage = _mlpf_safe_df(v52_results.get("feature_usage", pd.DataFrame()))
    cumulative = _mlpf_safe_df(v52_results.get("cumulative_summary", pd.DataFrame()))
    ticker_breakdown = _mlpf_safe_df(v52_results.get("ticker_breakdown", pd.DataFrame()))

    v87_gate = _mlpf_get_df(v81_v87_results, "v87", "final_gate")
    v81_lock = _mlpf_get_df(v81_v87_results, "v81", "lock_audit")
    v80_preflight = _mlpf_get_df(v73_v80_results, "v80", "preflight")

    feature_count = _mlpf_get_feature_usage_count(feature_usage)
    shortlist_count = len(shortlist) if not shortlist.empty else 0
    prediction_count = len(predictions) if not predictions.empty else 0
    ticker_count = predictions["ticker"].nunique() if "ticker" in predictions.columns and not predictions.empty else 0

    ok_folds = 0
    total_folds = 0
    if not folds.empty:
        total_folds = len(folds)
        if "Status" in folds.columns:
            ok_folds = int(folds["Status"].astype(str).str.upper().eq("OK").sum())
        else:
            ok_folds = total_folds

    positive_return_folds, measured_return_folds = _mlpf_count_positive_folds(folds, "Top20 return lift")
    positive_spread_folds, measured_spread_folds = _mlpf_count_positive_folds(folds, "Top20 minus Bottom20")

    top20_return_lift = None
    top20_tp_lift = None
    if not cumulative.empty and "Selection" in cumulative.columns:
        top20 = cumulative[cumulative["Selection"].astype(str).str.contains("Top 20", case=False, na=False)].copy()
        if not top20.empty:
            top20_return_lift = _mlpf_float(top20.iloc[0].get("Return lift vs all"))
            top20_tp_lift = _mlpf_float(top20.iloc[0].get("TP lift vs all"))

    v87_status = _mlpf_find_row_value(v87_gate, key_tokens=["Final"], fallback="Missing")
    v81_state = _mlpf_find_row_value(v81_lock, key_tokens=["Advanced", "Lab", "state"], fallback="Missing")
    v80_status = _mlpf_find_row_value(v80_preflight, key_tokens=["Advanced"], fallback="Missing")

    rows = []

    rows.append({
        "Preflight item": "V8.7 final advanced gate",
        "Status": "Blocked" if _mlpf_has(v87_status, ["blocked", "rejected", "fail", "missing"]) else "Info",
        "Value": v87_status,
        "Institutional interpretation": "Inherited final gate. Any block keeps advanced models non-promouvable.",
    })

    rows.append({
        "Preflight item": "V8.1 lab state",
        "Status": "Blocked" if _mlpf_has(v81_state, ["blocked", "missing", "hard"]) else "Info",
        "Value": v81_state,
        "Institutional interpretation": "Advanced model lab may only open as isolated research sandbox if upstream gates allow it.",
    })

    rows.append({
        "Preflight item": "V8.0 preflight status",
        "Status": "Blocked" if _mlpf_has(v80_status, ["blocked", "rejected", "fail", "missing"]) else "Info",
        "Value": v80_status,
        "Institutional interpretation": "V8.0 must not be contradicted by a later advanced-model section.",
    })

    rows.append({
        "Preflight item": "OOS prediction sample",
        "Status": "OK" if prediction_count >= 1000 else ("Watch" if prediction_count >= 300 else "Insufficient"),
        "Value": f"{prediction_count:,} rows",
        "Institutional interpretation": "Advanced models need a materially larger OOS audit base than the baseline ranker.",
    })

    rows.append({
        "Preflight item": "Ticker coverage",
        "Status": "OK" if ticker_count >= 10 else ("Watch" if ticker_count >= 5 else "Insufficient"),
        "Value": f"{ticker_count} ticker(s)",
        "Institutional interpretation": "Cross-sectional advanced models require broad enough universe coverage.",
    })

    rows.append({
        "Preflight item": "Feature shortlist depth",
        "Status": "OK" if feature_count >= 8 else ("Watch" if feature_count >= 5 else "Insufficient"),
        "Value": f"{feature_count} used feature(s), {shortlist_count} shortlist row(s)",
        "Institutional interpretation": "Do not add nonlinear models if the stable feature shortlist is too thin.",
    })

    rows.append({
        "Preflight item": "Purged OOS fold coverage",
        "Status": "OK" if total_folds > 0 and ok_folds == total_folds else "Watch",
        "Value": f"{ok_folds}/{total_folds} OK fold(s)",
        "Institutional interpretation": "Every advanced candidate must reuse purged/embargoed OOS folds.",
    })

    rows.append({
        "Preflight item": "Top20 return fold consistency",
        "Status": "OK" if measured_return_folds > 0 and positive_return_folds >= max(1, measured_return_folds - 1) else "Weak",
        "Value": f"{positive_return_folds}/{measured_return_folds} positive fold(s)",
        "Institutional interpretation": "Advanced models are blocked if the baseline rank evidence is not fold-consistent.",
    })

    rows.append({
        "Preflight item": "Top20 cumulative edge",
        "Status": "OK" if (top20_return_lift is not None and top20_return_lift > 0 and (top20_tp_lift or 0) > 0) else "Weak",
        "Value": f"TP lift {_mlpf_pct(top20_tp_lift)}, return lift {_mlpf_pct(top20_return_lift)}",
        "Institutional interpretation": "A nonlinear model cannot repair absent economic lift without new evidence.",
    })

    rows.append({
        "Preflight item": "Panel availability",
        "Status": "OK" if not enriched_panel.empty else "Missing",
        "Value": f"{len(enriched_panel):,} enriched row(s)",
        "Institutional interpretation": "Needed only for future offline training design; no training is performed here.",
    })

    rows.append({
        "Preflight item": "Decision Engine",
        "Status": "Hard blocked",
        "Value": "No integration",
        "Institutional interpretation": "No advanced-model output can reach the Decision Engine from this lab.",
    })

    return pd.DataFrame(rows)


