# V8.9 — Advanced model family feasibility matrix
# ------------------------------------------------------------

def build_v89_advanced_model_family_feasibility(v88_preflight=None):
    """
    Feasibility matrix for future advanced models.
    This is not a training runner and does not instantiate heavy models.
    """
    preflight = _mlpf_safe_df(v88_preflight)

    hard_block = False
    if not preflight.empty and "Status" in preflight.columns:
        hard_block = bool(
            preflight["Status"].astype(str).str.contains("Hard blocked|Blocked|Insufficient", case=False, na=False).any()
        )

    sample_status = _mlpf_find_row_value(preflight, key_tokens=["OOS", "prediction"], value_cols=["Status"], fallback="Unknown")
    feature_status = _mlpf_find_row_value(preflight, key_tokens=["Feature", "shortlist"], value_cols=["Status"], fallback="Unknown")
    fold_status = _mlpf_find_row_value(preflight, key_tokens=["fold", "coverage"], value_cols=["Status"], fallback="Unknown")
    edge_status = _mlpf_find_row_value(preflight, key_tokens=["cumulative", "edge"], value_cols=["Status"], fallback="Unknown")

    families = [
        {
            "Model family": "Elastic-Net Logistic",
            "Dependency": "sklearn",
            "Installed": _mlpf_import_available("sklearn"),
            "Complexity": "Low",
            "Primary purpose": "Sparse linear benchmark after feature pruning.",
            "Main risk": "Underfitting if edge is nonlinear.",
            "Minimum evidence before sandbox": "Clean folds + stable shortlist + positive Top20 edge.",
        },
        {
            "Model family": "Calibrated Logistic",
            "Dependency": "sklearn",
            "Installed": _mlpf_import_available("sklearn"),
            "Complexity": "Low / medium",
            "Primary purpose": "Calibration experiment only after ranking proves stable.",
            "Main risk": "False sense of probability if fold calibration is unstable.",
            "Minimum evidence before sandbox": "ECE/Brier improvement on purged calibration folds.",
        },
        {
            "Model family": "Random Forest",
            "Dependency": "sklearn",
            "Installed": _mlpf_import_available("sklearn"),
            "Complexity": "Medium",
            "Primary purpose": "Nonlinear interaction benchmark with conservative depth.",
            "Main risk": "Cross-sectional overfit and unstable feature importances.",
            "Minimum evidence before sandbox": "More tickers, stable folds, shallow depth grid only.",
        },
        {
            "Model family": "Extra Trees",
            "Dependency": "sklearn",
            "Installed": _mlpf_import_available("sklearn"),
            "Complexity": "Medium",
            "Primary purpose": "Variance-reduced nonlinear benchmark.",
            "Main risk": "Spurious ranking lift from noisy splits.",
            "Minimum evidence before sandbox": "Permutation importance stability and fold lift consistency.",
        },
        {
            "Model family": "HistGradientBoosting",
            "Dependency": "sklearn",
            "Installed": _mlpf_import_available("sklearn"),
            "Complexity": "Medium / high",
            "Primary purpose": "Native sklearn gradient boosting benchmark.",
            "Main risk": "Overfit if early stopping and purge discipline are weak.",
            "Minimum evidence before sandbox": "Nested purged CV + monotonic risk diagnostics.",
        },
        {
            "Model family": "XGBoost",
            "Dependency": "xgboost",
            "Installed": _mlpf_import_available("xgboost"),
            "Complexity": "High",
            "Primary purpose": "Advanced nonlinear candidate after baseline evidence improves.",
            "Main risk": "Hyperparameter mining and leakage through repeated testing.",
            "Minimum evidence before sandbox": "Locked feature set, nested CV, strict trial budget, no probability usage.",
        },
        {
            "Model family": "LightGBM",
            "Dependency": "lightgbm",
            "Installed": _mlpf_import_available("lightgbm"),
            "Complexity": "High",
            "Primary purpose": "Fast tree boosting for larger multi-ticker panels.",
            "Main risk": "Small-sample leaf overfit and unstable rank buckets.",
            "Minimum evidence before sandbox": "Larger universe/history + leaf constraints + stability audit.",
        },
    ]

    rows = []
    for spec in families:
        installed = bool(spec["Installed"])

        if hard_block:
            readiness = "Blocked by upstream gates"
            allowed_action = "Do not train"
        elif not installed:
            readiness = "Dependency missing"
            allowed_action = "Document only"
        elif _mlpf_has(sample_status, ["Insufficient"]) or _mlpf_has(feature_status, ["Insufficient"]):
            readiness = "Data insufficient"
            allowed_action = "Do not train"
        elif _mlpf_has(fold_status, ["Watch", "Weak"]) or _mlpf_has(edge_status, ["Weak"]):
            readiness = "Sandbox design only"
            allowed_action = "Do not train yet"
        else:
            readiness = "Sandbox eligible, not promotable"
            allowed_action = "Offline sandbox only after explicit run block"

        rows.append({
            "Model family": spec["Model family"],
            "Dependency": spec["Dependency"],
            "Installed": "Yes" if installed else "No",
            "Complexity": spec["Complexity"],
            "Primary purpose": spec["Primary purpose"],
            "Main risk": spec["Main risk"],
            "Minimum evidence before sandbox": spec["Minimum evidence before sandbox"],
            "Readiness": readiness,
            "Allowed action": allowed_action,
        })

    return pd.DataFrame(rows)


