# ------------------------------------------------------------

def build_v91_hyperparameter_guardrail_plan(v89_feasibility=None):
    """
    Conservative search-space plan for future advanced models.
    This is a control document, not a fit call.
    """
    feasibility = _mlpf_safe_df(v89_feasibility)

    allowed_families = []
    if not feasibility.empty and "Readiness" in feasibility.columns:
        allowed_families = feasibility.loc[
            ~feasibility["Readiness"].astype(str).str.contains("Blocked|insufficient|missing", case=False, na=False),
            "Model family",
        ].astype(str).tolist() if "Model family" in feasibility.columns else []

    specs = [
        {
            "Model family": "Elastic-Net Logistic",
            "Max trials": 12,
            "Search space": "C=[0.01, 0.03, 0.1, 0.3, 1.0], l1_ratio=[0.05, 0.25, 0.50]",
            "Mandatory constraints": "StandardScaler, median imputer, class_weight audit, coefficient stability by fold.",
        },
        {
            "Model family": "Random Forest",
            "Max trials": 18,
            "Search space": "n_estimators<=300, max_depth<=4, min_samples_leaf>=25, max_features in [sqrt, 0.5]",
            "Mandatory constraints": "No unlimited depth, no small leaves, permutation importance stability required.",
        },
        {
            "Model family": "Extra Trees",
            "Max trials": 18,
            "Search space": "n_estimators<=300, max_depth<=4, min_samples_leaf>=25, bootstrap audit optional",
            "Mandatory constraints": "Same fold protocol as Random Forest; no feature-mining after OOS review.",
        },
        {
            "Model family": "HistGradientBoosting",
            "Max trials": 20,
            "Search space": "max_iter<=250, learning_rate<=0.08, max_leaf_nodes<=15, l2_regularization>=0.01",
            "Mandatory constraints": "Early stopping inside train only; no outer-test-driven tuning.",
        },
        {
            "Model family": "XGBoost",
            "Max trials": 25,
            "Search space": "max_depth<=3, eta<=0.05, subsample<=0.8, colsample<=0.8, min_child_weight>=10",
            "Mandatory constraints": "Only if dependency installed and universe/history expanded; strict trial budget.",
        },
        {
            "Model family": "LightGBM",
            "Max trials": 25,
            "Search space": "num_leaves<=15, learning_rate<=0.05, min_data_in_leaf>=30, feature_fraction<=0.8",
            "Mandatory constraints": "Only if dependency installed and leaf constraints are enforced.",
        },
    ]

    rows = []
    for spec in specs:
        family = spec["Model family"]
        permitted = family in allowed_families
        rows.append({
            "Model family": family,
            "Sandbox permission": "Design only" if not permitted else "Sandbox candidate, still no training in V9.1",
            "Max trials": spec["Max trials"],
            "Search space": spec["Search space"],
            "Mandatory constraints": spec["Mandatory constraints"],
            "Overfit control": "Abort if lift appears in <80% of folds, if Top20-vs-Bottom20 spread fails, or if calibration worsens dummy.",
        })

    return pd.DataFrame(rows)


