def build_v92_calibration_firewall_contract():
    """
    Probability firewall for future advanced models.
    This keeps the project aligned with prior probability-block decisions.
    """
    rows = [
        {
            "Control": "Raw probability display",
            "Status": "Hard blocked",
            "Rule": "Do not display p_raw as a true probability of TP/success.",
            "Required evidence to unlock": "Fold-aware calibration with ECE, Brier improvement, reliability bins, and regime stability.",
        },
        {
            "Control": "Calibration method",
            "Status": "Research only",
            "Rule": "Test Platt/isotonic only inside nested purged folds; never fit calibrator on outer OOS.",
            "Required evidence to unlock": "Consistent calibration improvement vs dummy and vs uncalibrated ranker.",
        },
        {
            "Control": "Probability bins",
            "Status": "Mandatory diagnostic",
            "Rule": "Report realized TP by bin, count by bin, ECE, MCE, Brier and calibration slope.",
            "Required evidence to unlock": "No empty high-confidence bins and no systematic overconfidence.",
        },
        {
            "Control": "Rank-first policy",
            "Status": "Mandatory",
            "Rule": "Advanced models must first beat the baseline on Top20 rank lift and Top20-vs-Bottom20 spread.",
            "Required evidence to unlock": "Positive economic lift, not just AUC.",
        },
        {
            "Control": "Decision Engine connection",
            "Status": "Hard blocked",
            "Rule": "No calibrated probability and no rank score can route into Decision Engine from this lab.",
            "Required evidence to unlock": "Separate governance gate, live shadow log, kill-switch, and multi-universe robustness.",
        },
    ]

    return pd.DataFrame(rows)


# ------------------------------------------------------------
# V9.3 — Final advanced-model preflight decision
# ------------------------------------------------------------

def build_v93_final_advanced_model_preflight_decision(
    v88_preflight=None,
    v89_feasibility=None,
    v90_blueprint=None,
    v91_guardrails=None,
    v92_firewall=None,
):
    """
    Aggregated preflight decision.
    The default remains blocked unless evidence is very clean; even then, only offline sandbox is allowed.
    """
    v88 = _mlpf_safe_df(v88_preflight)
    v89 = _mlpf_safe_df(v89_feasibility)
    v90 = _mlpf_safe_df(v90_blueprint)
    v91 = _mlpf_safe_df(v91_guardrails)
    v92 = _mlpf_safe_df(v92_firewall)

    hard_blockers = []
    warnings = []

    if v88.empty:
        hard_blockers.append("V8.8 preflight missing")
    else:
        for _, row in v88.iterrows():
            item = _mlpf_text(row.get("Preflight item"))
            status = _mlpf_text(row.get("Status"))
            if _mlpf_has(status, ["hard blocked", "blocked", "insufficient", "missing"]):
                hard_blockers.append(f"{item}: {status}")
            elif _mlpf_has(status, ["weak", "watch"]):
                warnings.append(f"{item}: {status}")

    sandbox_candidates = 0
    installed_candidates = 0
    if not v89.empty and "Readiness" in v89.columns:
        installed_candidates = int(v89.get("Installed", pd.Series(dtype=str)).astype(str).str.contains("Yes", case=False, na=False).sum()) if "Installed" in v89.columns else 0
        sandbox_candidates = int(v89["Readiness"].astype(str).str.contains("Sandbox eligible|Sandbox design", case=False, na=False).sum())

    if v90.empty:
        hard_blockers.append("V9.0 nested CV blueprint missing")
    if v91.empty:
        hard_blockers.append("V9.1 hyperparameter guardrails missing")
    if v92.empty:
        hard_blockers.append("V9.2 calibration firewall missing")

    if hard_blockers:
        final_status = "Advanced model blocked"
        final_detail = "Blocked reasons: " + "; ".join(dict.fromkeys(hard_blockers)) + "."
        allowed_next_action = "Do not train advanced models. Expand data/features/universe or fix upstream gates."
    elif sandbox_candidates > 0:
        final_status = "Offline sandbox design allowed"
        final_detail = (
            f"{sandbox_candidates} family/families can be specified for future offline sandbox. "
            "Still no training in this panel, no probability, no signal, no Decision Engine."
        )
        allowed_next_action = "Create a separate offline sandbox runner with nested purged CV and locked trial budget."
    else:
        final_status = "Design only"
        final_detail = "No model family is ready for even sandbox training yet."
        allowed_next_action = "Keep improving evidence stack before model expansion."

    rows = [
        {
            "Decision item": "Advanced model preflight status",
            "Status": final_status,
            "Detail": final_detail,
        },
        {
            "Decision item": "Installed advanced dependencies",
            "Status": "Info",
            "Detail": f"{installed_candidates} installed family/families detected from feasibility matrix.",
        },
        {
            "Decision item": "Sandbox candidate families",
            "Status": "Info" if sandbox_candidates > 0 else "None",
            "Detail": f"{sandbox_candidates} candidate family/families, still non-promouvable.",
        },
        {
            "Decision item": "Warnings",
            "Status": "Info" if warnings else "OK",
            "Detail": "None" if not warnings else "; ".join(dict.fromkeys(warnings)) + ".",
        },
        {
            "Decision item": "Allowed next action",
            "Status": "Research only",
            "Detail": allowed_next_action,
        },
        {
            "Decision item": "Probability usage",
            "Status": "Hard blocked",
            "Detail": "No raw or calibrated probability can be used as an exploitable probability at this stage.",
        },
        {
            "Decision item": "Trading signal",
            "Status": "Hard blocked",
            "Detail": "No BUY/SELL signal. No sizing. No allocation recommendation.",
        },
        {
            "Decision item": "Decision Engine",
            "Status": "Hard blocked",
            "Detail": "No integration path opened by V8.8 -> V9.3.",
        },
    ]

    return pd.DataFrame(rows)


# ------------------------------------------------------------
# Runner + renderer
# ------------------------------------------------------------

def run_v88_to_v93_advanced_model_preflight_lab(
    ticker,
    v50_results=None,
    v511_results=None,
    v52_results=None,
    suite_v53_v63=None,
    completion_v64_v72=None,
    v73_v80_results=None,
    v81_v87_results=None,
    panel_period="",
    panel_interval="",
    panel_horizon=None,
    panel_pt=None,
    panel_sl=None,
):
    """
    Lightweight runner. It builds diagnostics only and performs no model training.
    """
    v88 = build_v88_advanced_model_data_preflight(
        v50_results=v50_results,
        v511_results=v511_results,
        v52_results=v52_results,
        suite_v53_v63=suite_v53_v63,
        completion_v64_v72=completion_v64_v72,
        v73_v80_results=v73_v80_results,
        v81_v87_results=v81_v87_results,
    )
    v89 = build_v89_advanced_model_family_feasibility(v88)
    v90 = build_v90_nested_purged_cv_blueprint(
        panel_period=panel_period,
        panel_interval=panel_interval,
        panel_horizon=panel_horizon,
        panel_pt=panel_pt,
        panel_sl=panel_sl,
    )
    v91 = build_v91_hyperparameter_guardrail_plan(v89)
    v92 = build_v92_calibration_firewall_contract()
    v93 = build_v93_final_advanced_model_preflight_decision(
        v88_preflight=v88,
        v89_feasibility=v89,
        v90_blueprint=v90,
        v91_guardrails=v91,
        v92_firewall=v92,
    )

    return {
        "v88": {"data_preflight": v88},
        "v89": {"family_feasibility": v89},
        "v90": {"nested_cv_blueprint": v90},
        "v91": {"hyperparameter_guardrails": v91},
        "v92": {"calibration_firewall": v92},
        "v93": {"final_preflight_decision": v93},
    }


def render_v88_to_v93_advanced_model_preflight_lab_panel(
    ticker,
    v50_results=None,
    v511_results=None,
    v52_results=None,
    suite_v53_v63=None,
    completion_v64_v72=None,
    v73_v80_results=None,
    v81_v87_results=None,
    panel_period="",
    panel_interval="",
    panel_horizon=None,
    panel_pt=None,
    panel_sl=None,
):
    """
    Streamlit panel for V8.8 -> V9.3.
    No widgets are used on purpose, to avoid DuplicateElementKey and unnecessary reruns.
    """
    st.divider()
    st.subheader("V8.8 -> V9.3 — Advanced Model Preflight Lab")
    st.warning(
        "V8.8 -> V9.3 est read-only et léger : il prépare le cadre LightGBM/XGBoost/Random Forest/boosting, "
        "mais n'entraîne aucun modèle avancé. Aucune probabilité exploitable, aucun signal, aucune intégration Decision Engine."
    )

    v50_results = _mlpf_safe_dict(v50_results) or _mlpf_safe_dict(st.session_state.get(f"ml_v50_results_cache_{ticker}", {}))
    v511_results = _mlpf_safe_dict(v511_results) or _mlpf_safe_dict(st.session_state.get(f"ml_v511_results_cache_{ticker}", {}))
    v52_results = _mlpf_safe_dict(v52_results) or _mlpf_safe_dict(st.session_state.get(f"ml_v52_results_cache_{ticker}", {}))
    suite_v53_v63 = _mlpf_safe_dict(suite_v53_v63) or _mlpf_safe_dict(st.session_state.get(f"ml_v53_v63_results_cache_{ticker}", {}))
    completion_v64_v72 = _mlpf_safe_dict(completion_v64_v72) or _mlpf_safe_dict(st.session_state.get(f"ml_v64_v72_results_cache_{ticker}", {}))
    v73_v80_results = _mlpf_safe_dict(v73_v80_results) or _mlpf_safe_dict(st.session_state.get(f"ml_v73_v80_results_cache_{ticker}", {}))
    v81_v87_results = _mlpf_safe_dict(v81_v87_results) or _mlpf_safe_dict(st.session_state.get(f"ml_v81_v87_results_cache_{ticker}", {}))

    readiness = pd.DataFrame(
        [
            {"Upstream layer": "V5.0 enriched panel", "Cache": f"ml_v50_results_cache_{ticker}", "Status": "OK" if bool(v50_results) else "Missing"},
            {"Upstream layer": "V5.1.1 shortlist", "Cache": f"ml_v511_results_cache_{ticker}", "Status": "OK" if bool(v511_results) else "Missing"},
            {"Upstream layer": "V5.2 enriched ranker", "Cache": f"ml_v52_results_cache_{ticker}", "Status": "OK" if bool(v52_results) else "Missing"},
            {"Upstream layer": "V5.3 -> V6.3 institutional suite", "Cache": f"ml_v53_v63_results_cache_{ticker}", "Status": "OK" if bool(suite_v53_v63) else "Missing"},
            {"Upstream layer": "V6.4 -> V7.2 completion suite", "Cache": f"ml_v64_v72_results_cache_{ticker}", "Status": "OK" if bool(completion_v64_v72) else "Missing"},
            {"Upstream layer": "V7.3 -> V8.0 QA suite", "Cache": f"ml_v73_v80_results_cache_{ticker}", "Status": "OK" if bool(v73_v80_results) else "Missing"},
            {"Upstream layer": "V8.1 -> V8.7 control suite", "Cache": f"ml_v81_v87_results_cache_{ticker}", "Status": "OK" if bool(v81_v87_results) else "Missing"},
        ]
    )

    st.subheader("V8.8 — Upstream readiness")
    st.dataframe(readiness, width="stretch", hide_index=True)

    results = run_v88_to_v93_advanced_model_preflight_lab(
        ticker=ticker,
        v50_results=v50_results,
        v511_results=v511_results,
        v52_results=v52_results,
        suite_v53_v63=suite_v53_v63,
        completion_v64_v72=completion_v64_v72,
        v73_v80_results=v73_v80_results,
        v81_v87_results=v81_v87_results,
        panel_period=panel_period,
        panel_interval=panel_interval,
        panel_horizon=panel_horizon,
        panel_pt=panel_pt,
        panel_sl=panel_sl,
    )

    st.session_state[f"ml_v88_v93_results_cache_{ticker}"] = results

    v88 = _mlpf_get_df(results, "v88", "data_preflight")
    v89 = _mlpf_get_df(results, "v89", "family_feasibility")
    v90 = _mlpf_get_df(results, "v90", "nested_cv_blueprint")
    v91 = _mlpf_get_df(results, "v91", "hyperparameter_guardrails")
    v92 = _mlpf_get_df(results, "v92", "calibration_firewall")
    v93 = _mlpf_get_df(results, "v93", "final_preflight_decision")

    if not v88.empty:
        st.subheader("V8.8 — Advanced model data preflight")
        st.dataframe(v88, width="stretch", hide_index=True)

    if not v89.empty:
        st.subheader("V8.9 — Advanced model family feasibility")
        st.dataframe(v89, width="stretch", hide_index=True)

    if not v90.empty:
        st.subheader("V9.0 — Nested purged CV blueprint")
        st.dataframe(v90, width="stretch", hide_index=True)

    if not v91.empty:
        st.subheader("V9.1 — Hyperparameter / overfit guardrails")
        st.dataframe(v91, width="stretch", hide_index=True)

    if not v92.empty:
        st.subheader("V9.2 — Calibration firewall contract")
        st.dataframe(v92, width="stretch", hide_index=True)

    if not v93.empty:
        st.subheader("V9.3 — Final advanced-model preflight decision")
        st.dataframe(v93, width="stretch", hide_index=True)

    st.info(
        "V8.8 -> V9.3 ne lance aucun modèle avancé. Il produit uniquement un preflight institutionnel : "
        "données, familles candidates, nested CV, hyperparamètres, firewall calibration et décision finale."
    )
    st.warning(
        "Même si une famille devient sandbox-éligible, la promotion reste bloquée : aucune probabilité exploitable, "
        "aucun signal, aucune intégration Decision Engine."
    )



